insert into public.mushroom_lookalikes_i18n
  (edible_slug, lookalike_slug, lang, visual_differences, smell_differences, habitat_differences, spore_print_differences, pro_tip, key_differences, verified)
values
($q1$agaricus_augustus$q1$,$q1$agaricus_xanthodermus$q1$,$q1$en$q1$,$q1$Smell + discolouration at the stem base (anise vs. carbolic; faintly yellow vs. chrome-yellow).$q1$,$q1$Anise (edible) vs. carbolic/ink (poisonous) — the most important criterion$q1$,$q1$both forest/park/garden$q1$,$q1$both chocolate-brown$q1$,$q1$Cut into the stem base: strong chrome-yellow + carbolic smell = Yellow-staining mushroom (Agaricus xanthodermus, poisonous). With white field mushrooms, also rule out a volva (Amanita / deathcap).$q1$,array[$q1$The Prince (Agaricus augustus): anise/almond smell, weak yellowing$q1$,$q1$Yellow-staining mushroom (Agaricus xanthodermus): carbolic/ink smell (intensifies on heating), chrome-yellow stem base$q1$]::text[],true),
($q1$agaricus_campestris$q1$,$q1$amanita_phalloides$q1$,$q1$en$q1$,$q1$Field mushroom: white-beige cap, pink gills that turn brown. Deathcap (Amanita phalloides): olive-green cap, white gills that stay white.$q1$,$q1$Field mushroom: pleasant mushroomy. Deathcap (Amanita phalloides): faintly sweetish.$q1$,$q1$Field mushroom: meadows, pastures. Deathcap (Amanita phalloides): deciduous forest, oaks.$q1$,$q1$Field mushroom: dark brown. Deathcap (Amanita phalloides): white.$q1$,$q1$ALWAYS check the stem base — a bulb in a membranous sac (volva) = NEVER eat!$q1$,array[$q1$Field mushroom NEVER has a bulb in a sac, the deathcap (Amanita phalloides) always does$q1$,$q1$Field mushroom gills turn pink then chocolate-brown, deathcap (Amanita phalloides) gills stay white$q1$]::text[],true),
($q1$amanita_rubescens$q1$,$q1$amanita_pantherina$q1$,$q1$en$q1$,$q1$The reddening test + ring (grooved vs. smooth) + bulb are decisive.$q1$,$q1$barely distinguishable$q1$,$q1$both all forest types$q1$,$q1$both white$q1$,$q1$The Blusher (Amanita rubescens) is for experienced foragers only. Check ALL features TOGETHER (reddening + grooved ring + bulb without a rimmed sheath).$q1$,array[$q1$Blusher (Amanita rubescens): flesh reddens (especially at the stem base / maggot tunnels), grooved ring, grey veil flakes$q1$,$q1$Panther cap (Amanita pantherina): flesh NEVER reddens, smooth ring, pure-white flakes, rimmed-bulbous base, toxins heat-stable$q1$]::text[],true),
($q1$austernpilz$q1$,$q1$galerina_marginata$q1$,$q1$en$q1$,$q1$Oyster mushroom (Pleurotus): shell-/fan-shaped cap 5-25 cm, white/grey/brown, in overlapping tile-like clusters; lateral or absent stem; broad whitish decurrent gills. Deadly galerina (Galerina marginata): small convex ochre- to cinnamon-brown caplet 1-4 cm with a central slender brownish stem, a ring zone in the upper third of the stem, gills turning cinnamon-brown with age.$q1$,$q1$Oyster mushroom (Pleurotus): mild, pleasantly mushroomy-anise-like. Deadly galerina (Galerina marginata): faintly mealy to inconspicuous — smell is NOT a reliable distinguishing feature, so do not rely on it.$q1$,$q1$Both grow on wood, but: the oyster mushroom (Pleurotus) prefers deciduous wood (beech/poplar), growing in clustered, bracket-like form, often high on the trunk; the deadly galerina (Galerina marginata) grows on rotting deadwood (frequently coniferous wood, but also deciduous), small, single to bundled, rather near the ground / on fallen logs.$q1$,$q1$Oyster mushroom (Pleurotus): WHITE to pale lilac-grey. Deadly galerina (Galerina marginata): RUST-/CINNAMON-BROWN. This is the most reliable single feature — the spore print separates the two with certainty.$q1$,$q1$Golden rule: a true oyster mushroom (Pleurotus) sits laterally/stemless as a thick, fleshy bracket on the wood and gives a WHITE to lilac-grey spore print. As soon as there is a central stem with a ring remnant OR the spore print comes out brown, it is NOT an oyster mushroom — then hands off (the deadly galerina, Galerina marginata, contains deadly amatoxins, the same poison as the deathcap). When in doubt, always make a spore print before eating.$q1$,array[$q1$Spore powder: oyster mushroom (Pleurotus) white to lilac-grey; deadly galerina (Galerina marginata) rust-/cinnamon-brown (a spore print on dark + light paper is the most reliable distinguishing feature).$q1$,$q1$Stem: the oyster mushroom (Pleurotus) has a lateral/eccentric, short or almost absent stem and NO ring; the deadly galerina (Galerina marginata) has a central, slender stem with a membranous ring-zone remnant in the upper third.$q1$,$q1$Growth form: the oyster mushroom (Pleurotus) grows in overlapping tile-like fashion in thick, fleshy clusters/brackets directly on the wood; the deadly galerina (Galerina marginata) grows small, single to bundled, with a thin-fleshed, convex caplet on deadwood.$q1$,$q1$Gills: the oyster mushroom (Pleurotus) has broad, whitish gills running down the (lateral) stem; the deadly galerina (Galerina marginata) has narrow gills, pale ochre when young, turning cinnamon-brown with age (due to the brown spore powder).$q1$,$q1$Size/consistency: the oyster mushroom (Pleurotus) is large (cap 5-25 cm), tough-fleshy; the deadly galerina (Galerina marginata) is small (cap mostly 1-4 cm), fragile, with a distinct stem like a normal gilled mushroom.$q1$]::text[],true),
($q1$calocybe_gambosa$q1$,$q1$inocybe_erubescens$q1$,$q1$en$q1$,$q1$Both appear in spring, pale-coloured; the fibrecap (Inocybe erubescens) is radially fibrous/cracked and reddening, the St. George's mushroom (Calocybe gambosa) is smooth-fleshy.$q1$,$q1$St. George's mushroom (Calocybe gambosa) strongly mealy-cucumbery; fibrecap (Inocybe erubescens) sweetish-spermatic$q1$,$q1$both meadows/forest edges, calcareous soil, same season$q1$,$q1$St. George's mushroom (Calocybe gambosa) white, fibrecap (Inocybe erubescens) brown$q1$,$q1$DEADLY (muscarine). White gills + mealy smell + no reddening are mandatory — otherwise hands off.$q1$,array[$q1$St. George's mushroom (Calocybe gambosa): white gills at every age + mealy smell, flesh does NOT redden$q1$,$q1$Fibrecap (Inocybe erubescens): flesh reddens, grey-brown gills, brown spore powder, high muscarine content$q1$]::text[],true),
($q1$champignon-de-paris$q1$,$q1$agaricus_xanthodermus$q1$,$q1$en$q1$,$q1$Yellow-staining mushroom (Karbol-Champignon): the stem base turns immediately chrome-yellow when cut, the cap centre is often greyish-metallic, and the stem base is bulbous without any flap of skin. Cultivated/field mushroom: the cut surface stays whitish to slightly reddish, with no yellow stem base.$q1$,$q1$The yellow-staining mushroom smells pungently of carbolic/phenol/ink (intensified by heating and by rubbing the stem base). Edible mushrooms smell pleasantly mushroomy, nutty, or of aniseed.$q1$,$q1$Both grow on nutrient-rich meadows, pastures, in parks and at forest edges, from summer to autumn — location does NOT help with the distinction.$q1$,$q1$Both are chocolate-brown — spore print colour is NOT a distinguishing feature here; watch for yellow staining and smell.$q1$,$q1$Cut the stem base lengthwise: strong chrome-yellow staining at the stem base + a carbolic/ink smell = toxic, discard the mushroom. Do not taste it orally. The consequences are severe gastrointestinal complaints (nausea, vomiting, diarrhoea), usually not life-threatening.$q1$,array[$q1$The stem base stains immediately and intensely chrome-yellow (bright yellow) when cut/squeezed — edible mushrooms stain at most faintly yellowish at the cap margin, NEVER strongly yellow at the stem base.$q1$,$q1$Smells unpleasant of carbolic/phenol or ink (best detected on the rubbed stem base or when heating) — edible mushrooms smell mushroomy, nutty, or of aniseed/almond.$q1$,$q1$Stem base bulbously thickened WITHOUT any flap of skin/volva; young cap often with a grey-metallic sheen in the centre; gills pink when young, dark chocolate-brown with age.$q1$,$q1$Identical growing site (meadows, pastures, parks, forest edges, nutrient-rich soils), hence frequent real-world confusion — location does NOT help with the distinction.$q1$]::text[],true),
($q1$champignon-de-paris$q1$,$q1$amanita_phalloides$q1$,$q1$en$q1$,$q1$Amanita phalloides: gills stay white, a membranous white volva at the bulbous stem base, cap olive-green to (var. alba/young) white. Mushroom (champignon): pink-brown gills, no volva, stem base without a sheath.$q1$,$q1$Amanita phalloides is inconspicuous when young, mouldy-sweetish like artificial honey to unpleasant when old. Champignon smells pleasantly mushroomy/nutty/aniseed-like.$q1$,$q1$Amanita phalloides as a mycorrhizal fungus in deciduous forest (especially with oak, beech); champignons on open cultivated land, meadows and pastures.$q1$,$q1$Amanita phalloides white, champignon brown — a white spore print is a clear warning sign.$q1$,$q1$Halve a suspicious white button/egg lengthwise: the presence of white gills + a volva sheath at the base = death cap, deadly. As little as about 20 g is life-threatening — when in doubt, VAPKO mushroom inspection / Tox Info Suisse 145.$q1$,array[$q1$Gills always pure white (even in the old mushroom) — champignon gills are pink when young, brown/blackish-brown when old.$q1$,$q1$Stem base with a bulbous base surrounded by a membranous, flappy white sheath (volva) — the champignon completely lacks the volva.$q1$,$q1$Spore print white (champignon brown).$q1$,$q1$Young specimens resemble a white 'egg' and are especially easily confused with young closed champignons — always cut them open; in section the developing white gill/volva structure shows (uniformly white-green inside, never pink).$q1$]::text[],true),
($q1$calvatia_gigantea$q1$,$q1$amanita_phalloides$q1$,$q1$en$q1$,$q1$Giant puffball: smooth, white to cream-coloured, closed outer skin, spherical, without stem/sheath/volva. Young A. phalloides in the egg: white to olive-tinged membranous universal veil, spherical-egg-shaped — deceptively similar externally, so only the cut counts.$q1$,$q1$Young puffball: pleasantly mushroomy-mild. A. phalloides mature: sweetish-honey-like to unpleasant; in the egg stage barely smellable, therefore NOT a reliable feature — never treat smell as a clearance.$q1$,$q1$Giant puffball: meadows, pastures, gardens, path edges, nutrient-rich soils (not a mycorrhizal fungus). A. phalloides: mycorrhizal fungus in deciduous/mixed forest, especially with oak and beech. Overlap at forest edges/parks possible — location alone does not protect.$q1$,$q1$Not relevant for the puffball (no gills). A. phalloides: white spore print. In the egg stage neither is informative — the distinction is made solely via the lengthwise cut.$q1$,$q1$Cut EVERY small, spherical 'puffball' completely lengthwise (top to bottom) BEFORE use. Only if the surface is uniformly pure white and homogeneous — without any stem/gill/cap outline — is it a puffball. At the slightest internal structure: deadly death cap, discard the entire basket.$q1$,array[$q1$CUT TEST (decisive): the giant puffball has a completely homogeneous, pure-white fruit mass without internal structure. In the young death cap in the egg stage, developing gills, stem and bulb are already recognisable in the lengthwise cut as a silhouette/'embryo' = deadly, discard immediately.$q1$,$q1$Interior colour: young puffball pure white and homogeneous inside. Any yellowish/greenish discolouration or a darker mushroom outline in the cut = not a puffball.$q1$,$q1$Outer covering: the puffball has a smooth, leathery-closed outer skin without a volva. The death cap egg sits in a membranous universal veil (velum universale), from which the volva and stem base develop.$q1$,$q1$A mature giant puffball (>10 cm up to 50 cm) is unmistakable — confusion is only possible with small, spherical young specimens. Rule of thumb: do not eat any 'puffball' smaller than a palm without a cut check.$q1$]::text[],true),
($q1$calvatia_gigantea$q1$,$q1$amanita_verna$q1$,$q1$en$q1$,$q1$Puffball: smooth white, closed, structureless outer skin, spherical. A. verna when young: pure-white veil egg; when mature, completely white with a membranous volva and ring. The egg stages are externally almost identical.$q1$,$q1$A. verna: inconspicuous to slightly unpleasant. Young puffball: mild-mushroomy. No reliable distinguishing feature in the young stage.$q1$,$q1$A. verna: mycorrhizal in (often calcareous) warmth-favoured deciduous/mixed forests with oak/sweet chestnut, appearing especially in spring/early summer, Mediterranean-tinged (southern locations). Giant puffball: grassland/pastures, more in late summer/autumn. Seasonal and location differences exist, but do not replace the cut test.$q1$,$q1$Puffball not relevant. A. verna: white spore print. In the egg stage worthless for the distinction — the cut decides.$q1$,$q1$Lengthwise cut through every small white spherical mushroom: if the silhouette of a little mushroom (stem + cap rudiment) shows in the white flesh, it is the deadly spring death cap — not the puffball.$q1$,array[$q1$A young A. verna egg is pure white and spherical like a young puffball — confusion is therefore real, especially because verna also grows in more open, warmer locations.$q1$,$q1$CUT TEST: homogeneous white puffball mass vs. an already recognisable stem + gill rudiment + bulb in the interior of the Amanita = deadly.$q1$,$q1$A. verna has a membranous volva and a stem-base bulb; the puffball has no volva and no stem.$q1$,$q1$Only the young spherical stage is confusable; a mature Amanita with cap/stem/ring is unambiguous.$q1$]::text[],true),
($q1$calvatia_gigantea$q1$,$q1$gemeiner-fliegenpilz-var-alba$q1$,$q1$en$q1$,$q1$Puffball: smooth, closed white skin, rounded, no stem. A. virosa when young: pure-white egg in a membranous covering; when grown, pure white with a pointed-conical cap, ring and membranous volva. In the egg stage it is barely separable externally from the puffball.$q1$,$q1$A. virosa when ripe: unpleasant, sweetish-disgusting (old finds). Young puffball: mild-mushroomy. Smell in the young/egg stage is unreliable — do not treat it as a clearance.$q1$,$q1$A. virosa: mycorrhizal in acidic coniferous/mixed forest, often with spruce/birch, rather in colder/montane mountain regions. Giant puffball: open grassland, pastures, gardens. Lower location overlap than with phalloides, but the cut test remains mandatory.$q1$,$q1$Puffball: no gills/no spore drop relevant. A. virosa: white spore print. In the confusable egg stage not usable — only the cut counts.$q1$,$q1$On every small white spherical mushroom make a lengthwise cut: a white mushroom-'embryo' visible in the cut (stem + developing cap) exposes the destroying angel (white death cap). Only a structureless white mass = puffball.$q1$,array[$q1$A young A. virosa egg is PURE WHITE and spherical — visually practically identical to a young white puffball. Precisely for this reason the cut test is most important here.$q1$,$q1$CUT TEST: puffball = uniformly homogeneous white mass throughout; A. virosa already shows developing gills, stem and bulb in the lengthwise cut (mushroom outline inside) = deadly.$q1$,$q1$A. virosa has a membranous, sack-like volva at the stem base and (later) a ring; the puffball has neither volva nor stem nor ring.$q1$,$q1$Confusion only in the young, spherical stage — as soon as cap/stem appear on the Amanita, the distinction is trivial.$q1$]::text[],true),
($q1$champignon-de-paris$q1$,$q1$gemeiner-fliegenpilz-var-alba$q1$,$q1$en$q1$,$q1$Amanita virosa: pure white, often conical cap, gills stay white, bulbous stem base with a lobed white volva. Champignon: gills pink to brown, no volva, stem base not enclosed in a membranous sheath.$q1$,$q1$Amanita virosa inconspicuous to sweetish-sickening (rotting flesh). Champignon pleasantly mushroomy/nutty/aniseed-like.$q1$,$q1$Amanita virosa in woodland (often spruce/coniferous forest, acidic soils); champignons on meadows, pastures, compost, cultivated land.$q1$,$q1$Amanita virosa white, champignon brown – the spore print is a reliable distinguishing criterion (white = danger).$q1$,$q1$Always twist the mushroom out of the ground completely, including the stem base, and check for a volva (membranous sheath) at the base of the bulb – volva + permanently white gills + white spore powder = deadly, hands off. If in doubt, Tox Info Suisse 145 / VAPKO mushroom inspection.$q1$,array[$q1$The gills stay pure white at EVERY age – champignon gills are pink when young and turn chocolate-brown to blackish-brown when old (never permanently white).$q1$,$q1$At the stem base a bulbous, swollen base with a membranous, lobed white sheath (volva/egg-membrane) – champignons NEVER have a volva.$q1$,$q1$Spore powder white; champignon spore powder is brown.$q1$,$q1$Grows mostly in (coniferous) woodland, often near spruce – champignons prefer meadows, pastures and cultivated land.$q1$]::text[],true),
($q1$clitocybe_nebularis$q1$,$q1$entoloma_sinuatum$q1$,$q1$en$q1$,$q1$Livid pinkgill (Entoloma sinuatum): more compact, fleshy, light grey to clay-yellowish/ivory-coloured cap; gills whitish-yellowish when young, flesh-pink when old, short and notched (sinuate) at the attachment, not decurrent. Clouded funnel (Clitocybe nebularis): large (10-25 cm) cloud-grey cap with whitish-cream, crowded gills that run shortly down the stem.$q1$,$q1$Clouded funnel: obtrusively sweetish-spicy (perceived as unpleasant by many). Livid pinkgill: mealy-rancid with a sourish-radish-like, unpleasant note.$q1$,$q1$Livid pinkgill: lime-loving, in deciduous and mixed forests (especially beech, oak, hornbeam) on calcareous/loamy soil, rather rare, May-November; grows singly, in groups OR in fairy rings. Clouded funnel: common and often in masses, deciduous and coniferous forest, late autumn (Oct-Nov), likewise forms rows and fairy rings. WARNING: fairy-ring growth is NOT suitable for distinguishing them — both species show it.$q1$,$q1$DECISIVE: Livid pinkgill flesh-pink to pinkish-brown (Entoloma genus characteristic). Clouded funnel white to pale cream-yellowish. A simple spore print on white paper separates the two reliably — this is the most dependable feature.$q1$,$q1$A spore print is mandatory: pink/flesh-pink powder = pinkgill = do NOT eat. The clouded funnel drops white to pale cream-coloured powder and has shortly decurrent, crowded gills. Do NOT rely on the growth form — BOTH species can form rows and fairy rings, this is NO distinguishing feature.$q1$,array[$q1$Spore powder (SAFEST feature): Livid pinkgill flesh-pink to pinkish-brown (pinkgill genus) — clouded funnel white to pale cream-yellowish. A spore print on white paper separates the two unambiguously.$q1$,$q1$Gill colour in age: Livid pinkgill gills whitish/yellowish when young, clearly flesh-PINK in age due to the spores — clouded funnel gills stay white to cream-yellowish, NEVER pink.$q1$,$q1$Gill attachment: Clouded funnel gills run shortly DOWN the stem (funnel-typical), crowded; livid pinkgill gills are notched (sinuate) at the attachment, short, stiff and stand little crowded — NOT decurrent.$q1$,$q1$Smell: Clouded funnel obtrusively sweetish-spicy; livid pinkgill mealy-rancid with an unpleasant sourish-radish-like note.$q1$]::text[],true),
($q1$eierschwamm$q1$,$q1$cortinarius_orellanus$q1$,$q1$en$q1$,$q1$Chanterelle: yolk-yellow with funnel shape and ridges. Webcap (Raukopf): red-brown-orange with true gills.$q1$,$q1$Chanterelle: apricot-fruity. Webcap: radish-like.$q1$,$q1$Chanterelle: May-Oct coniferous forest. Webcap: Sep-Nov deciduous forest.$q1$,$q1$Chanterelle: pale yellow. Webcap: rust-brown.$q1$,$q1$GOLDEN RULE: turn the cap over — TRUE gills or RIDGES? If in doubt, VAPKO!$q1$,array[$q1$Chanterelle has RIDGES, webcap has TRUE gills$q1$,$q1$Chanterelle is egg-yellow-apricot, webcap orange-red-brown$q1$]::text[],true),
($q1$eierschwamm$q1$,$q1$hygrophoropsis_aurantiaca$q1$,$q1$en$q1$,$q1$Ridges (chanterelle) vs. true gills (false one); texture firm vs. soft.$q1$,$q1$Chanterelle fruity (apricot); false one nonspecific/musty$q1$,$q1$Chanterelle deciduous/coniferous forest; false one mainly conifer litter/deadwood$q1$,$q1$both pale$q1$,$q1$The false chanterelle is mildly poisonous (gastrointestinal). Check blunt ridges vs. sharp detachable gills. If strongly orange-red, additionally rule out the olive-tree mushroom (poisonous).$q1$,array[$q1$True chanterelle: blunt, firmly fused ridges, firm-fleshy$q1$,$q1$False chanterelle: true thin, strongly forked, easily detachable gills, soft$q1$]::text[],true),
($q1$hallimasch$q1$,$q1$cortinarius_orellanus$q1$,$q1$en$q1$,$q1$Honey fungus (Hallimasch): honey-yellow with ring, in clusters. Webcap (Raukopf): orange-red-brown, single.$q1$,$q1$Honey fungus: sourish. Webcap: radish-like.$q1$,$q1$Honey fungus: tree stumps, roots. Webcap: ground, deciduous forest.$q1$,$q1$Honey fungus: white. Webcap: rust-brown.$q1$,$q1$Be especially careful with young mushrooms. Make a spore print.$q1$,array[$q1$Honey fungus has a ring + grows parasitically on trees, webcap single$q1$,$q1$Spore powder: honey fungus white, webcap rust-brown$q1$]::text[],true),
($q1$infundibulicybe_geotropa$q1$,$q1$clitocybe_dealbata$q1$,$q1$en$q1$,$q1$Trooping Funnel (Monk's Head): 12-25 cm, cream/buff-coloured to reddish-ochre with age, central palpable umbo, robust club-shaped stem. Ivory Funnel (Sweating Mushroom): only 2-5 cm, chalk-white pruinose, depressed/flat without an umbo, thin slender stem.$q1$,$q1$Trooping Funnel smells aromatically sweetish with a distinct bitter-almond note; Ivory Funnel is insignificant to faintly mealy. Caution: smell is a SUPPORTING feature, never the sole safety criterion - always combine it with size/umbo/flesh thickness.$q1$,$q1$Ivory Funnel: open grassland, meadows, pastures, lawns, path edges, parks. Trooping Funnel: deciduous and coniferous forest, forest edges, forest meadows on moist calcareous soil. Both can form fairy rings - the habitat type (forest vs. open grass) is more relevant than the ring growth.$q1$,$q1$Both WHITE - the spore print does NOT help to distinguish here. Separation is made via size, flesh thickness, cap umbo and stem thickness.$q1$,$q1$Golden rule: NEVER eat SMALL white funnel caps (under about 6 cm, thin-fleshed, without a palpable cap umbo) - they contain muscarine and are dangerously confusable as a group. Take only the large (12-25 cm), thick-fleshed Trooping Funnel with a clearly palpable central cap umbo and a robust stem. Fairy rings and white spore print are present in BOTH - they are NOT useful for distinguishing.$q1$,array[$q1$Size/flesh: Ivory Funnel only 2-5 cm cap, thin-fleshed (a few mm); Trooping Funnel 12-25 cm, thick-fleshed and with a clearly palpable central umbo/bump in the centre of the cap (finger test) - the umbo is always absent in the Ivory Funnel.$q1$,$q1$Both white/cream-coloured & funnel-shaped with decurrent gills and WHITE spore print - the cap colour and spore print do NOT help, only size + flesh thickness + umbo + habitat separate them reliably.$q1$,$q1$Habitat/season: Ivory Funnel on meadows, pastures, path edges, lawns, parks (early summer-late autumn, often in fairy rings); Trooping Funnel in deciduous/coniferous forest, at forest edges and on forest meadows on moist calcareous soil (late summer-autumn, likewise fairy rings - habitat alone is NOT sufficient).$q1$,$q1$Stem: Trooping Funnel has a robust, often club-thickened stem (2-4 cm thick, 8-15 cm long); Ivory Funnel slender and thin.$q1$]::text[],true),
($q1$infundibulicybe_geotropa$q1$,$q1$clitocybe_rivulosa$q1$,$q1$en$q1$,$q1$Fool's Funnel (Frosty Funnel): up to 4-5 cm, chalk-white pruinose, depressed without an umbo, thin stem. Trooping Funnel (Monk's Head): 12-25 cm, cream/buff-coloured, with a central umbo, thick club-shaped stem.$q1$,$q1$Trooping Funnel aromatically sweetish with a bitter-almond note; Fool's Funnel inconspicuous to faint. Use smell only as an additional feature, never alone.$q1$,$q1$Fool's Funnel: lawns, meadows, path edges, dunes, embankments, parks (in the grass, in troops/fairy rings). Trooping Funnel: deciduous/coniferous forest on calcareous soil, forest edges, forest meadows. Forest vs. open grassland is the relevant location criterion.$q1$,$q1$Both WHITE - no distinction via spore colour possible; size + flesh thickness + habitat + umbo decide.$q1$,$q1$Every small, chalk-white pruinose funnel cap in the grass/lawn is muscarine-suspect - if in doubt, leave it standing. The Trooping Funnel is large (12-25 cm), thick-fleshed, forest-bound and has a palpable central umbo - not the dainty small white meadow mushroom. White spore powder does NOT rule out the poisonous funnel cap, since it too produces a white spore print.$q1$,array[$q1$Size: Fool's Funnel only up to approx. 4-5 cm cap, chalk-white pruinose, depressed/indented without an umbo; Trooping Funnel 12-25 cm, thick-fleshed, with a clearly palpable central umbo.$q1$,$q1$Both whitish-funnel-shaped with decurrent gills and WHITE spore print - only size, flesh thickness and cap umbo separate them reliably, colour and spore print do NOT.$q1$,$q1$Highly toxic due to muscarine (muscarine syndrome: heavy salivation/sweating/lacrimation within 15-30 min, in severe cases circulatory collapse), often on the same meadow/path-edge/dune locations in troops or fairy rings.$q1$,$q1$Stem dainty/thin in the poisonous funnel cap vs. robust-club-shaped (2-4 cm thick) in the Trooping Funnel.$q1$]::text[],true),
($q1$infundibulicybe_geotropa$q1$,$q1$entoloma_sinuatum$q1$,$q1$en$q1$,$q1$Livid Pinkgill (Lead Poisoner): 5-20 cm, ivory/pale grey-brown to pale lilac-grey, convex with a wavy margin without an umbo, thick rigid gills that turn pink. Trooping Funnel (Monk's Head): funnel-shaped with a central umbo, white decurrent gills, cream/buff-coloured.$q1$,$q1$Livid Pinkgill mealy with an unpleasant sourish-radish-like accompanying smell; Trooping Funnel aromatically sweetish with a bitter-almond aroma. Smell only as an additional feature, the spore print is decisive.$q1$,$q1$Livid Pinkgill: open deciduous forest (often beech/oak-hornbeam) on fresh to moist, calcareous soil, summer-autumn, mycorrhizal. Trooping Funnel: deciduous/coniferous forest, forest edges, forest meadows on moist calcareous soil, late summer-autumn - habitats overlap, therefore a spore-print and gill check is mandatory.$q1$,$q1$Decisive: Livid Pinkgill FLESH-PINK/flesh-reddish spore print vs. Trooping Funnel WHITE. This is the most reliable distinguishing feature between these two.$q1$,$q1$Make a spore print: pink/flesh-coloured powder = Livid Pinkgill = leave it standing. Additionally check whether the gills run down the stem (Trooping Funnel) or are merely emarginate/straight-attached and turn pink with maturity (Livid Pinkgill). If the central umbo is missing and the cap is not truly funnel-shaped, caution is required.$q1$,array[$q1$SPORE PRINT: Livid Pinkgill has FLESH-PINK (flesh-reddish) spore print; Trooping Funnel has WHITE spore print - the most reliable distinguishing feature via spore print.$q1$,$q1$GILLS: Livid Pinkgill gills whitish when young, then yellowish, finally flesh-pink due to the spores, emarginate/straight-attached at the stem (NOT decurrent); Trooping Funnel gills remain white/cream-coloured and run clearly down the stem.$q1$,$q1$CAP SHAPE: Livid Pinkgill convex with an inrolled, later wavy margin, WITHOUT a central umbo and without a pronounced funnel shape; Trooping Funnel funnel-shaped with a palpable central umbo.$q1$,$q1$SMELL: Livid Pinkgill mealy with an unpleasant sourish-radish-like note; Trooping Funnel aromatically sweetish with a bitter-almond note.$q1$]::text[],true),
($q1$kuehneromyces_mutabilis$q1$,$q1$galerina_marginata$q1$,$q1$en$q1$,$q1$Both honey-brown, hygrophanous, clustered on wood - visually very similar; only the stem below the ring zone differs (scaly vs. smooth).$q1$,$q1$both mushroomy, no reliable distinction by smell$q1$,$q1$both on dead wood/stumps, often mixed$q1$,$q1$both rust-brown$q1$,$q1$DEADLY. Taboo for beginners. Harvest only with the complete stem and check every single mushroom - when in doubt, take it to the VAPKO inspection.$q1$,array[$q1$Stem below the ring: Sheathed Woodtuft scaly/frosted, Funeral Bell smooth-silky$q1$,$q1$Funeral Bell contains deadly amatoxins$q1$]::text[],true),
($q1$lactarius_deliciosus$q1$,$q1$paxillus_involutus$q1$,$q1$en$q1$,$q1$Saffron Milkcap: consistently orange to carrot-red, cap with darker concentric zones, often greenish spots with age/when injured, stem frequently with pits. Brown Rollrim: dull yellow-brown to umber-brown, permanently inrolled felty cap margin, no orange, no concentric milkcap zones.$q1$,$q1$Saffron Milkcap: mild, fruity. Brown Rollrim: inconspicuous, slightly sourish; no typical milkcap scent.$q1$,$q1$Habitat overlap possible: Saffron Milkcap is a mycorrhizal partner of pines (partly spruces), rather calcareous soil. Brown Rollrim forms mycorrhiza with pine, spruce, birch, beech on acidic, fresh to moist soils. Habitat is therefore NOT a reliable distinguishing feature - only the milk test and colour count.$q1$,$q1$Saffron Milkcap: cream-white to pale ochre-yellowish spore print. Brown Rollrim: brownish (clay-brown) spore print - clearly darker. Clear diagnostic direction: the Rollrim is always noticeably darker.$q1$,$q1$The cut/milk test is mandatory: whoever sees NO orange-red milky sap at the cut surface does not have a Milkcap - leave it standing. The Brown Rollrim never exudes milk and turns brown-black under pressure (the Milkcap only slowly turns green). Paxillus syndrome (immune-haemolytic) can be fatal after years of repeated consumption - therefore never taste it 'to try', not even cooked.$q1$,array[$q1$MILK TEST (decisive): Saffron Milkcap releases abundant carrot-/orange-red milky sap when cut. The Brown Rollrim releases NO milk - it is not a milk mushroom. No orange-red milky sap = no Milkcap.$q1$,$q1$Pressure discolouration: Rollrim gills and flesh discolour immediately to brown to dark-red-/black-brown when pressed/injured. Milkcap flesh/milk discolours only slowly greenish (never brown-black).$q1$,$q1$Gills: Rollrim ochre-yellow to olive-brown, decurrent at the stem and easily detachable from the cap flesh. Milkcap gills are orange/saffron-coloured and not detachable.$q1$,$q1$Cap colour + cap margin: Milkcap orange to carrot-red with darker concentric ring zones. Rollrim dull yellow-brown to umber-brown, without orange, with a permanently inrolled, felty cap margin (even with age).$q1$]::text[],true),
($q1$lactarius_deterrimus$q1$,$q1$paxillus_involutus$q1$,$q1$en$q1$,$q1$False saffron milkcap (Lactarius deterrimus): orange-red to orange-brownish cap, with age/in frost developing dirty green spots, pale orange gills that turn dark red to grey-green when injured. Brown rollrim (Paxillus involutus): yellowish to umber-brown, moist glossy cap, when young with a long inrolled felty cap margin, when old distinctly funnel-shaped and depressed; ochre-yellowish to olive-brown, thin and crowded, decurrent and detachable gills that stain STRONGLY rust- to blackish-brown when pressed/touched (milkcap gills do not turn rust-brown). Both can appear funnel-shaped and orange-brown -> hence the confusion.$q1$,$q1$False saffron milkcap: mild, fruity-spicy (taste slightly bitter). Brown rollrim: sourish-nondescript; smell is NOT a reliable distinguishing feature — the milk test and the gill pressure test are decisive.$q1$,$q1$Overlap exists: the brown rollrim is a mycorrhizal partner of, among others, spruce (also pine, birch, beech, hornbeam) and grows in the same acidic coniferous/mixed-forest soil in which the false saffron milkcap occurs with spruce. Habitat does NOT separate them reliably.$q1$,$q1$Secondary feature, not sharply separating: the false saffron milkcap, depending on the source, cream to pale ochre to ochre-brownish; the brown rollrim distinctly clay- to rust-brown. The colours overlap towards ochre — therefore only as a supporting clue, not as the main criterion. The milk test remains decisive. When in doubt, take a spore print.$q1$,$q1$Always do the milk test: cut a fresh section and check for milk exuding. If NO milk exudes, it is not a milkcap — the brown rollrim is milkless and, via the cumulative Paxillus syndrome (haemolytic anaemia, kidney failure), can become life-threatening even after years of consumption. Milkcaps, by contrast, exude orange/carrot-red milk that turns wine-red. Rule of thumb: only collect milkcaps with red/orange milk — never those with pale/white milk or with no milk at all.$q1$,array[$q1$MILK TEST (decisive, verified): the false saffron milkcap exudes orange/carrot-red milk when cut, which turns wine-red within 15-20 min (later grey-green); the brown rollrim exudes NO milk/fluid — no milk at all = NEVER eat it if you are expecting a milkcap.$q1$,$q1$Gill pressure test (verified): rollrim gills stain strongly rust- to blackish-brown when pressed and can be detached from the cap; milkcap gills are brittle, firmly attached to the cap, and turn dark red/grey-green when injured, not rust-brown.$q1$,$q1$Cap margin & shape: the rollrim has a long felty-inrolled cap margin and a glossy olive-brown cap; the milkcap cap is orange with green spots, without a permanently felty inrolled margin.$q1$,$q1$Spore print (supplementary, not reliable on its own): milkcap cream to ochre vs. rollrim clay/rust-brown — overlaps towards ochre, therefore only supplementary.$q1$]::text[],true),
($q1$lepista_nuda$q1$,$q1$cortinarius_orellanus$q1$,$q1$en$q1$,$q1$Cortinarius orellanus: yellow-/red-brown, slightly umbonate, finely scaly-fibrous cap, yellow-cinnamon-brown gills, rust-brown veil fibres on the stem. Lepista nuda: uniformly violet, smooth domed cap without a veil.$q1$,$q1$Lepista nuda distinctly aromatic-sweet (perfume-like). orellanus smells faintly radish-like, without the sweet scent. Smell only as a clue, never reliable on its own.$q1$,$q1$orellanus: deciduous/mixed forest with oak and beech (mycorrhiza), summer to late autumn, rather rare/warmth-favoured. Lepista nuda: nutrient-rich litter, hedges, compost, very late in the season.$q1$,$q1$Lepista nuda pale pink-whitish; Cortinarius orellanus rust-brown. A rust-brown print rules out Lepista nuda.$q1$,$q1$A spore print is mandatory: rust-brown = webcap, life-threatening. Cortinarius orellanus is considered one of the most dangerous mushrooms in Europe (orellanine, latency up to 14 days, kidney and liver damage). A cobweb-like veil on the young mushroom or rust-brown stem fibres = never eat. When in the slightest doubt, discard.$q1$,array[$q1$Spore print (most reliable distinguisher from the entire webcap genus): Lepista nuda pale pink-whitish vs. Cortinarius orellanus rust-brown. A rust-brown print rules out Lepista nuda.$q1$,$q1$Cortina/veil: orellanus has a (when young yellowish) cobweb-like veil with rust-brown veil remnants on the stem; Lepista nuda has no velum whatsoever.$q1$,$q1$Cap colour: orellanus yellow- to red-brown/foxy (NEVER violet), often slightly umbonate; Lepista nuda uniformly violet in youth.$q1$,$q1$Gill colour: orellanus yellow-/cinnamon-brown, distantly spaced, emarginate (notched) attachment; Lepista nuda violet/violet-pink and staying pale.$q1$]::text[],true),
($q1$lepista_nuda$q1$,$q1$cortinarius_rubellus$q1$,$q1$en$q1$,$q1$Lepista nuda: when young uniformly violet throughout (cap, gills, stem), domed smooth cap without a pointed umbo, no veil. Cortinarius rubellus: rust- to foxy-orange cap with a pointed (umbonate) apex, finely felty-fibrous, cinnamon-/rust-brown gills, rust-brown veil fibres on the stem.$q1$,$q1$Lepista nuda smells aromatic-sweet (perfume-like, reminiscent of biscuit/orange blossom). Cortinarius rubellus smells faintly radish-like, without the typical sweet scent. Smell is only a clue, NEVER reliable on its own — spore print + cortina are decisive.$q1$,$q1$Webcap (Raukopf): acidic coniferous forests (spruce/spruce-pine mixed forest), boggy-moist and montane sites, Aug-Oct. Wood blewit (Roetelritterling): nutrient-rich deciduous/mixed-forest litter, hedges, compost heaps, very late in the season up to after the first frosts.$q1$,$q1$Decisive: Lepista nuda = pale pink-whitish/cream-pink spore print. Cortinarius rubellus = rust-brown spore print. A rust-brown print reliably rules out Lepista nuda.$q1$,$q1$ALWAYS take a spore print (cap overnight on white paper). Pale pink-whitish = possibly Lepista nuda. Rust-brown OR a cobweb-like veil (cortina) on the young mushroom = STOP, webcap — never eat. Orellanine poisoning only manifests after 3-14 days, by which point the kidney is already irreversibly damaged. When in the slightest doubt, do not eat.$q1$,array[$q1$Spore print (most reliable separation check): Lepista nuda pale pink-whitish/cream-pink — EVERY Cortinarius/webcap has RUST-BROWN spore powder. A rust-brown print reliably rules out the wood blewit.$q1$,$q1$Cortina/veil: the webcap as a young mushroom has a cobweb-like veil (cortina) between the cap margin and the stem; veil remnants on the stem stain rust-brown. The wood blewit NEVER has a veil — no velum at all.$q1$,$q1$Cap shape/colour: Cortinarius rubellus rust- to cinnamon-/foxy-orange with a pointed, umbonate apex; Lepista nuda when young uniformly violet, domed cap without a pointed umbo.$q1$,$q1$Gill colour: wood blewit violet/violet-pink and staying pale; webcap cinnamon-/rust-brown, distantly spaced, emarginate (notched) attachment.$q1$,$q1$Habitat: webcap near conifers (spruce) on acidic, often boggy-moist soil in the mountains; wood blewit in nutrient-rich deciduous/mixed-forest litter, hedges, compost heaps, late in the season up to after frost.$q1$]::text[],true),
($q1$lycoperdon_perlatum$q1$,$q1$amanita_phalloides$q1$,$q1$en$q1$,$q1$From the outside, a white, closed death cap egg can superficially resemble a young white puffball. Reliable separation only in longitudinal section: homogeneous white mass (puffball) vs. a preformed mushroom with a gill/stem silhouette and a volva (Amanita).$q1$,$q1$Young puffball odourless to mushroomy-mild. Young death cap almost odourless, only when old sweetish-honey-like to carrion-like. Smell is NOT a reliable feature at the critical egg stage.$q1$,$q1$A. phalloides is a mycorrhizal mushroom mainly with oak and beech (also chestnut), preferring acidic soils; the puffball is saprotrophic and ubiquitous in all forest types, meadows and gardens. The habitats often overlap → habitat does NOT help with the distinction, only the section test is reliable.$q1$,$q1$In the puffball, yellow- to olive-brown spore powder matures inside (the mushroom is then no longer edible). A. phalloides has white spore powder — but not testable at the egg stage, therefore irrelevant for the collector.$q1$,$q1$Halve EVERY spherical puffball completely lengthwise before eating and check the cut surface. Only eat it if the inside is COMPLETELY pure white and homogeneous — without the slightest outline of gills, stem or cap. A single recognizable mushroom outline means deadly amatoxin poisoning (liver failure). When in doubt, go to the mushroom inspection centre (VAPKO).$q1$,array[$q1$LONGITUDINAL SECTION (the decisive test): in the puffball the inside is a completely uniform, pure white, marshmallow-like mass WITHOUT any structure. In the young death cap egg, the section already shows the preformed mushroom — the embryonic gills and the stem as a darker silhouette/outline. Even a single recognizable gill or stem base = discard.$q1$,$q1$Stem base/volva: the young Amanita sits inside a white membranous universal veil (velum) and has a lobed, membranous bulb/volva at the base. The puffball has no volva, no distinct stem and no veil of this kind — it sits in the soil with a short sterile base.$q1$,$q1$Outer skin: the common puffball bears fine wipeable spine-/wart-warts that leave a net pattern, and is white inside. The Amanita egg is smooth-membranous white on the outside.$q1$,$q1$Ripening changes the puffball: as soon as the inside turns yellowish/olive/brownish (spore formation), it is no longer edible — the Amanita flesh stays white in section and shows the mushroom silhouette.$q1$]::text[],true),
($q1$lycoperdon_perlatum$q1$,$q1$amanita_verna$q1$,$q1$en$q1$,$q1$Outwardly very similar to the young white puffball (pure white membranous egg); reliably distinguishable only in cross-section by the preformed mushroom structure (gills+stem) and the pronounced volva — not by the outer shape.$q1$,$q1$A. verna when young odourless to faint; when old unpleasantly sweetish. Not a reliable distinguishing feature at the egg stage.$q1$,$q1$A. verna occurs mainly in spring/early summer (deciduous forests, rather calcareous/warmer soils); puffballs appear rather in summer–autumn and are ubiquitous. Season/habitat are clues, but NOT a reliable substitute for the section test.$q1$,$q1$A. verna: white spore powder. Puffball: yellow-/olive-brown spore powder at maturity (then no longer edible). Not testable at the egg stage, therefore irrelevant for identification.$q1$,$q1$Here too: halve every spherical white find — only eat it if the inside is completely homogeneous white without a gill/stem silhouette and without a volva. A preformed mushroom in the section means deadly amatoxin poisoning. Inspection centre (VAPKO) at any uncertainty.$q1$,array[$q1$Like all white death caps (section Phalloideae), A. verna is spherical at the young egg stage enveloped by the white velum and can be confused with white puffballs. The LONGITUDINAL SECTION decides: homogeneous white mass (puffball) vs. preformed gills + stem in the egg (Amanita).$q1$,$q1$Stem base: A. verna shows a distinctly pronounced, lobed, sack-like membranous sheath (volva) at the base — the puffball lacks any volva.$q1$,$q1$Gills stay white to cream-white (even when mature) — laid down in the egg as a pale silhouette in section; the puffball never has gill rudiments.$q1$,$q1$Outside pure white-membranous (Amanita) vs. finely warty/spiny with wipeable warts (common puffball).$q1$]::text[],true),
($q1$marone$q1$,$q1$flockenstieliger_hexenpilz$q1$,$q1$en$q1$,$q1$Bay bolete (Marone): brown, light blueing. Witch's bolete (Hexenpilz): brown, rapid strong blueing, red dots.$q1$,null,$q1$Both in forest.$q1$,null,$q1$Both edible. The witch's bolete MUST be cooked for 15+ min.$q1$,array[$q1$Both are edible mushrooms; the witch's bolete blues FASTER$q1$,$q1$Witch's bolete has little red dots on the stem$q1$]::text[],true),
($q1$marasmius_oreades$q1$,$q1$clitocybe_rivulosa$q1$,$q1$en$q1$,$q1$Fairy ring mushroom (Nelkenschwindling): brownish-yellow cap with a blunt umbo, widely spaced pale gills, tough pliable stem. Fool's funnel / poison funnel (Gifttrichterling): lead-white to creamy-grey, often depressed/funnel-shaped cap, crowded decurrent gills.$q1$,$q1$Fairy ring mushroom: pleasantly spicy, of cloves/bitter almond (a hydrocyanic-acid note) — CAUTION: ~25% of people are genetically unable to perceive this smell, so it is not a stand-alone feature. Poison funnel: mealy to odourless. Use smell only as additional confirmation, never as the sole proof of safety.$q1$,$q1$Both grow in the SAME habitat: meadows, pastures, lawns in gardens/parks; both form fairy rings — no separation by location is possible. This greatly increases the risk of confusion.$q1$,$q1$Both have WHITE spore powder — a spore print does NOT separate these two. What remains decisive is the gill attachment (decurrent vs. widely spaced/emarginate) and the tough stem.$q1$,$q1$Golden rule in the meadow: check the gills. The fairy ring mushroom has WIDELY spaced, NON-decurrent gills and a tough, pliable stem. If the gills are crowded and run down the stem — leave it standing (suspicion of the muscarine-containing poison funnel). The spicy clove smell is only an additional confirmation (a quarter of people cannot smell it).$q1$,array[$q1$Gills (THE main feature): the poison funnel has crowded, shortly DECURRENT (running down the stem) gills — the fairy ring mushroom has DISTANT (widely) spaced gills that are emarginate (notched) at the stem and NOT decurrent$q1$,$q1$Stem: the fairy ring mushroom's stem is tough, pliable, cartilaginous-fibrous (can be twisted without breaking) — the funnel cap's stem is brittle$q1$,$q1$Cap: the funnel cap is lead-white/creamy-grey, hygrophanous, often depressed/funnel-shaped — the fairy ring mushroom is leathery brownish-yellow with a blunt umbo$q1$,$q1$Reviving test: the fairy ring mushroom's fruiting bodies revive after drying (typical of the Marasmius genus) — the poison funnel does not$q1$]::text[],true),
($q1$marasmius_oreades$q1$,$q1$clitocybe_dealbata$q1$,$q1$en$q1$,$q1$Ivory funnel / field funnel (Feldtrichterling): smaller, chalky lead-white to cream-yellow, often depressed cap with crowded decurrent gills. Fairy ring mushroom (Nelkenschwindling): leathery brown-yellow cap with an umbo, widely spaced gills, distinctly tougher stem.$q1$,$q1$Fairy ring mushroom pleasantly spicy (clove/bitter almond) — not perceptible to ~25% of people for genetic reasons, therefore not a stand-alone feature. Field funnel mealy to odourless.$q1$,$q1$Like C. rivulosa, a typical meadow/lawn mushroom on grassy spots, possibly in fairy rings — exactly within the habitat of the fairy ring mushroom. Location is not suitable for distinguishing them.$q1$,$q1$Both with WHITE spore powder — not a distinguishing feature. What remains decisive is the gill attachment and the tough stem.$q1$,$q1$Muscarine acts already in small amounts (sweating, salivation, watering eyes after 15-30 min). Never collect if the gills are crowded and run down the stem — the edible fairy ring mushroom ALWAYS has widely spaced, non-decurrent gills and a tough, pliable stem. The clove smell is only an additional confirmation.$q1$,array[$q1$Gills: the field funnel has crowded gills, attached to shortly DECURRENT (running down the stem) — the fairy ring mushroom has widely distant, emarginate (notched) gills, NOT decurrent$q1$,$q1$Cap: the field funnel is chalky lead-white to cream-yellow, smooth/frosted, flat to depressed — the fairy ring mushroom is leather-coloured with a blunt umbo, hygrophanous$q1$,$q1$Stem: the fairy ring mushroom is tough-pliable, cartilaginous-fibrous — the field funnel is more fibrous and more brittle$q1$,$q1$Reviving test: the fairy ring mushroom revives after drying — the field funnel does not$q1$]::text[],true),
($q1$marasmius_oreades$q1$,$q1$inocybe_erubescens$q1$,$q1$en$q1$,$q1$Fibrecap (Risspilz): conical-umbonate cap, radially split open, whitish and turning brick-red over time/under pressure, with darkening (olive-pink-brownish) gills. Fairy ring mushroom (Nelkenschwindling): smooth leather-coloured cap with a blunt umbo, gills staying pale and widely spaced.$q1$,$q1$Fairy ring mushroom pleasantly spicy (clove/bitter almond; not perceptible to ~25%). Brick-red fibrecap faintly fruity, unpleasantly sweetish-spermatic with age. Use smell only as an addition, never alone.$q1$,$q1$The brick-red fibrecap grows lime-loving (calcareous), mainly in deciduous/mixed forests, parks and under shrubbery (mycorrhiza with beech/lime), partly also on lawns — not primarily open meadow like the fairy ring mushroom. Location helps but is NOT a stand-alone safety feature (also possible on lawns/park lawns).$q1$,$q1$DECISIVE and life-saving: the fibrecap has dark-brown spore powder — the fairy ring mushroom white. A spore print separates the two unambiguously.$q1$,$q1$Spore-powder check as a lifesaver: white = fairy ring mushroom possible, brown = NEVER eat. In addition, these expose the deadly fibrecap: fissured-radially-fibrous cap, brick-red discolouration (under pressure) and the spermatic smell. Muscarine — a deadly amount already from approx. 40-500 g of fresh mushroom.$q1$,array[$q1$Spore powder (DECISIVE): the fibrecap has DARK-BROWN spore powder, the gills change from white/cream over olive-grey-pink to mottled-brownish — the fairy ring mushroom has WHITE spore powder and persistently pale gills$q1$,$q1$Reddening: the fibrecap reddens brick-red (cap/stem/flesh, especially under pressure and with age) — the fairy ring mushroom does NOT redden$q1$,$q1$Cap surface: the fibrecap is conical-umbonate, radially fibrous and splitting open/fissured ('Risspilz', i.e. fissure mushroom) — the fairy ring mushroom is smooth, hygrophanous, with a blunt umbo$q1$,$q1$Smell: the fibrecap is spermatic/fruity-unpleasant — the fairy ring mushroom spicy, of cloves/bitter almond$q1$]::text[],true),
($q1$lycoperdon_perlatum$q1$,$q1$gemeiner-fliegenpilz-var-alba$q1$,$q1$en$q1$,$q1$From above/outside hardly distinguishable from a young white puffball, because A. virosa is completely pure white. Reliable distinction only in cross-section: a pre-formed white mushroom with crowded gills + volva (Amanita) vs. a homogeneous white mass (puffball).$q1$,$q1$Older A. virosa smells unpleasantly sweetish-repulsive; but the young 'egg' is inconspicuous. Smell is not reliable at the critical egg stage.$q1$,$q1$A. virosa grows mainly in moist (acidic) coniferous/mixed forests, with mycorrhiza preferentially with spruce (finds also documented under beech/oak/birch), often at higher/montane elevations — ecologically partly different from the ubiquitous saprotrophic puffball, but location is NOT a reliable criterion.$q1$,$q1$A. virosa: white spore powder. In the puffball, yellow-/olive-brown spore powder matures (= then no longer edible). At the egg stage it cannot be checked, therefore irrelevant for identification.$q1$,$q1$Because the white destroying-angel egg is pure white and especially resembles a white puffball, the following applies all the more strictly: halve it completely, and eat ONLY if the inner flesh is absolutely homogeneous white, without any gill/stem silhouette and without a volva. Any mushroom outline = mortal danger (amatoxins, liver failure). When in doubt, go to the mushroom inspection office (VAPKO).$q1$,array[$q1$Young stages of Amanita virosa are explicitly noted in mushroom/poison databases as being confused with bovistas and puffballs. Decisive is the LONGITUDINAL CUT: puffball = homogeneous pure white mass; Amanita egg = already pre-formed (white, crowded) gills and a stem recognisable as a silhouette.$q1$,$q1$Stem base: A. virosa has a membranous, lobed white sheath (volva) at the base. The puffball has no volva and no distinct stem.$q1$,$q1$Outer contour: the virosa egg is pure white and smooth-membranous; the common puffball bears fine, wipe-off-able warts/spines.$q1$,$q1$Since A. virosa is completely white (cap, gills, stem all stay white), the colour clue is absent — only the cut image and the volva separate them reliably.$q1$]::text[],true),
($q1$morchella_elata$q1$,$q1$fliegenpilz-grosspilz$q1$,$q1$en$q1$,$q1$Morel honeycombed/regular vs. false morel brain-like/irregular.$q1$,$q1$both unspecific$q1$,$q1$both spring, burn sites/floodplain forest/coniferous forest$q1$,$q1$no gill spore powder (ascomycetes)$q1$,$q1$The spring false morel is highly toxic (potentially deadly). Longitudinal cut: continuously hollow (morel) vs. cottony-chambered (false morel).$q1$,array[$q1$Black morel: honeycombed-pitted cap, cap+stem completely hollow$q1$,$q1$Spring false morel: brain-like convoluted, stem chambered (not hollow), gyromitrin (highly toxic)$q1$]::text[],true),
($q1$parasol$q1$,$q1$amanita_pantherina$q1$,$q1$en$q1$,$q1$Parasol: light-brown cap, snakeskin-patterned stem. Panther: brown with white warts, white stem with bulbs.$q1$,$q1$Parasol: nutty, pleasant. Panther: radish-like.$q1$,$q1$Parasol: meadows, forest edge. Panther: deciduous forest.$q1$,$q1$Both white.$q1$,$q1$PARASOL test: ring movable-slidable, stem snakeskin-patterned. With warts, NEVER eat.$q1$,array[$q1$Parasol ring MOVABLE, Panther ring fixed$q1$,$q1$Parasol snakeskin-patterned stem, Panther white-smooth$q1$,$q1$Panther has a bulb with 2-3 ring-like rolls$q1$]::text[],true),
($q1$parasol$q1$,$q1$chlorophyllum_brunneum$q1$,$q1$en$q1$,$q1$Stem snakeskin patterning (Parasol yes) + reddening (toxic shaggy parasol yes) + bulb.$q1$,$q1$both unspecific$q1$,$q1$Parasol forest/meadow; toxic shaggy parasol often compost/garden$q1$,$q1$both white-cream$q1$,$q1$Gastrointestinal toxin. Snakeskin-patterned stem + no reddening = Parasol; smooth stem + saffron-red discoloration = hands off.$q1$,array[$q1$Parasol: snakeskin-patterned (snakeskin-like) stem, slidable double ring, flesh does NOT redden$q1$,$q1$Toxic shaggy parasol: smooth stem, rimmed bulb, flesh/gills discolor saffron-red$q1$]::text[],true),
($q1$roetling$q1$,$q1$agaricus_xanthodermus$q1$,$q1$en$q1$,$q1$Yellow-staining mushroom: cap white to chalk-white, when young spherical/hemispherical, later flattened, smooth to finely scaly; stem base in longitudinal cut IMMEDIATELY bright chrome-yellow. Sheep mushroom: cap cream-white, silky-fibrous to slightly scaly, convex to flat; yellows only weakly over the whole mushroom and without the concentrated chrome-yellow spot at the stem base.$q1$,$q1$Decisive feature: the sheep mushroom smells pleasantly of anise/marzipan. The yellow-staining mushroom smells unpleasantly of ink/carbolic/phenol (medicinal-iodine-like); the smell intensifies when rubbing the stem base and especially when heating/cooking.$q1$,$q1$Yellow-staining mushroom: gardens, parks, forest edges, compost heaps, ruderal/near-settlement areas. Sheep mushroom: fertilized meadows and pastures, especially sheep and horse pastures. Habitat alone does NOT separate them reliably (overlap possible).$q1$,$q1$In both species dark chocolate-brown to purple-brown (genus Agaricus) - NOT a distinguishing feature.$q1$,$q1$Cut the stem base lengthwise: if it turns immediately intense chrome-yellow AND the mushroom smells of ink/carbolic instead of anise, leave it - yellow-staining mushroom. Rule of thumb: any champignon with a carbolic/ink smell or a bright chrome-yellow stem base = toxic, do not eat.$q1$,array[$q1$Smell is the most important feature: sheep mushroom pleasantly of anise/marzipan; yellow-staining mushroom unpleasantly of ink/carbolic/phenol - intensifying when rubbing the stem base and when heating.$q1$,$q1$Cut the stem base lengthwise: yellow-staining mushroom discolors IMMEDIATELY intense chrome-yellow, concentrated at the stem base; sheep mushroom yellows only weakly over the whole fruiting body and not concentrated at the stem base.$q1$,$q1$Both have a ring and gills that mature from pale-pink to chocolate-brown, and both have dark-brown spore powder - therefore ONLY the stem-base cut (chrome-yellow) AND the smell test reliably separate them, not the gills or spore color.$q1$]::text[],true),
($q1$roetling$q1$,$q1$amanita_phalloides$q1$,$q1$en$q1$,$q1$Death cap: cap olive/yellow-greenish with ingrown radial fibers (the white form var. alba also pure white), PURE WHITE gills, bulbous stem base with a membranous sheath (volva). Sheep mushroom: cream-white cap, gills pink -> chocolate-brown, NO membranous sheath.$q1$,$q1$Sheep mushroom: pleasant anise/marzipan smell. Death cap: when young sweetish-honey-like, with age unpleasant - NO anise.$q1$,$q1$Amanita phalloides: mycorrhizal mushroom predominantly with oaks and beeches in the forest. Sheep mushroom: free-standing on meadows and pastures without tree association. Habitat alone is NOT a reliable feature.$q1$,$q1$DECISIVE: sheep mushroom dark chocolate-brown to purple-brown; Amanita phalloides PURE WHITE. White spore deposit = never eat.$q1$,$q1$Never collect young, still-closed white 'champignons' with pale gills - precisely in the button stage the deadly death cap looks most similar to the champignon. Dig up the entire stem base (volva present?) and treat pure-white gills as well as a white spore deposit as an absolute stop signal.$q1$,array[$q1$Gills: the death cap always has PURE WHITE gills; champignon gills are pale-pink when young (very young buttons exceptionally cream-white) and mature via gray-pink to chocolate-brown. In the button stage do not trust gill color alone - then volva + spore deposit are mandatory.$q1$,$q1$Stem base: distinctly set-off bulb with a membranous sheath (volva) in the death cap; the champignon lacks the volva. Always dig up the stem base completely.$q1$,$q1$Do NOT use cap color as the main feature: typically olive/yellow-green, but as var. alba also pure white - therefore always check gills + volva + spore powder, never just the color.$q1$,$q1$Spore powder white (champignon dark brown) - the most reliable single feature.$q1$]::text[],true),
($q1$russula_virescens$q1$,$q1$amanita_phalloides$q1$,$q1$en$q1$,$q1$Green coloration similar, especially when young; the Russula cap skin cracks into a mosaic-like (felty) pattern.$q1$,$q1$Russula mild/nutty; death cap honey-like (when old)$q1$,$q1$both deciduous forest$q1$,$q1$Russula white, A. phalloides white$q1$,$q1$DEADLY. With green mushrooms ALWAYS dig out the whole mushroom: are BOTH ring AND volva absent? Otherwise do not eat.$q1$,array[$q1$Russula: brittle gills, NO ring, NO bulb/volva$q1$,$q1$Death cap: ring + membranous volva at a bulbous base, flexible gills$q1$]::text[],true),
($q1$russula_cyanoxantha$q1$,$q1$amanita_phalloides$q1$,$q1$en$q1$,$q1$Violet-green specimens can be confused visually; the gill test (flexible vs. not) + the stem base are decisive.$q1$,$q1$Russula mild$q1$,$q1$both deciduous forest (beech/oak)$q1$,$q1$both white$q1$,$q1$DEADLY. Expose the stem base: any bulb with a membranous sheath = mortal danger.$q1$,array[$q1$Charcoal burner (Russula cyanoxantha): flexible, greasy gills (do not splinter), NO ring, NO volva$q1$,$q1$Death cap: ring + volva, deadly amatoxins$q1$]::text[],true),
($q1$roetling$q1$,$q1$amanita_verna$q1$,$q1$en$q1$,$q1$Spring destroying angel (Amanita verna): pure white cap, PURE WHITE gills (even when old), stem base with a bulbous, membranous, sack-like sheath (volva), often deep in the soil. Sheep mushroom (field/horse champignon): cream-white cap, gills mature pink -> grey-pink -> chocolate brown, NO volva, at most a slightly thickened stem base.$q1$,$q1$Sheep mushroom: pleasant anise/marzipan smell. Amanita verna: nearly odorless to faintly sweetish/honey-like, unpleasant when old - NO anise.$q1$,$q1$Amanita verna: mycorrhizal fungus, grows in woodland (deciduous/mixed forest), mainly in spring, with a tree association. Sheep mushroom: saprotrophic on open meadows and pastures without a tree association. Caution: habitat alone is NOT a reliable feature.$q1$,$q1$DECISIVE and 100% reliable: sheep mushroom dark chocolate brown to purple-brown; Amanita verna PURE WHITE. With a white spore print NEVER eat it as a champignon.$q1$,$q1$With every white 'champignon' ALWAYS fully dig out and expose the stem base: if a bulbous membranous sheath (volva) is found OR the gills stay pure white - life-threatening, leave it standing. When in doubt make a spore print: white = death cap (Knollenblätterpilz), never eat. Do not even collect young, closed white buttons in the first place.$q1$,array[$q1$Gills: Amanita verna has pure white gills at EVERY age; the sheep mushroom has them pale-pink when young (very young buttons can be cream-white!), later grey-pink to chocolate brown. IMPORTANT: In the button stage the gill color alone is NOT reliable - then you must check volva + spore print.$q1$,$q1$Stem base: Amanita verna has a distinctly set-off bulb with a membranous, sack-like sheath (volva); the champignon has NO volva. Always dig out the stem base completely as well - the volva often sits deep in the soil.$q1$,$q1$Spore powder: champignon dark brown, Amanita verna pure WHITE - the spore print is the most reliable single feature.$q1$,$q1$Smell: sheep mushroom smells of anise; Amanita verna without anise smell (neutral to sweetish-honey-like) - a missing anise smell is a warning sign, but NEVER replaces the volva/spore check.$q1$]::text[],true),
($q1$russula_vesca$q1$,$q1$russula_emetica$q1$,$q1$en$q1$,$q1$R. vesca: dull flesh- to wine-red/red-brown, often faded and irregularly blotchy, cap margin with a receding (too-short) cap skin, so that the gill edges protrude tooth-like. R. emetica: uniformly bright cherry-/blood-red, slimy-glossy when moist, cap skin covering right to the margin and peelable far (often to the center of the cap).$q1$,$q1$Both largely inconspicuous/slightly fruity; the smell does NOT separate these two species. The taste is decisive (mild vs. burning sharp).$q1$,$q1$R. emetica: moist/acidic bog and coniferous forests (spruce, pine, silver fir), often mossy. R. vesca: deciduous and mixed forest with beech and oak, rather fresh to dry soils.$q1$,$q1$Both white to whitish – the spore powder does NOT separate these two species. Do not use for distinguishing.$q1$,$q1$Taste test by the Russula rule: chew a small piece of cap with gills, spit it out, do not swallow – mild = edible Russula, sharp/burning = sickener (Speitäubling, poisonous, discard). The rule applies ONLY if the mushroom has been identified beyond doubt as a Russula (brittle-breaking, splintering gills, no stem ring, no volva). R. emetica is not deadly, but causes days of severe gastrointestinal distress.$q1$,array[$q1$Taste (Russula rule, the decisive distinguishing feature): R. vesca is mild and pleasantly nutty; R. emetica tastes immediately burning sharp/peppery. Briefly chew a small piece of cap with gills, do NOT swallow, spit out completely – only apply if the mushroom has been identified beyond doubt as a Russula (brittle-breaking gills, no ring, no volva).$q1$,$q1$Cap color: R. vesca dull flesh-/wine-red to red-brown, often blotchily fading; R. emetica bright blood-, cherry- to purple-red, sticky-glossy when wet.$q1$,$q1$Shortened cap skin (key feature of R. vesca): the cap margin recedes, so that cap flesh and gill ends protrude tooth-like beyond the margin – absent in R. emetica (cap skin covers to the margin and can be peeled far, often to the center of the cap).$q1$,$q1$Location: R. emetica typically in moist bog and coniferous forests (spruce, pine, silver fir, often mossy/acidic); R. vesca mainly in deciduous/mixed forest with beech and oak.$q1$]::text[],true),
($q1$russula_vesca$q1$,$q1$amanita_phalloides$q1$,$q1$en$q1$,$q1$Decisive and binding is the stem base: in A. phalloides a membranous white volva around a bulbous stem base plus a hanging, grooved ring; free, soft gills. R. vesca has a straight-tapering, bulb- and ringless stem base and brittle-breaking, attached gills. Color is NOT a reliable criterion: phalloides is usually olive-/yellow-green (also white as var. alba); the flesh-red cap color of vesca is at most a hint. The typical color confusion of the death cap is with GREEN edible Russulas, not with the red vesca – therefore always secure the identification morphologically at the stem base.$q1$,$q1$Older death cap smells sweetish like artificial honey to unpleasant; edible Russula smells mild/inconspicuous. Smell is ONLY an indication, never the safety criterion.$q1$,$q1$Both mycorrhizal fungi with deciduous trees (oak, beech, sweet chestnut) – location does NOT separate them reliably, hence morphological examination at the stem base is mandatory.$q1$,$q1$Both white – the spore powder does NOT distinguish these species and must not be used as an all-clear.$q1$,$q1$ALWAYS dig out the mushroom whole with the stem base (do not cut it off!) and check for bulb + membranous white volva + stem ring. If a volva/bulb/ring is found or the gills are soft and free, it is NOT a Russula – do not apply the Russula rule/taste test, because amatoxins taste MILD and are deadly. Color is never the criterion. In Switzerland: at any doubt go to the official VAPKO mushroom inspection.$q1$,array[$q1$Bulb/volva at the stem base: A. phalloides ALWAYS has a membranous, sack-like white sheath (volva) around a distinct bulb – Russulas NEVER have a volva and no bulb. This is the binding criterion, color is NOT.$q1$,$q1$Stem ring: A. phalloides carries a hanging, membranous, grooved ring (skirt) on the upper stem – Russulas are ringless.$q1$,$q1$Gills: Russula = brittle-breaking, splintering gills attached to the stem (brittle-gilled); A. phalloides = soft, flexible, FREE (not attached to the stem) gills. The taste test fails here because amatoxins taste MILD/nutty!$q1$,$q1$Cap color as a weak hint: A. phalloides is white-green/green/olive/yellow-green (rarely white, var. alba) – the flesh-red/wine-red color of R. vesca does NOT match it, but never replaces the stem-base check. The classic color confusion is with GREEN Russulas, not with the red edible Russula.$q1$]::text[],true),
($q1$schopftintling$q1$,$q1$amanita_phalloides$q1$,$q1$en$q1$,$q1$Inky cap (Shaggy ink cap): white-scaly, egg-shaped. Death cap (Amanita phalloides): olive-green, smooth.$q1$,null,$q1$Inky cap: meadows, roadsides. Death cap: deciduous forest.$q1$,$q1$Inky cap: black. Death cap: white.$q1$,$q1$The inky cap's gills turn black; the death cap's NEVER do.$q1$,array[$q1$Shaggy ink cap: egg-shaped, scaly cap; death cap: smooth$q1$,$q1$Inky cap in meadows, death cap in woodland$q1$]::text[],true),
($q1$semmelstoppelpilz$q1$,$q1$austernpilz$q1$,$q1$en$q1$,$q1$Hedgehog mushroom: on the ground in mixed forest. Oyster mushroom: on a tree trunk.$q1$,null,$q1$Ground vs. tree$q1$,null,$q1$Both are suitable for beginners.$q1$,array[$q1$Hedgehog mushroom has SPINES; oyster mushroom has GILLS$q1$,$q1$Ground vs. tree trunk$q1$]::text[],true),
($q1$steinpilz$q1$,$q1$butterpilz$q1$,$q1$en$q1$,$q1$Porcini (cep): white-netted stem, no ring. Slippery jack (Butterpilz): slimy cap, ring.$q1$,null,$q1$Both in coniferous forest; slippery jack under pine.$q1$,null,$q1$Peel the skin off the slippery jack's cap.$q1$,array[$q1$Porcini: smooth stem; slippery jack: ring + slimy cap$q1$]::text[],true),
($q1$steinpilz$q1$,$q1$tylopilus_felleus$q1$,$q1$en$q1$,$q1$Pore colour (white/yellow vs. pink) + netting (fine-white vs. coarse-dark).$q1$,$q1$Bitter bolete (Tylopilus felleus) is extremely bitter (tiny taste sample, spit it out)$q1$,$q1$Both in acidic coniferous/mixed forests, often together$q1$,$q1$Porcini olive, bitter bolete pink$q1$,$q1$Not poisonous, but a single bitter bolete ruins an entire dish. Pink pores + coarse netting + bitterness give it away.$q1$,array[$q1$Porcini: fine white netting, white/yellow pores, mild$q1$,$q1$Bitter bolete: coarse dark netting, pink pores, extremely bitter$q1$]::text[],true),
($q1$zigeunerpilz$q1$,$q1$cortinarius_orellanus$q1$,$q1$en$q1$,$q1$Gypsy mushroom (Cortinarius caperatus): straw-yellow to yellow-brown, grey-whitish-lilac frosted, longitudinally wrinkled cap with a double-edged membranous ring. Fool's webcap (Cortinarius orellanus): deep orange to copper-/rust-brown, dull-fibrous to finely scaly, dry cap WITHOUT any frosting; NO true ring, only a fleeting cortina; stem cylindrical, of the same colour or yellowish, not distinctly banded (unlike rubellus).$q1$,$q1$Gypsy mushroom: mild. Fool's webcap: faintly radish-like.$q1$,$q1$Gypsy mushroom: coniferous and (rarely) deciduous forest, often on acidic sandy soil, near bilberry. Fool's webcap: warmth-favoured deciduous forests near oak, beech, hazel, sweet chestnut on acidic to basic soils (July–October) — typically not coniferous forest.$q1$,$q1$Gypsy mushroom: pale cinnamon-brown/rust-yellow. Fool's webcap: rust-brown. No single reliably distinguishing feature.$q1$,$q1$Only eat the gypsy mushroom if it has a clear, firm ring with a double edge. A deep orange-/rust-brown, dry-fibrous cap WITHOUT frosting and without a true ring (only veil fibres) points to the deadly fool's webcap — hands off, take it to mushroom inspection (VAPKO).$q1$,array[$q1$The gypsy mushroom has a firm membranous stem ring with a double edge; the fool's webcap has NO true ring, only fleeting veil fibres (cortina).$q1$,$q1$The gypsy mushroom's cap is grey-lilac frosted and wrinkled; the webcap's cap is dry-fibrous to finely scaly and uniformly deep orange-/copper-/rust-brown without frosting.$q1$,$q1$The webcap's stem is of the same colour to yellowish and not distinctly banded; the gypsy mushroom's stem bears the membranous double-edged collar.$q1$,$q1$The toxin orellanine is heat-/drying-resistant and, after a latency of days to weeks (3–14 days), leads to fatal kidney failure — no taste test and no detoxifying through cooking is possible.$q1$]::text[],true),
($q1$zigeunerpilz$q1$,$q1$cortinarius_rubellus$q1$,$q1$en$q1$,$q1$Gypsy mushroom (Reifpilz): straw-yellow to yellow-brown cap with a grey-whitish-lilac bloom (veil), surface characteristically longitudinally wrinkled/furrowed, with a distinct membranous stem ring that has a double margin. Cortinarius rubellus (Deadly webcap, Raukopf): yellow- to orange- or reddish-foxy cinnamon-brown, dry and finely felty cap with a pointed (or rounded) umbo, NO true ring (only fleeting cortina/veil remnants), stem slender and yellowish snake-banded (yellow veil girdles).$q1$,$q1$Gypsy mushroom (Reifpilz): pleasant/mild. Deadly webcap (Spitzgebuckelter Raukopf): faintly radish-like.$q1$,$q1$Gypsy mushroom (Reifpilz): coniferous and (rarely) deciduous forest, fond of growing near blueberry on acidic, sandy soil, August-October. Deadly webcap (Spitzgebuckelter Raukopf): above all coniferous forest (spruce stands), often in damp/boggy locations on acidic soils, near blueberry — the habitat overlap heightens the risk.$q1$,$q1$Gypsy mushroom (Reifpilz): pale cinnamon-brown to rusty-yellow. Cortinarius rubellus: rust-brown. The spore colour does NOT reliably separate them here — never use it as the sole feature.$q1$,$q1$Look on the stem for the firm membranous ring with its characteristic DOUBLE margin — if this ring is missing and the stem is instead yellowish snake-banded with only fleeting veil fibres, then it is not a Gypsy mushroom but possibly the deadly webcap. When in doubt about young specimens, ALWAYS take it to the mushroom inspection office (VAPKO).$q1$,array[$q1$The Gypsy mushroom has a firm, membranous stem ring with a characteristic DOUBLE margin; the deadly webcap (Spitzgebuckelter Raukopf) has NO true ring, only fleeting veil fibres (cortina).$q1$,$q1$The Gypsy mushroom's cap is dull grey-whitish to lilac BLOOMED and longitudinally wrinkled; the webcap has a dry, finely felty-fibrous, reddish-foxy cinnamon-brown cap with a distinct POINTED umbo.$q1$,$q1$The webcap's stem is slender and yellowish SNAKE-BANDED (yellow veil girdles); the Gypsy mushroom's stem is thicker and bears the membranous cuff instead of girdles.$q1$,$q1$Eat only when an unambiguous double-margined ring is present; the toxin orellanine is heat- and drying-stable and causes irreversible kidney failure after a latency of 2-21 days — no cooking/drying detoxifies it.$q1$]::text[],true),
($q1$agaricus_augustus$q1$,$q1$agaricus_xanthodermus$q1$,$q1$es$q1$,$q1$Olor + decoloración en la base del pie (anís vs. carbol/fenol; ligeramente amarillo vs. amarillo cromo).$q1$,$q1$Anís (comestible) vs. carbol/fenol/tinta (tóxico) — el criterio más importante$q1$,$q1$ambos en bosque/parque/jardín$q1$,$q1$ambos marrón chocolate$q1$,$q1$Cortar la base del pie: amarillo cromo intenso + olor a carbol/fenol = champiñón amarilleante (Agaricus xanthodermus, tóxico). En los champiñones blancos, descartar además la volva (Amanita / oronja mortal).$q1$,array[$q1$Champiñón gigante (Agaricus augustus): olor a anís/almendra, amarilleo débil$q1$,$q1$Champiñón amarilleante (Agaricus xanthodermus): olor a carbol/fenol/tinta (se intensifica al calentar), base del pie de color amarillo cromo$q1$]::text[],true),
($q1$agaricus_campestris$q1$,$q1$amanita_phalloides$q1$,$q1$es$q1$,$q1$Champiñón: sombrero blanco-beige, láminas rosadas que se vuelven marrones. Oronja mortal (Amanita phalloides): sombrero verde oliva, láminas blancas que permanecen blancas.$q1$,$q1$Champiñón: agradable, a hongo. Oronja mortal: ligeramente dulzón.$q1$,$q1$Champiñón: prados, pastizales. Oronja mortal: bosque de frondosas, robles.$q1$,$q1$Champiñón: marrón oscuro. Oronja mortal: blanco.$q1$,$q1$SIEMPRE comprobar la base del pie — bulbo dentro de una funda membranosa (volva) = ¡NUNCA comer!$q1$,array[$q1$El champiñón NUNCA tiene bulbo dentro de una funda; la oronja mortal siempre$q1$,$q1$Las láminas del champiñón se vuelven rosadas y marrón chocolate; las de la oronja mortal permanecen blancas$q1$]::text[],true),
($q1$amanita_rubescens$q1$,$q1$amanita_pantherina$q1$,$q1$es$q1$,$q1$Decide la prueba de enrojecimiento + el anillo (estriado vs. liso) + el bulbo.$q1$,$q1$apenas distinguibles$q1$,$q1$ambos en todos los tipos de bosque$q1$,$q1$ambos blanco$q1$,$q1$La amanita rojiza (Amanita rubescens) solo para personas con experiencia. Comprobar TODAS las características EN CONJUNTO (enrojecimiento + anillo estriado + bulbo sin vaina con reborde).$q1$,array[$q1$Amanita rojiza (Amanita rubescens): la carne enrojece (sobre todo en la base del pie / galerías de larvas), anillo estriado, copos del velo grises$q1$,$q1$Amanita pantera (Amanita pantherina): la carne NUNCA enrojece, anillo liso, copos blanco puro, base bulbosa con reborde, toxinas termoestables$q1$]::text[],true),
($q1$austernpilz$q1$,$q1$galerina_marginata$q1$,$q1$es$q1$,$q1$Seta de ostra (Pleurotus): sombrero en forma de concha/abanico de 5-25 cm, blanco/gris/marrón, en grupos imbricados (como tejas); pie lateral o ausente; láminas anchas, blanquecinas y decurrentes. Galerina (Galerina marginata): sombrerito pequeño y convexo de color ocre a marrón canela de 1-4 cm, con pie central delgado y parduzco, zona anular en el tercio superior del pie; con la edad, láminas de color marrón canela.$q1$,$q1$Seta de ostra: suave, agradable, a hongo y ligeramente a anís. Galerina: débilmente harinoso o inapreciable — el olor NO es una característica distintiva segura, por lo que no hay que fiarse de él.$q1$,$q1$Ambas sobre madera, pero: la seta de ostra prefiere madera de frondosas (haya/álamo), en grupos a modo de consolas, a menudo a gran altura en el tronco; la galerina crece sobre madera muerta y podrida (con frecuencia coníferas, pero también frondosas), pequeña, solitaria a agrupada, más bien a ras de suelo o sobre troncos caídos.$q1$,$q1$Seta de ostra: BLANCO a lila-grisáceo pálido. Galerina: MARRÓN HERRUMBRE/CANELA. Esta es la característica individual más fiable — la esporada separa ambas con seguridad.$q1$,$q1$Regla de oro: una verdadera seta de ostra se asienta de forma lateral/sin pie como una consola gruesa y carnosa sobre la madera y da una esporada BLANCA a lila-grisácea. En cuanto hay un pie central con restos de anillo O la esporada resulta marrón, NO es una seta de ostra — entonces, no tocar (la galerina contiene amatoxinas mortales, el mismo veneno que la oronja mortal/Amanita phalloides). En caso de duda, hacer siempre una esporada antes de comer.$q1$,array[$q1$Esporada: seta de ostra blanca a lila-grisácea; galerina marrón herrumbre/canela (la esporada sobre papel oscuro y claro es la característica distintiva más segura).$q1$,$q1$Pie: la seta de ostra tiene un pie lateral/excéntrico, corto o casi ausente, y NINGÚN anillo; la galerina tiene un pie central y delgado con restos membranosos de una zona anular en el tercio superior.$q1$,$q1$Forma de crecimiento: la seta de ostra crece de forma imbricada (como tejas) en grupos/consolas gruesos y carnosos directamente sobre la madera; la galerina crece pequeña, solitaria a agrupada, con un sombrerito convexo de carne fina sobre madera muerta.$q1$,$q1$Láminas: la seta de ostra con láminas anchas, blanquecinas y decurrentes sobre el pie (lateral); la galerina con láminas estrechas, de jóvenes de color ocre pálido y que con la edad viran a marrón canela (por el polvo de esporas marrón).$q1$,$q1$Tamaño/consistencia: la seta de ostra grande (sombrero de 5-25 cm), de carne dura; la galerina pequeña (sombrero por lo general de 1-4 cm), frágil, con un pie marcado como una seta laminada normal.$q1$]::text[],true),
($q1$calocybe_gambosa$q1$,$q1$inocybe_erubescens$q1$,$q1$es$q1$,$q1$Ambos de primavera, claros; el Inocybe (Inocybe erubescens) es de fibras radiales/agrietado y enrojece, mientras que la seta de San Jorge (Calocybe gambosa) es lisa y carnosa.$q1$,$q1$Seta de San Jorge: fuertemente harinoso, a pepino; Inocybe: dulzón-espermático$q1$,$q1$ambos en prados / bordes de bosque, en suelos calcáreos, misma temporada$q1$,$q1$Seta de San Jorge blanco, Inocybe marrón$q1$,$q1$MORTAL (muscarina). Láminas blancas + olor harinoso + ausencia de enrojecimiento son obligatorios — de lo contrario, no tocar.$q1$,array[$q1$Seta de San Jorge (Calocybe gambosa): láminas blancas a cualquier edad + olor harinoso, la carne NO enrojece$q1$,$q1$Inocybe (Inocybe erubescens): la carne enrojece, láminas de color gris-marrón, polvo de esporas marrón, alto contenido en muscarina$q1$]::text[],true),
($q1$champignon-de-paris$q1$,$q1$agaricus_xanthodermus$q1$,$q1$es$q1$,$q1$Champiñón amarilleante (Karbol/de bosque): la base del pie se vuelve inmediatamente de color amarillo cromo al cortarla, el centro del sombrero a menudo es grisáceo-metálico, la base del pie es bulbosa sin piel lobulada. Champiñón de cultivo/champiñón de prado: la superficie de corte permanece blanquecina o ligeramente rojiza, sin base del pie amarilla.$q1$,$q1$El champiñón amarilleante huele penetrante a carbólico/fenol/tinta (se intensifica al calentarlo y al frotar la base del pie). Los champiñones comestibles huelen agradablemente a hongo, a nuez o a anís.$q1$,$q1$Ambos en prados ricos en nutrientes, pastizales, parques y bordes de bosque, de verano a otoño; el hábitat NO ayuda a distinguirlos.$q1$,$q1$Ambos de color marrón chocolate; aquí el color de la esporada NO es un rasgo distintivo; fijarse en el amarilleamiento y en el olor.$q1$,$q1$Cortar la base del pie longitudinalmente: un amarilleamiento intenso de color amarillo cromo en la base del pie + olor a carbólico/tinta = tóxico, desechar el hongo. No probar por vía oral. Las consecuencias son molestias gastrointestinales fuertes (náuseas, vómitos, diarrea), por lo general no potencialmente mortales.$q1$,array[$q1$La base del pie se vuelve inmediatamente de un intenso amarillo cromo (amarillo brillante) al cortarla/aplastarla; los champiñones comestibles amarillean a lo sumo levemente en el borde del sombrero, NUNCA de forma intensa en la base del pie.$q1$,$q1$Huele desagradablemente a carbólico/fenol o a tinta (se percibe mejor en la base del pie frotada o al calentarlo); los champiñones comestibles huelen a hongo, a nuez o a anís/almendra.$q1$,$q1$Base del pie engrosada de forma bulbosa SIN piel lobulada/volva; el sombrero joven a menudo con un brillo gris-metálico en el centro; láminas rosadas de jóvenes, marrón chocolate oscuro con la edad.$q1$,$q1$Lugar de crecimiento idéntico (prados, pastizales, parques, bordes de bosque, suelos ricos en nutrientes), por lo que la confusión real es frecuente; el hábitat NO ayuda a distinguirlos.$q1$]::text[],true),
($q1$champignon-de-paris$q1$,$q1$amanita_phalloides$q1$,$q1$es$q1$,$q1$Amanita phalloides: láminas que permanecen blancas, volva membranosa blanca en la base bulbosa del pie, sombrero de verde oliva hasta (var. alba/joven) blanco. Champiñón: láminas de color rosa-marrón, sin volva, base del pie sin vaina.$q1$,$q1$Amanita phalloides de joven inodora; de vieja huele a moho dulzón, como a miel artificial, hasta desagradable. El champiñón huele agradablemente a hongo/nuez/anís.$q1$,$q1$Amanita phalloides es un hongo micorrícico de bosques de frondosas (sobre todo bajo roble, haya); los champiñones crecen en terreno agrícola abierto, prados y pastizales.$q1$,$q1$Amanita phalloides blanca, champiñón marrón; una esporada blanca es una clara señal de alarma.$q1$,$q1$Partir longitudinalmente el botón/huevo blanco sospechoso: la presencia de láminas blancas + envoltura de volva en la base = oronja verde (Amanita phalloides), mortal. Ya unos 20 g aprox. son potencialmente mortales; en caso de duda, control de hongos VAPKO / Tox Info Suisse 145.$q1$,array[$q1$Láminas siempre de un blanco puro (también en el ejemplar viejo); las láminas del champiñón son rosadas de jóvenes y marrones/marrón negruzco de viejas.$q1$,$q1$Base del pie con una base bulbosa rodeada por una vaina membranosa lobulada blanca (volva); en el champiñón la volva falta por completo.$q1$,$q1$Esporada blanca (champiñón marrón).$q1$,$q1$Los ejemplares jóvenes se asemejan a un 'huevo' blanco y se confunden con especial facilidad con champiñones jóvenes cerrados; cortar siempre, en el corte se aprecia la estructura incipiente de láminas/volva blanca (interior uniformemente blanco-verdoso, nunca rosado).$q1$]::text[],true),
($q1$calvatia_gigantea$q1$,$q1$gemeiner-fliegenpilz-var-alba$q1$,$q1$es$q1$,$q1$Bejín (Bovist): piel blanca lisa y cerrada, redondeada, sin pie. A. virosa de joven: huevo de un blanco puro dentro de una envoltura membranosa; ya desarrollada de un blanco puro con sombrero cónico-puntiagudo, anillo y volva membranosa. En el estadio de huevo es externamente casi imposible de distinguir del bejín.$q1$,$q1$A. virosa madura: desagradable, dulzón-repugnante (ejemplares viejos). Bejín joven: suave, a hongo. El olor en el estadio joven/de huevo no es fiable; no debe interpretarse como autorización para consumir.$q1$,$q1$A. virosa: micorriza en bosques de coníferas/mixtos ácidos, a menudo junto a abeto rojo/abedul, más bien en regiones de montaña frías/montanas. Bejín gigante: praderas abiertas, pastizales, jardines. Menor solapamiento de hábitat que con phalloides, pero la prueba de corte sigue siendo obligatoria.$q1$,$q1$Bejín: sin láminas/sin esporada relevante. A. virosa: esporada blanca. En el estadio de huevo confundible no es utilizable; solo cuenta el corte.$q1$,$q1$En cualquier pequeño hongo esférico blanco, hacer un corte longitudinal: un 'embrión' de hongo blanco visible en el corte (pie + sombrero incipiente) delata a la oronja blanca (Amanita virosa). Solo una masa blanca sin estructura = bejín.$q1$,array[$q1$El huevo joven de A. virosa es de un BLANCO PURO y esférico, ópticamente casi idéntico a un bejín blanco joven. Precisamente por eso la prueba de corte es aquí lo más importante.$q1$,$q1$PRUEBA DE CORTE: bejín = masa blanca homogénea en toda su extensión; A. virosa muestra en el corte longitudinal ya láminas incipientes, pie y bulbo (silueta del hongo en su interior) = mortal.$q1$,$q1$A. virosa tiene una volva membranosa en forma de saco en la base del pie y (más tarde) un anillo; el bejín no tiene ni volva ni pie ni anillo.$q1$,$q1$La confusión solo es posible en el estadio joven, esférico; en cuanto en la Amanita aparecen sombrero/pie, la distinción es trivial.$q1$]::text[],true),
($q1$calvatia_gigantea$q1$,$q1$amanita_phalloides$q1$,$q1$es$q1$,$q1$Bejín gigante: piel exterior lisa, blanca a crema, cerrada, esférica, sin pie/envoltura/volva. A. phalloides joven en el huevo: envoltura general membranosa blanca a teñida de oliva, esférica-ovoide; externamente engañosamente similar, por lo que solo cuenta el corte.$q1$,$q1$Bejín joven: agradablemente suave, a hongo. A. phalloides madura: dulzón-amielado hasta desagradable; en el estadio de huevo apenas perceptible, por lo que NO es un rasgo fiable; nunca interpretar el olor como autorización para consumir.$q1$,$q1$Bejín gigante: prados, pastizales, jardines, bordes de caminos, suelos ricos en nutrientes (no es hongo micorrícico). A. phalloides: hongo micorrícico de bosques de frondosas/mixtos, sobre todo junto a roble y haya. Posible solapamiento en bordes de bosque/parques; el hábitat por sí solo no protege.$q1$,$q1$En el bejín no es relevante (sin láminas). A. phalloides: esporada blanca. En el estadio de huevo ninguno de los dos es concluyente; la distinción se hace únicamente mediante el corte longitudinal.$q1$,$q1$Cortar CADA pequeño 'bejín' esférico ANTES de usarlo, longitudinalmente (de arriba abajo) y por completo. Solo si la superficie es de un blanco puro y homogénea en toda su extensión —sin ninguna silueta de pie/láminas/sombrero— es un bejín. Ante la mínima estructura interna: oronja verde mortal, desechar todo el cesto.$q1$,array[$q1$PRUEBA DE CORTE (decisiva): el bejín gigante tiene una carne completamente homogénea, de un blanco puro y sin estructura interna. En la oronja verde joven en estadio de huevo, en el corte longitudinal ya se reconocen láminas incipientes, pie y bulbo como silueta/'embrión' = mortal, desechar de inmediato.$q1$,$q1$Color interior: el bejín joven es por dentro de un blanco puro y homogéneo. Cualquier coloración amarillenta/verdosa o una silueta de hongo más oscura en el corte = no es un bejín.$q1$,$q1$Envoltura exterior: el bejín tiene una piel exterior lisa, coriácea y cerrada, sin volva. El huevo de la oronja verde está dentro de una envoltura general membranosa (velo universal), a partir de la cual se forman la volva y la base del pie.$q1$,$q1$El bejín gigante maduro (>10 cm hasta 50 cm) es inconfundible; la confusión solo es posible con ejemplares jóvenes, pequeños y esféricos. Regla práctica: no comer ningún 'bejín' más pequeño que la palma de la mano sin control por corte.$q1$]::text[],true),
($q1$calvatia_gigantea$q1$,$q1$amanita_verna$q1$,$q1$es$q1$,$q1$Bejín: piel exterior blanca lisa, cerrada y sin estructura, esférica. A. verna joven: huevo de velo de un blanco puro; madura completamente blanca con volva membranosa y anillo. Los estadios de huevo son externamente casi idénticos.$q1$,$q1$A. verna: inodora a ligeramente desagradable. Bejín joven: suave, a hongo. No es un rasgo distintivo fiable en el estadio joven.$q1$,$q1$A. verna: micorriza en bosques de frondosas/mixtos cálidos (a menudo calcáreos) junto a roble/castaño, aparece sobre todo en primavera/comienzos de verano, de carácter mediterráneo (umbrales del sur/zonas soleadas). Bejín gigante: praderas/pastizales, más bien a finales de verano/otoño. Existen diferencias de temporada y hábitat, pero no sustituyen la prueba de corte.$q1$,$q1$Bejín no relevante. A. verna: esporada blanca. En el estadio de huevo carece de valor para la distinción; el corte es lo decisivo.$q1$,$q1$Corte longitudinal en cada pequeño hongo esférico blanco: si en la carne blanca aparece la silueta de un pequeño hongo (pie + esbozo del sombrero), es la oronja blanca de primavera, mortal, y no el bejín.$q1$,array[$q1$El huevo joven de A. verna es de un blanco puro y esférico como un bejín joven; la confusión es por ello real, sobre todo porque verna también crece en zonas más abiertas y cálidas.$q1$,$q1$PRUEBA DE CORTE: masa de bejín blanca y homogénea frente a pie + esbozo de láminas + bulbo ya reconocibles en el interior en la Amanita = mortal.$q1$,$q1$A. verna posee volva membranosa y bulbo en la base del pie; el bejín no tiene volva ni pie.$q1$,$q1$Solo el estadio joven esférico es confundible; la Amanita madura con sombrero/pie/anillo es inequívoca.$q1$]::text[],true),
($q1$champignon-de-paris$q1$,$q1$gemeiner-fliegenpilz-var-alba$q1$,$q1$es$q1$,$q1$Amanita virosa: sombrero blanco puro, a menudo cónico, las láminas permanecen blancas, base del pie bulbosa con volva blanca lobulada. Champiñón: láminas de rosa a marrón, sin volva, base del pie sin vaina membranosa.$q1$,$q1$Amanita virosa: discreto a dulzón-repugnante (carne en descomposición). Champiñón: agradable, a champiñón/anuez/anisado.$q1$,$q1$Amanita virosa en el bosque (a menudo abetos/bosque de coníferas, suelos ácidos); los champiñones en prados, pastos, compost, terreno cultivado.$q1$,$q1$Amanita virosa blanco, champiñón marrón – la esporada es un criterio de distinción fiable (blanco = peligro).$q1$,$q1$Extrae siempre el hongo completo, incluida la base del pie, girándolo fuera del suelo, y comprueba si hay una volva (vaina membranosa) en la base bulbosa – volva + láminas que permanecen blancas + esporada blanca = mortal, no lo toques. En caso de sospecha, Tox Info Suisse 145 / control de setas VAPKO.$q1$,array[$q1$Las láminas permanecen de un blanco puro a CUALQUIER edad – las láminas del champiñón son rosadas de jóvenes y se vuelven marrón chocolate hasta marrón negruzco al envejecer (nunca blancas de forma permanente).$q1$,$q1$En la base del pie hay una base bulbosamente engrosada con una vaina membranosa, lobulada y blanca (volva/envoltura del huevo) – los champiñones NUNCA tienen volva.$q1$,$q1$Esporada blanca; la esporada del champiñón es marrón.$q1$,$q1$Crece sobre todo en el bosque (de coníferas), a menudo junto a abetos – los champiñones prefieren prados, pastos y terreno cultivado.$q1$]::text[],true),
($q1$clitocybe_nebularis$q1$,$q1$entoloma_sinuatum$q1$,$q1$es$q1$,$q1$Entoloma sinuatum (pardillo gigante): sombrero más compacto y carnoso, de color gris claro a amarillo arcilloso/marfil; láminas de jóvenes blanquecino-amarillentas, de viejas de color rosa carne, cortas y unidas de forma escotada (sinuada), no decurrentes. Pardilla (Clitocybe nebularis): sombrero grande (10-25 cm) de color gris niebla con láminas blanquecino-cremosas, apretadas y brevemente decurrentes por el pie.$q1$,$q1$Pardilla: dulzón-especiado penetrante (percibido por muchos como desagradable). Pardillo gigante: harinoso-rancio con un matiz ácido-rabanoso desagradable.$q1$,$q1$Pardillo gigante: amante de la cal, en bosques caducifolios y mixtos (sobre todo haya, roble, carpe) sobre suelo calcáreo/arcilloso, más bien raro, de mayo a noviembre; crece solitario, en grupos O en corros de brujas. Pardilla: frecuente y a menudo en masa, bosque caducifolio y de coníferas, otoño tardío (oct-nov), forma también hileras y corros de brujas. ATENCIÓN: el crecimiento en corro de brujas NO sirve para la distinción — ambas especies lo presentan.$q1$,$q1$DECISIVO: pardillo gigante de color rosa carne a rosa pardo (rasgo del género Entoloma). Pardilla blanca a crema-amarillenta pálida. Una simple esporada sobre papel blanco distingue ambas con seguridad — es el carácter más fiable.$q1$,$q1$La esporada es obligatoria: polvo rosa/rosa carne = pardillo (Entoloma) = NO comer. La pardilla deja una esporada blanca a crema pálida y tiene láminas brevemente decurrentes y apretadas. NO te fíes de la forma de crecimiento — AMBAS especies pueden formar hileras y corros de brujas, eso NO es un carácter distintivo.$q1$,array[$q1$Esporada (carácter MÁS SEGURO): pardillo gigante de color rosa carne a rosa pardo (género Entoloma) — pardilla blanca a crema-amarillenta pálida. La esporada sobre papel blanco las distingue inequívocamente.$q1$,$q1$Color de las láminas al envejecer: las láminas del pardillo gigante son de jóvenes blanquecinas/amarillentas, de viejas claramente de color rosa CARNE por las esporas — las láminas de la pardilla permanecen blancas a crema-amarillentas, NUNCA rosadas.$q1$,$q1$Inserción de las láminas: las láminas de la pardilla son brevemente DECURRENTES por el pie (típico de Clitocybe), apretadas; las láminas del pardillo gigante están unidas de forma escotada (sinuada), cortas, rígidas y poco apretadas — NO decurrentes.$q1$,$q1$Olor: pardilla dulzón-especiado penetrante; pardillo gigante harinoso-rancio con un matiz ácido-rabanoso desagradable.$q1$]::text[],true),
($q1$eierschwamm$q1$,$q1$cortinarius_orellanus$q1$,$q1$es$q1$,$q1$Rebozuelo: amarillo yema con forma de embudo y pliegues. Cortinario (Cortinarius orellanus): pardo rojizo-anaranjado con láminas verdaderas.$q1$,$q1$Rebozuelo: afrutado a albaricoque. Cortinario: a rábano.$q1$,$q1$Rebozuelo: de mayo a octubre, bosque de coníferas. Cortinario: de septiembre a noviembre, bosque caducifolio.$q1$,$q1$Rebozuelo: amarillo pálido. Cortinario: pardo herrumbre.$q1$,$q1$REGLA DE ORO: dale la vuelta al sombrero — ¿láminas VERDADERAS o PLIEGUES? En caso de duda, ¡VAPKO!$q1$,array[$q1$El rebozuelo tiene PLIEGUES, el cortinario tiene láminas VERDADERAS$q1$,$q1$El rebozuelo es amarillo yema-albaricoque, el cortinario anaranjado-pardo rojizo$q1$]::text[],true),
($q1$eierschwamm$q1$,$q1$hygrophoropsis_aurantiaca$q1$,$q1$es$q1$,$q1$Pliegues (rebozuelo) frente a láminas verdaderas (falso rebozuelo); consistencia firme frente a blanda.$q1$,$q1$Rebozuelo afrutado (albaricoque); falso rebozuelo inespecífico/a moho$q1$,$q1$Rebozuelo en bosque caducifolio/de coníferas; falso rebozuelo sobre todo en hojarasca de coníferas/madera muerta$q1$,$q1$ambos pálidos$q1$,$q1$El falso rebozuelo es ligeramente tóxico (gastrointestinal). Comprobar pliegues romos frente a láminas afiladas y desprendibles. Si es de un naranja-rojo intenso, descartar además el hongo del olivo (Omphalotus, tóxico).$q1$,array[$q1$Rebozuelo verdadero: pliegues romos, firmemente soldados, de carne firme$q1$,$q1$Falso rebozuelo: láminas verdaderas finas, muy bifurcadas, fácilmente desprendibles, blandas$q1$]::text[],true),
($q1$hallimasch$q1$,$q1$cortinarius_orellanus$q1$,$q1$es$q1$,$q1$Armillaria (hallimasch): amarillo miel con anillo, en grupos cespitosos. Cortinario (Cortinarius orellanus): anaranjado-pardo rojizo, solitario.$q1$,$q1$Armillaria: agrio. Cortinario: a rábano.$q1$,$q1$Armillaria: tocones, raíces. Cortinario: suelo, bosque caducifolio.$q1$,$q1$Armillaria: blanco. Cortinario: pardo herrumbre.$q1$,$q1$Presta especial atención con los hongos jóvenes. Haz una esporada.$q1$,array[$q1$Armillaria tiene anillo + es parásita sobre el árbol; el cortinario es solitario$q1$,$q1$Esporada: Armillaria blanca, cortinario pardo herrumbre$q1$]::text[],true),
($q1$kuehneromyces_mutabilis$q1$,$q1$galerina_marginata$q1$,$q1$es$q1$,$q1$Ambos de color pardo miel, higrófanos, en grupos cespitosos sobre madera — ópticamente muy similares; lo único que los distingue es el pie por debajo de la zona anular (escamoso frente a liso).$q1$,$q1$ambos con olor fúngico, sin distinción olfativa fiable$q1$,$q1$ambos sobre madera muerta/tocones, a menudo mezclados$q1$,$q1$ambos pardo herrumbre$q1$,$q1$MORTAL. Prohibido para principiantes. Recolectar únicamente con el pie completo y revisar cada ejemplar por separado — en caso de duda, llevar al control de VAPKO.$q1$,array[$q1$Pie por debajo del anillo: la seta de los tocones (Stockschwämmchen) es escamosa/pruinosa, la Galerina venenosa (Gifthäubling) es lisa-sedosa$q1$,$q1$La Galerina venenosa contiene amatoxinas mortales$q1$]::text[],true),
($q1$infundibulicybe_geotropa$q1$,$q1$clitocybe_rivulosa$q1$,$q1$es$q1$,$q1$Clitocybe acanalado y pruinoso (Rinnigbereifter Trichterling): hasta 4-5 cm, blanco tiza pruinoso, deprimido sin mamelón, pie delgado. Cabeza de monje (Mönchskopf): 12-25 cm, crema/pardo cuero, con mamelón central, pie grueso y claviforme.$q1$,$q1$La cabeza de monje es aromática y dulzona con una nota de almendra amarga; el clitocybe acanalado y pruinoso es inconspicuo a débil. Utilizar el olor solo como carácter complementario, nunca de forma aislada.$q1$,$q1$Clitocybe acanalado y pruinoso: céspedes, prados, bordes de caminos, dunas, taludes, parques (en la hierba, en grupos/corros de brujas). Cabeza de monje: bosque de frondosas/coníferas sobre suelo calcáreo, lindes de bosque, claros de bosque. Bosque frente a pastizal abierto es el criterio de localización relevante.$q1$,$q1$Ambos BLANCO - no es posible distinguirlos por el color de las esporas; deciden el tamaño + el grosor de la carne + la localización + el mamelón.$q1$,$q1$Cualquier clitocybe pequeño, blanco tiza y pruinoso en la hierba/césped es sospechoso de muscarina - en caso de sospecha, dejarlo. La cabeza de monje es grande (12-25 cm), de carne gruesa, ligada al bosque y tiene un mamelón central palpable - no es la delicada y pequeña seta blanca de prado. Un polvo de esporas blanco NO descarta el clitocybe venenoso, ya que este también esporula en blanco.$q1$,array[$q1$Tamaño: el clitocybe acanalado y pruinoso solo hasta aprox. 4-5 cm de sombrero, blanco tiza pruinoso, deprimido/hundido sin mamelón; la cabeza de monje 12-25 cm, de carne gruesa, con un mamelón central claramente palpable.$q1$,$q1$Ambos blanquecino-infundibuliformes con láminas decurrentes y polvo de esporas BLANCO - solo el tamaño, el grosor de la carne y el mamelón del sombrero los separan con seguridad, el color y el polvo de esporas NO.$q1$,$q1$Muy venenoso por muscarina (síndrome muscarínico: fuerte salivación/sudoración/lagrimeo en 15-30 min, en casos graves colapso circulatorio), a menudo en las mismas localizaciones de prados/bordes de caminos/dunas en grupos o corros de brujas.$q1$,$q1$Pie delicado/delgado en el clitocybe venenoso frente a robusto-claviforme (2-4 cm de grosor) en la cabeza de monje.$q1$]::text[],true),
($q1$infundibulicybe_geotropa$q1$,$q1$clitocybe_dealbata$q1$,$q1$es$q1$,$q1$Cabeza de monje (Mönchskopf): 12-25 cm, color crema/cuero hasta ocre-rojizo en la vejez, mamelón central palpable, pie robusto-claviforme. Clitocybe de los campos (Feldtrichterling): solo 2-5 cm, blanco tiza pruinoso, deprimido/plano sin mamelón, pie delgado y delicado.$q1$,$q1$La cabeza de monje huele aromática y dulzona con una clara nota de almendra amarga; el clitocybe de los campos insignificante a débilmente harinoso. Atención: el olor es un carácter DE APOYO, nunca el único criterio de seguridad - combinar siempre con el tamaño/mamelón/grosor de la carne.$q1$,$q1$Clitocybe de los campos: pastizal abierto, prados, pastos, céspedes, bordes de caminos, parques. Cabeza de monje: bosque de frondosas y coníferas, lindes de bosque, claros de bosque sobre suelo calcáreo húmedo. Ambos pueden formar corros de brujas - el tipo de localización (bosque frente a hierba abierta) es más relevante que el crecimiento en corros.$q1$,$q1$Ambos BLANCO - el polvo de esporas NO ayuda aquí a distinguirlos. La separación se realiza por el tamaño, el grosor de la carne, el mamelón del sombrero y el grosor del pie.$q1$,$q1$Regla de oro: los clitocybes blancos PEQUEÑOS (de menos de aprox. 6 cm, de carne delgada, sin mamelón palpable en el sombrero) NUNCA comerlos - contienen muscarina y como grupo son confundibles de forma potencialmente mortal. Tomar únicamente la cabeza de monje grande (12-25 cm), de carne gruesa, con un mamelón central claramente palpable en el sombrero y pie robusto. Los corros de brujas y el polvo de esporas blanco los tienen AMBOS - NO sirven para distinguirlos.$q1$,array[$q1$Tamaño/carne: el clitocybe de los campos solo 2-5 cm de sombrero, de carne delgada (pocos mm); la cabeza de monje 12-25 cm, de carne gruesa y con un mamelón/verruga central claramente palpable en el centro del sombrero (prueba del dedo) - el mamelón le falta siempre al clitocybe de los campos.$q1$,$q1$Ambos blanco/cremosos e infundibuliformes con láminas decurrentes y polvo de esporas BLANCO - el color del sombrero y el polvo de esporas NO ayudan, solo el tamaño + el grosor de la carne + el mamelón + la localización los separan con seguridad.$q1$,$q1$Localización/temporada: el clitocybe de los campos en prados, pastos, bordes de caminos, céspedes, parques (de principios de verano a finales de otoño, a menudo en corros de brujas); la cabeza de monje en bosque de frondosas/coníferas, en lindes de bosque y en claros de bosque sobre suelo calcáreo húmedo (de finales de verano a otoño, también corros de brujas - la localización por sí sola NO basta).$q1$,$q1$Pie: la cabeza de monje tiene un pie robusto, a menudo claviformemente engrosado (2-4 cm de grosor, 8-15 cm de largo); el clitocybe de los campos delicado y delgado.$q1$]::text[],true),
($q1$infundibulicybe_geotropa$q1$,$q1$entoloma_sinuatum$q1$,$q1$es$q1$,$q1$Entoloma gigante (Riesenrötling): 5-20 cm, marfil/pardo grisáceo claro hasta gris liláceo pálido, convexo con margen ondulado sin mamelón, láminas gruesas y rígidas que viran a rosa. Cabeza de monje (Mönchskopf): infundibuliforme con mamelón central, láminas blancas decurrentes, color crema/cuero.$q1$,$q1$El entoloma gigante harinoso con un olor secundario desagradablemente agrio-rabanoso; la cabeza de monje aromática y dulzona con aroma de almendra amarga. El olor solo como carácter complementario, la esporada es decisiva.$q1$,$q1$Entoloma gigante: bosque claro de frondosas (a menudo haya/roble-carpe) sobre suelo fresco a húmedo, rico en cal, de verano a otoño, micorrízico. Cabeza de monje: bosque de frondosas/coníferas, lindes de bosque, claros de bosque sobre suelo calcáreo húmedo, de finales de verano a otoño - las localizaciones se solapan, por ello la comprobación de la esporada y de las láminas es imprescindible.$q1$,$q1$Decisivo: el entoloma gigante tiene polvo de esporas ROSA CARNE/rosa carnoso frente a la cabeza de monje BLANCO. Este es el carácter de separación más seguro entre ambos.$q1$,$q1$Hacer la esporada: polvo rosa/color carne = entoloma gigante = dejarlo. Adicionalmente comprobar si las láminas son decurrentes (cabeza de monje) o solo escotadas/insertadas rectas y viran a rosa con la madurez (entoloma gigante). Si falta el mamelón central y el sombrero no es realmente infundibuliforme, hay que extremar la precaución.$q1$,array[$q1$POLVO DE ESPORAS: el entoloma gigante tiene polvo de esporas ROSA CARNE (rosa carnoso); la cabeza de monje tiene polvo de esporas BLANCO - el carácter de separación más seguro mediante la esporada.$q1$,$q1$LÁMINAS: las láminas del entoloma gigante de jóvenes blanquecinas, luego amarillentas, finalmente rosa carne por las esporas, escotadas/insertadas rectas en el pie (NO decurrentes); las láminas de la cabeza de monje permanecen blancas/cremosas y descienden claramente por el pie.$q1$,$q1$FORMA DEL SOMBRERO: el entoloma gigante convexo con margen enrollado, después ondulado, SIN mamelón central y sin forma infundibuliforme marcada; la cabeza de monje infundibuliforme con mamelón central palpable.$q1$,$q1$OLOR: el entoloma gigante harinoso con una nota desagradablemente agria-rabanosa; la cabeza de monje aromática y dulzona con nota de almendra amarga.$q1$]::text[],true),
($q1$lactarius_deliciosus$q1$,$q1$paxillus_involutus$q1$,$q1$es$q1$,$q1$Níscalo (Edel-Reizker): por completo naranja a rojo zanahoria, sombrero con zonas concéntricas más oscuras, a menudo con manchas verdosas en la vejez/al dañarse, pie frecuentemente con hoyuelos. Paxilo enrollado (Kahler Krempling): pardo amarillento mate hasta pardo umbra, margen del sombrero permanentemente enrollado y afieltrado, sin naranja, sin zonas concéntricas de níscalo.$q1$,$q1$Níscalo: suave, afrutado-frutal. Paxilo enrollado: inconspicuo, ligeramente agrio; sin el aroma típico del níscalo.$q1$,$q1$Posible solapamiento de hábitat: el níscalo es compañero micorrízico de los pinos (en parte abetos rojos), preferentemente suelo calcáreo. El paxilo enrollado forma micorriza con pino, abeto rojo, abedul, haya sobre suelos ácidos, frescos a húmedos. Por ello la localización NO es un carácter de separación seguro – solo cuentan la prueba de la leche y el color.$q1$,$q1$Níscalo: polvo de esporas blanco cremoso hasta ocre amarillento pálido. Paxilo enrollado: polvo de esporas parduzco (pardo arcilla) – claramente más oscuro. Dirección diagnóstica clara: el paxilo siempre notablemente más oscuro.$q1$,$q1$La prueba de corte/leche es obligatoria: quien NO vea látex rojo anaranjado en el corte, no tiene un níscalo – dejarlo. El paxilo enrollado nunca segrega leche y vira al pardo-negruzco bajo presión (el níscalo solo verdea lentamente). El síndrome de Paxillus (inmuno-hemolítico) puede tener un desenlace mortal tras un consumo repetido durante años – por ello nunca catarlo 'para probar', ni siquiera cocinado.$q1$,array[$q1$PRUEBA DE LA LECHE (decisiva): el níscalo segrega abundante látex rojo zanahoria/anaranjado al corte. El paxilo enrollado NO segrega leche – no es un hongo lechoso. Sin látex rojo anaranjado = no es un níscalo.$q1$,$q1$Cambio de color por presión: las láminas y la carne del paxilo se tornan al instante pardo hasta pardo rojo-/negruzco oscuro bajo presión/lesión. La carne/leche del níscalo cambia solo lentamente a verdoso (nunca pardo-negruzco).$q1$,$q1$Láminas: el paxilo de ocre amarillento → pardo oliva, decurrentes en el pie y fácilmente separables de la carne del sombrero. Las láminas del níscalo son anaranjadas/color azafrán y no separables.$q1$,$q1$Color del sombrero + margen del sombrero: el níscalo naranja a rojo zanahoria con zonas anulares concéntricas más oscuras. El paxilo pardo amarillento mate hasta pardo umbra, sin naranja, con margen del sombrero permanentemente enrollado y afieltrado (también en la vejez).$q1$]::text[],true),
($q1$lactarius_deterrimus$q1$,$q1$paxillus_involutus$q1$,$q1$es$q1$,$q1$Níscalo de abeto (Lactarius deterrimus): sombrero de color rojo anaranjado a pardo anaranjado, con el tiempo o con las heladas presenta manchas verdosas sucias; láminas de color naranja pálido que, al ser dañadas, viran a rojo oscuro hasta verde grisáceo. Paxillus involutus (paxilo enrollado): sombrero de color pardo amarillento a pardo umbría, brillante en húmedo, de joven con el margen del sombrero enrollado y afieltrado durante mucho tiempo, de viejo claramente deprimido en forma de embudo; láminas de color ocre amarillento a pardo oliváceo, delgadas y apretadas, decurrentes y separables, que bajo presión o al tacto se manchan FUERTEMENTE de pardo ferruginoso a pardo negruzco (las láminas del níscalo no se vuelven pardo ferruginosas). Ambos pueden parecer anaranjado-pardos y en forma de embudo, de ahí la confusión.$q1$,$q1$Níscalo de abeto (Lactarius deterrimus): suave, afrutado-aromático (sabor ligeramente amargo). Paxillus involutus: agrio-discreto; el olor NO es un rasgo distintivo fiable: la prueba de la leche y la prueba de presión de las láminas son las decisivas.$q1$,$q1$Existe solapamiento: Paxillus involutus es micorrízico, entre otros, del abeto rojo (también del pino, abedul, haya, carpe) y crece en el mismo suelo ácido de bosque de coníferas/mixto en el que aparece el níscalo de abeto junto al abeto rojo. El hábitat NO separa de forma fiable.$q1$,$q1$Rasgo secundario, no claramente discriminante: el níscalo de abeto, según la fuente, va de crema a ocre pálido hasta pardo ocráceo; Paxillus involutus es claramente pardo arcilloso a pardo ferruginoso. Los colores se solapan hacia el ocre, por lo que solo sirve como prueba complementaria, no como criterio principal. Lo decisivo sigue siendo la prueba de la leche. En caso de duda, tomar una esporada.$q1$,$q1$Haz siempre la prueba de la leche: corta en fresco y comprueba si exuda leche. Si NO sale leche, no es un níscalo: Paxillus involutus carece de leche y, a través del síndrome acumulativo de Paxillus (anemia hemolítica, insuficiencia renal), puede llegar a poner en peligro la vida incluso tras años de consumo. Los níscalos, en cambio, exudan leche de color naranja/rojo zanahoria que vira a rojo vino. Regla práctica: recoge únicamente lactarios con leche roja/naranja, nunca con leche clara/blanca o sin leche alguna.$q1$,array[$q1$PRUEBA DE LA LECHE (decisiva, verificada): el níscalo de abeto (Lactarius deterrimus) exuda al cortarlo leche de color naranja/rojo zanahoria que en 15-20 min vira a rojo vino (más tarde a verde grisáceo); Paxillus involutus NO exuda leche ni líquido alguno: ausencia total de leche = NUNCA comer si se espera un níscalo.$q1$,$q1$Prueba de presión de las láminas (verificada): las láminas de Paxillus involutus se manchan fuertemente de pardo ferruginoso a pardo negruzco bajo presión y se desprenden del sombrero; las láminas del níscalo son quebradizas, están firmemente unidas al sombrero y, al ser dañadas, viran a rojo oscuro/verde grisáceo, no a pardo ferruginoso.$q1$,$q1$Margen del sombrero y forma: Paxillus involutus tiene el margen del sombrero afieltrado y enrollado durante mucho tiempo y el sombrero pardo oliváceo brillante; el sombrero del níscalo es anaranjado con manchas verdes, sin un enrollamiento afieltrado permanente del margen.$q1$,$q1$Esporada (complementaria, no fiable por sí sola): níscalo de crema a ocre frente a Paxillus involutus pardo arcilloso/ferruginoso; se solapan hacia el ocre, por lo que solo sirve de forma complementaria.$q1$]::text[],true),
($q1$lepista_nuda$q1$,$q1$cortinarius_orellanus$q1$,$q1$es$q1$,$q1$Cortinarius orellanus: sombrero de color pardo amarillento a pardo rojizo, ligeramente mamelonado, finamente escamoso-fibroso; láminas de color pardo amarillo-canela; fibras del velo de color pardo ferruginoso en el pie. Lepista nuda: completamente violeta, sombrero liso y convexo sin velo.$q1$,$q1$Lepista nuda con olor claramente aromático-dulzón (como a perfume). Cortinarius orellanus huele débilmente a rábano, sin el aroma dulzón. El olor solo como indicio, nunca fiable por sí solo.$q1$,$q1$Cortinarius orellanus: bosque de frondosas/mixto junto a roble y haya (micorriza), de verano a finales de otoño, más bien raro/favorecido por el calor. Lepista nuda: hojarasca rica en nutrientes, setos, compost, muy tarde en la temporada.$q1$,$q1$Lepista nuda de color rosa-blanquecino pálido; Cortinarius orellanus de color pardo ferruginoso. Una esporada pardo ferruginosa excluye a Lepista nuda.$q1$,$q1$La esporada es obligatoria: pardo ferruginoso = Cortinarius, mortalmente peligroso. Cortinarius orellanus está considerado uno de los hongos más peligrosos de Europa (orellanina, latencia de hasta 14 días, daños renales y hepáticos). Un velo aracnoideo en el ejemplar joven o fibras pardo ferruginosas en el pie = no comer nunca. Ante la menor duda, descartar.$q1$,array[$q1$Esporada (el discriminante más fiable frente a todo el género Cortinarius): Lepista nuda rosa-blanquecino pálido frente a Cortinarius orellanus pardo ferruginoso. Una esporada pardo ferruginosa excluye a Lepista nuda.$q1$,$q1$Cortina/velo: Cortinarius orellanus tiene un velo aracnoideo (de joven amarillento) con restos del velo pardo ferruginosos en el pie; Lepista nuda no tiene velo alguno.$q1$,$q1$Color del sombrero: Cortinarius orellanus pardo amarillento a pardo rojizo/zorruno (NUNCA violeta), a menudo ligeramente mamelonado; Lepista nuda completamente violeta en su juventud.$q1$,$q1$Color de las láminas: Cortinarius orellanus pardo amarillo/canela, separadas, escotado-adheridas; Lepista nuda violeta/violeta-rosado y manteniéndose clara.$q1$]::text[],true),
($q1$lepista_nuda$q1$,$q1$cortinarius_rubellus$q1$,$q1$es$q1$,$q1$Lepista nuda: de joven completamente violeta (sombrero, láminas, pie), sombrero convexo y liso sin mamelón puntiagudo, sin velo. Cortinarius rubellus: sombrero de color anaranjado herrumbre a anaranjado zorruno con vértice puntiagudo (mamelonado), finamente afieltrado-fibroso, láminas de color pardo canela/herrumbre, fibras del velo de color pardo ferruginoso en el pie.$q1$,$q1$Lepista nuda huele aromático-dulzón (como a perfume, recordando a galleta/flor de naranjo). Cortinarius rubellus huele débilmente a rábano, sin el típico aroma dulzón. El olor es solo un indicio, NUNCA fiable por sí solo: lo decisivo son la esporada + la cortina.$q1$,$q1$Cortinarius rubellus: bosques de coníferas ácidos (abeto rojo/bosque mixto de abeto rojo y pino), ubicaciones turbosas-húmedas y de montaña, de agosto a octubre. Lepista nuda: hojarasca de bosque de frondosas/mixto rica en nutrientes, setos, montones de compost, muy tarde en la temporada hasta después de las primeras heladas.$q1$,$q1$Decisivo: Lepista nuda = esporada de color rosa-blanquecino pálido/crema-rosado. Cortinarius rubellus = esporada de color pardo ferruginoso. Una esporada pardo ferruginosa excluye con seguridad a Lepista nuda.$q1$,$q1$Toma SIEMPRE una esporada (sombrero sobre papel blanco durante la noche). Rosa-blanquecino pálido = posiblemente Lepista nuda. Pardo ferruginoso O un velo aracnoideo (cortina) en el ejemplar joven = ALTO, es un Cortinarius: no comer nunca. La intoxicación por orellanina se manifiesta solo tras 3-14 días, cuando el riñón ya está irreversiblemente dañado. Ante la menor duda, no comer.$q1$,array[$q1$Esporada (la prueba de separación más segura): Lepista nuda rosa-blanquecino pálido/crema-rosado; CUALQUIER Cortinarius tiene esporada PARDO FERRUGINOSA. Una esporada pardo ferruginosa excluye con seguridad a Lepista nuda.$q1$,$q1$Cortina/velo: Cortinarius rubellus tiene de joven un velo aracnoideo (cortina) entre el margen del sombrero y el pie; los restos del velo en el pie se tiñen de pardo ferruginoso. Lepista nuda NUNCA tiene velo, ningún velo en absoluto.$q1$,$q1$Forma/color del sombrero: Cortinarius rubellus anaranjado herrumbre a anaranjado canela/zorruno con vértice puntiagudo y mamelonado; Lepista nuda de joven completamente violeta, sombrero convexo sin mamelón puntiagudo.$q1$,$q1$Color de las láminas: Lepista nuda violeta/violeta-rosado y manteniéndose clara; Cortinarius rubellus pardo canela/herrumbre, separadas, escotado-adheridas.$q1$,$q1$Hábitat: Cortinarius rubellus junto a coníferas (abeto rojo) sobre suelo ácido, a menudo turboso-húmedo, en zonas de montaña; Lepista nuda en hojarasca de bosque de frondosas/mixto rica en nutrientes, setos, montones de compost, tarde en la temporada hasta después de las heladas.$q1$]::text[],true),
($q1$lycoperdon_perlatum$q1$,$q1$amanita_phalloides$q1$,$q1$es$q1$,$q1$Desde fuera, un huevo cerrado y blanco de oronja verde (Amanita phalloides) puede parecerse superficialmente a un bejín blanco joven. Solo se distinguen con seguridad en sección longitudinal: masa blanca homogénea (bejín) frente a un hongo preformado con la silueta de láminas/pie y volva (Amanita).$q1$,$q1$El bejín joven es inodoro hasta de olor suave a hongo. La oronja verde joven es casi inodora; solo de vieja huele dulzón-amielado hasta a carroña. El olor NO es un rasgo fiable en el crítico estadio de huevo.$q1$,$q1$Amanita phalloides es un hongo micorrízico sobre todo junto a roble y haya (también castaño), prefiere suelos ácidos; el bejín es saprótrofo y ubicuo en todo tipo de bosques, prados y jardines. Las ubicaciones se solapan con frecuencia, por lo que la ubicación NO ayuda a distinguir: solo la prueba del corte es segura.$q1$,$q1$En el bejín madura en su interior una esporada de color pardo amarillento a pardo oliváceo (entonces el hongo ya no es comestible). Amanita phalloides tiene esporada blanca, pero en el estadio de huevo no es comprobable, por lo que resulta irrelevante para el recolector.$q1$,$q1$Antes de consumirlo, parte por la mitad y a lo largo TODO bejín esférico y examina la imagen del corte. Cómelo solo si el interior es COMPLETAMENTE blanco puro y homogéneo, sin la menor silueta de láminas, pie o sombrero. Una sola silueta de hongo reconocible significa una intoxicación mortal por amatoxinas (insuficiencia hepática). En caso de duda, acude al puesto de control de setas (VAPKO).$q1$,array[$q1$SECCIÓN LONGITUDINAL (la prueba decisiva): en el bejín, el interior es una masa totalmente uniforme, blanca pura, parecida a un malvavisco, SIN estructura alguna. En el huevo joven de la oronja verde ya se ve en el corte el hongo preformado: las láminas y el pie esbozados como silueta más oscura. Basta un solo arranque reconocible de láminas o de pie = tirar.$q1$,$q1$Base del pie/volva: la Amanita joven está dentro de una envoltura general blanca y membranosa (velo) y tiene en la base un bulbo/volva membranoso y lobulado. El bejín no tiene volva, ni pie diferenciado, ni envoltura de este tipo: se asienta en el suelo con una base estéril corta.$q1$,$q1$Piel externa: el bejín común lleva finas espinas/verrugas frotables que dejan un patrón reticulado y es blanco por dentro. El huevo de Amanita es por fuera blanco, liso y membranoso.$q1$,$q1$La madurez cambia al bejín: en cuanto el interior se vuelve amarillento/oliváceo/parduzco (formación de esporas), ya no es comestible; la carne de la Amanita permanece blanca en el corte y muestra la silueta del hongo.$q1$]::text[],true),
($q1$lycoperdon_perlatum$q1$,$q1$amanita_verna$q1$,$q1$es$q1$,$q1$Externamente muy parecida al bejín blanco joven (huevo blanco puro y membranoso); solo se distingue con seguridad en sección transversal por la estructura de hongo esbozada (láminas + pie) y la pronunciada volva, no por la forma externa.$q1$,$q1$Amanita verna de joven inodora hasta de olor débil; de vieja, dulzón-desagradable. No es un rasgo distintivo fiable en el estadio de huevo.$q1$,$q1$Amanita verna aparece sobre todo en primavera/principios de verano (bosques de frondosas, más bien suelos calcáreos/cálidos); los bejines aparecen más bien de verano a otoño y son ubicuos. Temporada/ubicación son indicios, pero NO un sustituto seguro de la prueba del corte.$q1$,$q1$Amanita verna: esporada blanca. Bejín: esporada de color pardo amarillento/oliváceo al madurar (entonces ya no es comestible). En el estadio de huevo no es comprobable, por lo que es irrelevante para la determinación.$q1$,$q1$También aquí: parte por la mitad todo hallazgo esférico blanco; cómelo solo si el interior es completamente homogéneo y blanco, sin silueta de láminas/pie y sin volva. Un hongo esbozado en el corte significa una intoxicación mortal por amatoxinas. Puesto de control (VAPKO) ante cualquier inseguridad.$q1$,array[$q1$Como todas las oronjas blancas (sección Phalloideae), Amanita verna en su joven estadio de huevo, envuelta por el velo blanco, es esférica y puede confundirse con bejines blancos. La SECCIÓN LONGITUDINAL es decisiva: masa blanca homogénea (bejín) frente a láminas + pie preformados en el huevo (Amanita).$q1$,$q1$Base del pie: Amanita verna muestra en la base una vaina (volva) claramente pronunciada, lobulada y membranosa en forma de saco; en el bejín falta toda volva.$q1$,$q1$Las láminas permanecen blancas hasta blanco crema (también maduras), esbozadas en el huevo como silueta clara en el corte; el bejín nunca tiene esbozos de láminas.$q1$,$q1$Por fuera blanco puro y membranoso (Amanita) frente a finamente verrugoso/espinoso con verrugas frotables (bejín común).$q1$]::text[],true),
($q1$lycoperdon_perlatum$q1$,$q1$gemeiner-fliegenpilz-var-alba$q1$,$q1$es$q1$,$q1$Desde arriba/desde fuera apenas se distingue del joven bejín blanco, ya que A. virosa es completamente blanco puro. La distinción segura solo es posible en el corte transversal: hongo preformado de color blanco con láminas apretadas + volva (Amanita) frente a una masa blanca homogénea (bejín).$q1$,$q1$El A. virosa más viejo huele desagradablemente dulzón-repugnante; pero el huevo joven es inodoro/discreto. El olor no es fiable en la fase crítica de huevo.$q1$,$q1$A. virosa crece sobre todo en bosques húmedos (ácidos) de coníferas/mixtos, formando micorriza preferentemente con la pícea (también hay hallazgos documentados con haya/roble/abedul), a menudo en zonas más altas/montanas; ecológicamente en parte distinto del bejín saprótrofo ubicuo, pero el lugar de crecimiento NO es un criterio seguro.$q1$,$q1$A. virosa: esporada blanca. En el bejín madura una esporada de color pardo amarillento/oliváceo (= entonces ya no comestible). En la fase de huevo no es comprobable, por lo que es irrelevante para la identificación.$q1$,$q1$Como el huevo blanco de la oronja blanca (Knollenblätterpilz) es blanco puro y se parece especialmente a un bejín blanco, rige con mayor rigor: cortar completamente por la mitad y comer SOLO si el interior es de carne blanca absolutamente homogénea, sin ninguna silueta de láminas/pie y sin volva. Cualquier contorno de hongo = peligro de muerte (amatoxinas, fallo hepático). En caso de duda, acudir al centro de control de setas (VAPKO).$q1$,array[$q1$Los estadios jóvenes de Amanita virosa se confunden expresamente en las bases de datos de hongos/venenos con bejines y pedos de lobo. Lo decisivo es el CORTE LONGITUDINAL: bejín = masa blanca pura homogénea; huevo de Amanita = láminas ya esbozadas (blancas, apretadas) y pie reconocibles como silueta.$q1$,$q1$Base del pie: A. virosa tiene una vaina blanca membranosa y lobulada (volva) en la base. El bejín no tiene volva ni un pie diferenciado.$q1$,$q1$Contorno exterior: el huevo de virosa es blanco puro y de superficie lisa-membranosa; el bejín común lleva finas verruguitas/espinitas que se pueden frotar/quitar.$q1$,$q1$Como A. virosa es completamente blanco (sombrero, láminas y pie permanecen blancos), no sirve la pista del color: solo la imagen del corte y la volva separan con seguridad.$q1$]::text[],true),
($q1$marasmius_oreades$q1$,$q1$clitocybe_dealbata$q1$,$q1$es$q1$,$q1$Clitocybe dealbata: más pequeño, sombrero de color blanco yeso-plomizo a amarillo crema, a menudo deprimido, con láminas apretadas y decurrentes. Marasmius oreades (senderuela): sombrero de color pardo cuero-amarillento con mamelón, láminas separadas, pie claramente más correoso.$q1$,$q1$La senderuela huele agradablemente especiada (clavo de especia/almendra amarga); ~25% de las personas no lo perciben por causas genéticas, por lo que no es un rasgo aislado. Clitocybe dealbata, harinoso a inodoro.$q1$,$q1$Como C. rivulosa, es un típico hongo de pradera/césped en lugares cubiertos de hierba, eventualmente en corros de brujas, exactamente en el hábitat de la senderuela. El lugar de crecimiento no sirve para la distinción.$q1$,$q1$Ambos con esporada BLANCA: no es un rasgo diferenciador. Lo decisivo siguen siendo la disposición de las láminas y el pie correoso.$q1$,$q1$La muscarina actúa ya en pequeñas cantidades (sudoración, salivación, lagrimeo a los 15-30 min). Nunca recolectar si las láminas están apretadas y decurren por el pie: la comestible senderuela tiene SIEMPRE láminas separadas, no decurrentes, y un pie correoso y flexible. El olor a clavo es solo una confirmación adicional.$q1$,array[$q1$Láminas: Clitocybe dealbata apretadas, adheridas al pie hasta brevemente DECURRENTES; senderuela muy separadas, escotadas en la inserción, NO decurrentes$q1$,$q1$Sombrero: Clitocybe dealbata blanco yeso-plomizo a amarillo crema, liso/pruinoso, plano a deprimido; senderuela de color cuero con mamelón obtuso, higrófano$q1$,$q1$Pie: senderuela correoso-flexible, cartilaginoso-fibroso; Clitocybe dealbata más fibroso y quebradizo$q1$,$q1$Test de revivificación: la senderuela revive tras secarse; Clitocybe dealbata no$q1$]::text[],true),
($q1$marasmius_oreades$q1$,$q1$clitocybe_rivulosa$q1$,$q1$es$q1$,$q1$Senderuela (Nelkenschwindling): sombrero de color pardusco-amarillo con mamelón obtuso, láminas pálidas y separadas, pie correoso y flexible. Clitocybe rivulosa (clitocibe tóxico): sombrero de color blanco plomizo-gris crema, a menudo deprimido/embudado, láminas apretadas y decurrentes.$q1$,$q1$Senderuela: agradablemente especiada, a clavo de especia/almendra amarga (nota de ácido cianhídrico). ATENCIÓN: ~25% de las personas NO pueden percibir este olor por causas genéticas, por lo que no es un rasgo aislado. Clitocybe tóxico: harinoso a inodoro. Usar el olor solo como confirmación adicional, nunca como única prueba de seguridad.$q1$,$q1$Ambos crecen en el MISMO lugar: prados, pastos, céspedes en jardines/parques; ambos forman corros de brujas; no es posible separarlos por el hábitat. Esto aumenta enormemente el riesgo de confusión.$q1$,$q1$Ambos tienen esporada BLANCA: la esporada NO separa a estos dos. Lo decisivo siguen siendo la disposición de las láminas (decurrentes frente a separadas/escotadas) y el pie correoso.$q1$,$q1$Regla de oro en la pradera: comprobar las láminas. La senderuela tiene láminas MUY separadas, NO decurrentes, y un pie correoso y flexible. Si las láminas están apretadas y decurren por el pie, dejarlo (sospecha de clitocibe tóxico con muscarina). El olor especiado a clavo es solo una confirmación adicional (una cuarta parte de las personas no lo huele).$q1$,array[$q1$Láminas (EL rasgo principal): el clitocibe tóxico tiene láminas apretadas, brevemente DECURRENTES por el pie; la senderuela tiene láminas SEPARADAS (distanciadas), de inserción escotada en el pie, NO decurrentes$q1$,$q1$Pie: el pie de la senderuela es correoso, flexible, cartilaginoso-fibroso (se puede retorcer sin romperse); el pie del clitocibe es quebradizo$q1$,$q1$Sombrero: el clitocibe es blanco plomizo/gris crema, higrófano, a menudo deprimido/embudado; la senderuela de color cuero pardo-amarillento con mamelón obtuso$q1$,$q1$Test de revivificación: los cuerpos fructíferos de la senderuela reviven tras el secado (típico de los Marasmius); el clitocibe tóxico no$q1$]::text[],true),
($q1$marasmius_oreades$q1$,$q1$inocybe_erubescens$q1$,$q1$es$q1$,$q1$Inocybe (seta de fibrillas): sombrero cónico-mamelonado, agrietado radialmente, blanquecino y que con el tiempo/la presión se torna rojo ladrillo, láminas que oscurecen (de color oliváceo-rosado-parduzco). Senderuela: sombrero liso de color cuero con mamelón obtuso, láminas separadas que permanecen pálidas.$q1$,$q1$Senderuela agradablemente especiada (clavo de especia/almendra amarga; no perceptible por ~25%). Inocybe erubescens (rojo ladrillo) débilmente afrutado, con la edad desagradablemente dulzón-espermático. El olor solo como complemento, nunca aislado.$q1$,$q1$Inocybe erubescens crece, amante de la cal, sobre todo en bosques de frondosas/mixtos, parques y bajo matorrales (micorriza con haya/tilo), en parte también en céspedes; no principalmente en pradera abierta como la senderuela. El lugar de crecimiento ayuda, pero NO es un rasgo de seguridad aislado (también posible en césped/césped de parque).$q1$,$q1$DECISIVO y salvavidas: el inocybe tiene esporada de color pardo oscuro; la senderuela, blanca. Una esporada separa a ambos de forma inequívoca.$q1$,$q1$La comprobación de la esporada como salvavidas: blanca = posible senderuela; parda = NUNCA comer. Además delatan al mortal inocybe: sombrero agrietado-radialmente fibroso, el tornarse rojo ladrillo (a la presión) y el olor espermático. Muscarina: cantidad mortal ya a partir de ~40-500 g de hongo fresco.$q1$,array[$q1$Esporada (DECISIVO): el inocybe tiene esporada PARDA OSCURA, las láminas viran de blanco/crema pasando por gris oliva-rosado a parduzco-manchado; la senderuela tiene esporada BLANCA y láminas que permanecen pálidas$q1$,$q1$Enrojecimiento: el inocybe se torna rojo ladrillo (sombrero/pie/carne, sobre todo a la presión y con la edad); la senderuela NO se enrojece$q1$,$q1$Superficie del sombrero: el inocybe es cónico-mamelonado, radialmente fibroso y agrietado/resquebrajado ('Risspilz'); la senderuela es lisa, higrófana, con mamelón obtuso$q1$,$q1$Olor: el inocybe espermático/afrutado-desagradable; la senderuela especiada a clavo de especia/almendra amarga$q1$]::text[],true),
($q1$marone$q1$,$q1$flockenstieliger_hexenpilz$q1$,$q1$es$q1$,$q1$Marone (boleto bayo): marrón, azulea ligeramente. Hexenpilz de pie punteado (Neoboletus, pie con finos puntitos/escamillas rojas, NO reticulado): marrón, azulea rápida e intensamente, con puntos rojos.$q1$,null,$q1$Ambos en el bosque$q1$,null,$q1$Ambos comestibles. El Hexenpilz DEBE cocinarse 15+ min.$q1$,array[$q1$Ambos comestibles; el Hexenpilz azulea MÁS RÁPIDO$q1$,$q1$El Hexenpilz tiene puntitos rojos en el pie$q1$]::text[],true),
($q1$morchella_elata$q1$,$q1$fliegenpilz-grosspilz$q1$,$q1$es$q1$,$q1$Colmenilla: alveolada/regular frente a la falsa colmenilla cerebriforme-irregular.$q1$,$q1$ambas inespecíficas$q1$,$q1$ambas en primavera, zonas quemadas/bosque de ribera/bosque de coníferas$q1$,$q1$sin esporada laminar (hongos ascomicetos)$q1$,$q1$La falsa colmenilla de primavera es muy tóxica (potencialmente mortal). Corte longitudinal: completamente hueco (colmenilla) frente a algodonoso-tabicado (falsa colmenilla).$q1$,array[$q1$Colmenilla puntiaguda: sombrero alveolado-acanalado, sombrero+pie completamente huecos$q1$,$q1$Falsa colmenilla de primavera: cerebriforme y retorcida, pie tabicado (no hueco), giromitrina (muy tóxica)$q1$]::text[],true),
($q1$parasol$q1$,$q1$amanita_pantherina$q1$,$q1$es$q1$,$q1$Parasol: sombrero pardo claro, pie con dibujo de piel de serpiente. Pantera: pardo con motas blancas, pie blanco con bulbos.$q1$,$q1$Parasol: a nuez, agradable. Pantera: a rábano.$q1$,$q1$Parasol: praderas, lindes del bosque. Pantera: bosque de frondosas.$q1$,$q1$Ambas blancas.$q1$,$q1$Prueba del PARASOL: anillo móvil-desplazable, pie con dibujo de piel de serpiente. Si hay motas, NUNCA comerlo.$q1$,array[$q1$Anillo del parasol MÓVIL, anillo de la pantera fijo$q1$,$q1$Parasol con pie de piel de serpiente, pantera de pie blanco-liso$q1$,$q1$La pantera tiene un bulbo con 2-3 rebordes anulares$q1$]::text[],true),
($q1$parasol$q1$,$q1$chlorophyllum_brunneum$q1$,$q1$es$q1$,$q1$Dibujo serpenteado del pie (parasol sí) + enrojecimiento (lepiota tóxica/Chlorophyllum sí) + bulbo.$q1$,$q1$ambas inespecíficas$q1$,$q1$Parasol en bosque/pradera; la lepiota tóxica (Chlorophyllum) a menudo en compost/jardín$q1$,$q1$ambas blanco-crema$q1$,$q1$Tóxico gastrointestinal. Pie con dibujo serpenteado + sin enrojecimiento = parasol; pie liso + coloración rojo azafrán = no tocar.$q1$,array[$q1$Parasol: pie con dibujo serpenteado (tipo piel de serpiente), anillo doble desplazable, la carne NO enrojece$q1$,$q1$Lepiota tóxica (Chlorophyllum): pie liso, bulbo marginado, la carne/láminas se tiñen de rojo azafrán$q1$]::text[],true),
($q1$roetling$q1$,$q1$agaricus_xanthodermus$q1$,$q1$es$q1$,$q1$Champiñón amarilleante (de carbol): sombrero blanco a blanco calizo, de joven globoso/hemisférico, después aplanado, liso a finamente escamoso; la base del pie, en corte longitudinal, INMEDIATAMENTE de un amarillo cromo intenso. Champiñón de oveja: sombrero blanco crema, sedoso-fibrilloso a ligeramente escamoso, convexo a plano; amarillea solo débilmente en todo el hongo y sin la mancha concentrada de amarillo cromo en la base del pie.$q1$,$q1$Rasgo decisivo: el champiñón de oveja huele agradablemente a anís/mazapán. El champiñón amarilleante (de carbol) huele desagradablemente a tinta/carbol/fenol (medicinal-yodado); el olor se intensifica al frotar la base del pie y, sobre todo, al calentar/cocinar.$q1$,$q1$Champiñón amarilleante (de carbol): jardines, parques, lindes de bosque, montones de compost, áreas ruderales/próximas a poblaciones. Champiñón de oveja: prados y pastos abonados, sobre todo pastizales de ovejas y caballos. El hábitat por sí solo NO separa con seguridad (es posible la superposición).$q1$,$q1$En ambas especies pardo chocolate oscuro a pardo púrpura (género Agaricus); NO es un rasgo distintivo.$q1$,$q1$Cortar longitudinalmente la base del pie: si se tiñe de inmediato de un amarillo cromo intenso Y el hongo huele a tinta/carbol en lugar de a anís, descartarlo: es el champiñón amarilleante (de carbol). Regla práctica: todo champiñón con olor a carbol/tinta o base del pie de amarillo cromo intenso = tóxico, no comerlo.$q1$,array[$q1$El olor es el rasgo más importante: el champiñón de oveja agradable a anís/mazapán; el champiñón amarilleante (de carbol) desagradable a tinta/carbol/fenol, intensificándose al frotar la base del pie y al calentar.$q1$,$q1$Cortar longitudinalmente la base del pie: el champiñón amarilleante (de carbol) se tiñe DE INMEDIATO de un amarillo cromo intenso, concentrado en la base del pie; el champiñón de oveja amarillea solo débilmente en todo el cuerpo fructífero y no concentrado en la base del pie.$q1$,$q1$Ambos tienen anillo y láminas que maduran de rosa pálido a pardo chocolate, y ambos tienen esporada pardo oscura; por eso SOLO el corte de la base del pie (amarillo cromo) Y la prueba del olor separan con seguridad, no las láminas ni el color de la esporada.$q1$]::text[],true),
($q1$roetling$q1$,$q1$amanita_phalloides$q1$,$q1$es$q1$,$q1$Oronja verde (cicuta verde): sombrero verde oliva/amarillo-verdoso con fibras radiales incrustadas (la forma blanca var. alba también puede ser blanca pura), láminas BLANCO PURO, base del pie bulbosa con vaina membranosa (volva). Champiñón de oveja: sombrero blanco crema, láminas de rosa -> pardo chocolate, SIN vaina membranosa.$q1$,$q1$Champiñón de oveja: olor agradable a anís/mazapán. Oronja verde (cicuta verde): de joven dulzón-amelado, en la vejez desagradable; NADA de anís.$q1$,$q1$Amanita phalloides: hongo micorrízico predominantemente bajo robles y hayas en el bosque. Champiñón de oveja: aislado en prados y pastos sin asociación a árboles. El hábitat por sí solo NO es un rasgo seguro.$q1$,$q1$DECISIVO: champiñón de oveja pardo chocolate oscuro a pardo púrpura; Amanita phalloides BLANCO PURO. Esporada blanca = nunca comer.$q1$,$q1$No recoger nunca 'champiñones' blancos jóvenes, aún cerrados, con láminas claras: precisamente en estado de botón el mortal Amanita phalloides es el que más se parece al champiñón. Desenterrar por completo la base del pie (¿hay volva?) y considerar las láminas blanco puro y la esporada blanca como señal de parada absoluta.$q1$,array[$q1$Láminas: la oronja verde (cicuta verde) tiene siempre láminas BLANCO PURO; las láminas del champiñón son de joven rosa pálido (los botones muy jóvenes excepcionalmente blanco crema) y maduran pasando por gris rosado hasta pardo chocolate. En estado de botón no fiarse solo del color de las láminas: entonces volva + esporada son obligatorios.$q1$,$q1$Base del pie: bulbo claramente diferenciado con vaina membranosa (volva) en la cicuta verde; en el champiñón falta la volva. Desenterrar siempre por completo la base del pie.$q1$,$q1$No usar el color del sombrero como rasgo principal: típicamente verde oliva/amarillo-verdoso, pero como var. alba también blanco puro; por eso comprobar siempre láminas + volva + esporada, nunca solo el color.$q1$,$q1$Esporada blanca (champiñón pardo oscuro): el rasgo individual más fiable.$q1$]::text[],true),
($q1$roetling$q1$,$q1$amanita_verna$q1$,$q1$es$q1$,$q1$Amanita verna (oronja mortal de primavera): sombrero blanco puro, láminas BLANCO PURO (también en la vejez), base del pie con una vaina (volva) bulbosa, membranosa y en forma de saco, a menudo hundida profundamente en la tierra. Champiñón de oveja: sombrero blanco cremoso, láminas que maduran de rosa -> gris-rosado -> marrón chocolate, SIN volva, a lo sumo con la base del pie ligeramente engrosada.$q1$,$q1$Champiñón de oveja: agradable olor a anís/mazapán. Amanita verna: casi inodora a ligeramente dulzona/melosa, desagradable en la vejez - SIN anís.$q1$,$q1$Amanita verna: hongo micorrízico, crece en el bosque (bosque caducifolio/mixto), sobre todo en primavera, ligado a árboles. Champiñón de oveja: saprótrofo en prados y pastizales abiertos sin ligazón a árboles. Atención: el hábitat por sí solo NO es un criterio seguro.$q1$,$q1$DECISIVO y fiable al 100 %: el champiñón de oveja es de un marrón chocolate oscuro a marrón purpúreo; Amanita verna es BLANCO PURO. Ante una esporada blanca, NUNCA comerlo como champiñón.$q1$,$q1$Ante cualquier 'champiñón' blanco, desentierra y deja al descubierto SIEMPRE la base del pie por completo: si aparece una vaina membranosa bulbosa (volva) O si las láminas permanecen blanco puro - es peligroso para la vida, déjalo en su sitio. En caso de duda, haz una esporada: blanca = oronja mortal, no comer nunca. No recolectar siquiera los botones blancos jóvenes y cerrados.$q1$,array[$q1$Láminas: Amanita verna tiene a CUALQUIER edad láminas blanco puro; el champiñón de oveja las tiene de joven rosa pálido (¡los botones muy jóvenes pueden ser blanco crema!), más tarde de gris-rosado a marrón chocolate. IMPORTANTE: en el estadio de botón el color de las láminas por sí solo NO es seguro - entonces hay que comprobar obligatoriamente la volva + la esporada.$q1$,$q1$Base del pie: Amanita verna tiene un bulbo claramente diferenciado con una vaina membranosa en forma de saco (volva); el champiñón NO tiene volva. Por ello desentierra siempre la base del pie por completo - la volva está a menudo hundida profundamente en la tierra.$q1$,$q1$Polvo de esporas: el champiñón es marrón oscuro, Amanita verna es BLANCO puro - la esporada es el carácter individual más fiable.$q1$,$q1$Olor: el champiñón de oveja huele a anís; Amanita verna sin olor a anís (neutro a dulzón-meloso) - la ausencia de olor a anís es una señal de alarma, pero NUNCA sustituye la comprobación de la volva/de las esporas.$q1$]::text[],true),
($q1$russula_cyanoxantha$q1$,$q1$amanita_phalloides$q1$,$q1$es$q1$,$q1$Los ejemplares de tonos violeta-verdosos son confundibles visualmente; la prueba de las láminas (flexibles vs. no flexibles) + la base del pie son decisivas.$q1$,$q1$La rúsula es suave$q1$,$q1$ambas en bosque caducifolio (haya/roble)$q1$,$q1$ambas blanco$q1$,$q1$MORTAL. Deja al descubierto la base del pie: cualquier bulbo con vaina membranosa = peligro de muerte.$q1$,array[$q1$Rúsula cárdena (Russula cyanoxantha): láminas flexibles y untuosas (no se astillan), SIN anillo, SIN volva$q1$,$q1$Oronja mortal (Amanita phalloides): anillo + volva, amatoxinas mortales$q1$]::text[],true),
($q1$russula_vesca$q1$,$q1$amanita_phalloides$q1$,$q1$es$q1$,$q1$Decisiva y vinculante es la base del pie: en A. phalloides una volva blanca membranosa alrededor de una base bulbosa del pie más un anillo colgante y estriado; láminas libres y blandas. R. vesca tiene una base del pie que se afina de forma recta, sin bulbo ni anillo, y láminas adheridas y de rotura quebradiza. El color NO es un criterio fiable: phalloides es por lo general verde oliva/amarillo-verdoso (también blanca como var. alba); el color rojo carne del sombrero de vesca es a lo sumo un indicio. La confusión de color típica de la oronja mortal se da con las rúsulas comestibles VERDES, no con la vesca roja - por eso, asegúrate siempre morfológicamente en la base del pie.$q1$,$q1$La oronja mortal más vieja huele dulzona a miel artificial hasta desagradable; la rúsula comestible huele suave/discreta. El olor es SOLO un indicio, nunca el criterio de seguridad.$q1$,$q1$Ambas son hongos micorrízicos junto a árboles caducifolios (roble, haya, castaño) - el emplazamiento NO las separa de forma fiable, por ello es imprescindible la comprobación morfológica en la base del pie.$q1$,$q1$Ambas blanco - el polvo de esporas NO DISTINGUE estas especies y no debe servir para dar el visto bueno.$q1$,$q1$Desentierra SIEMPRE el hongo entero con la base del pie (¡no lo cortes!) y comprueba si hay bulbo + volva blanca membranosa + anillo en el pie. Si aparece volva/bulbo/anillo o si las láminas son blandas y libres, NO es una rúsula - no apliques la regla de las rúsulas/la prueba de sabor, ya que las amatoxinas saben SUAVES y son mortales. El color nunca es el criterio. En Suiza: ante cualquier duda, acude al control oficial de setas VAPKO.$q1$,array[$q1$Bulbo/volva en la base del pie: A. phalloides tiene SIEMPRE una vaina blanca membranosa y en forma de saco (volva) alrededor de un bulbo bien marcado - las rúsulas NUNCA tienen volva ni bulbo. Este es el criterio vinculante, el color NO lo es.$q1$,$q1$Anillo del pie: A. phalloides lleva un anillo (manguito) colgante, membranoso y estriado en la parte superior del pie - las rúsulas carecen de anillo.$q1$,$q1$Láminas: rúsula = láminas de rotura quebradiza, que se astillan, adheridas al pie (de láminas quebradizas); A. phalloides = láminas blandas, flexibles y LIBRES (no adheridas al pie). ¡La prueba de sabor falla aquí, porque las amatoxinas saben SUAVES/a nuez!$q1$,$q1$El color del sombrero como indicio débil: A. phalloides es blanco-verdosa/verde/oliva/amarillo-verdosa (rara vez blanca, var. alba) - el color rojo carne/rojo vino de R. vesca NO encaja con ello, pero nunca sustituye la comprobación de la base del pie. La confusión de color clásica se da con las rúsulas VERDES, no con la rúsula comestible roja.$q1$]::text[],true),
($q1$russula_vesca$q1$,$q1$russula_emetica$q1$,$q1$es$q1$,$q1$R. vesca: rojo carne mate a rojo vino/rojo pardo, a menudo desvaído y con manchas irregulares, con el borde del sombrero de cutícula retraída (demasiado corta), de modo que los bordes de las láminas sobresalen a modo de dientecillos. R. emetica: rojo cereza/rojo sangre brillante y uniforme, viscosa y reluciente con la humedad, con la cutícula cubriendo hasta el borde y desprendible en gran parte (a menudo hasta el centro del sombrero).$q1$,$q1$Ambas en gran medida discretas/ligeramente afrutadas; el olor NO separa estas dos especies. Lo decisivo es el sabor (suave vs. ardiente y picante).$q1$,$q1$R. emetica: bosques húmedos/ácidos de turbera y coníferas (abeto rojo, pino, abeto blanco), a menudo con musgo. R. vesca: bosque caducifolio y mixto junto a haya y roble, en suelos más bien frescos a secos.$q1$,$q1$Ambas blanco a blanquecino – el polvo de esporas NO separa estas dos especies. No usar para la distinción.$q1$,$q1$Prueba de sabor según la regla de las rúsulas: masticar un trozo pequeño del sombrero con láminas, escupir, no tragar – suave = rúsula comestible, picante/ardiente = rúsula vomitiva (tóxica, descartar). La regla SOLO es válida si el hongo se ha reconocido sin lugar a dudas como rúsula (láminas quebradizas que se astillan, sin anillo en el pie, sin volva). R. emetica no es mortal, pero provoca trastornos gastrointestinales intensos durante días.$q1$,array[$q1$Sabor (regla de las rúsulas, el carácter distintivo decisivo): R. vesca es suave y agradablemente a nuez; R. emetica sabe de inmediato ardiente/picante como la pimienta. Masticar brevemente un trozo pequeño del sombrero con láminas, NO tragar, escupir por completo – aplicar solo si el hongo se ha reconocido sin lugar a dudas como rúsula (láminas quebradizas, sin anillo, sin volva).$q1$,$q1$Color del sombrero: R. vesca rojo carne/rojo vino mate hasta rojo pardo, a menudo desvaído con manchas; R. emetica rojo sangre, rojo cereza brillante hasta rojo púrpura, pegajosa y reluciente con la humedad.$q1$,$q1$Cutícula acortada (carácter guía de R. vesca): el borde del sombrero queda retraído, de modo que la carne del sombrero y los extremos de las láminas sobresalen del borde a modo de dientecillos – falta en R. emetica (la cutícula cubre hasta el borde y se desprende en gran parte, a menudo hasta el centro del sombrero).$q1$,$q1$Emplazamiento: R. emetica típicamente en bosques húmedos de turbera y coníferas (abeto rojo, pino, abeto blanco, a menudo con musgo/ácidos); R. vesca sobre todo en bosque caducifolio/mixto junto a haya y roble.$q1$]::text[],true),
($q1$russula_virescens$q1$,$q1$amanita_phalloides$q1$,$q1$es$q1$,$q1$Coloración verde similar, sobre todo de joven; la cutícula de la rúsula se resquebraja en placas.$q1$,$q1$La rúsula es suave/a nuez; la oronja mortal huele a miel (de vieja)$q1$,$q1$ambas en bosque caducifolio$q1$,$q1$La rúsula blanco, A. phalloides blanco$q1$,$q1$MORTAL. Ante hongos verdes, desentierra SIEMPRE el hongo entero: ¿faltan el anillo Y la volva? Si no, no comer.$q1$,array[$q1$Rúsula: láminas quebradizas, SIN anillo, SIN bulbo/volva$q1$,$q1$Oronja mortal: anillo + volva membranosa en una base bulbosa, láminas flexibles$q1$]::text[],true),
($q1$schopftintling$q1$,$q1$amanita_phalloides$q1$,$q1$es$q1$,$q1$Coprino (Schopftintling): blanco-escamoso, de forma ovoide. Oronja verde (Knollenblätterpilz / Amanita phalloides): verde oliva, lisa.$q1$,null,$q1$Coprino: prados, bordes de caminos. Oronja verde: bosque de frondosas.$q1$,$q1$Coprino: negra. Oronja verde: blanca.$q1$,$q1$Las láminas del coprino se vuelven negras; las de la oronja verde NUNCA lo hacen.$q1$,array[$q1$Coprino melenudo (Schopftintling): sombrero ovoide y escamoso; la oronja verde tiene el sombrero liso$q1$,$q1$El coprino crece en prados; la oronja verde, en el bosque$q1$]::text[],true),
($q1$semmelstoppelpilz$q1$,$q1$austernpilz$q1$,$q1$es$q1$,$q1$Lengua de vaca (Semmelstoppelpilz): sobre el suelo, en bosque mixto. Seta de ostra (Austernpilz): sobre el tronco de un árbol.$q1$,null,$q1$Suelo frente a árbol$q1$,null,$q1$Ambas son aptas para principiantes.$q1$,array[$q1$La lengua de vaca tiene PÚAS; la seta de ostra tiene LÁMINAS$q1$,$q1$Suelo frente a tronco de árbol$q1$]::text[],true),
($q1$steinpilz$q1$,$q1$butterpilz$q1$,$q1$es$q1$,$q1$Boletus (Steinpilz): pie con retículo blanco, sin anillo. Boleto granulado anillado (Butterpilz): sombrero viscoso, con anillo.$q1$,null,$q1$Ambos en bosque de coníferas; el Butterpilz, junto al pino silvestre.$q1$,null,$q1$Al Butterpilz se le puede retirar la cutícula (piel del sombrero).$q1$,array[$q1$El boletus tiene el pie liso; el Butterpilz tiene anillo + sombrero viscoso$q1$]::text[],true),
($q1$steinpilz$q1$,$q1$tylopilus_felleus$q1$,$q1$es$q1$,$q1$Color de los tubos (blanco/amarillo frente a rosa) + retículo (fino y blanco frente a grueso y oscuro).$q1$,$q1$Tylopilus felleus (boleto de hiel) extremadamente amargo (probar una porción mínima y escupirla).$q1$,$q1$Ambos en bosques de coníferas/mixtos de suelo ácido, a menudo juntos.$q1$,$q1$Boletus (Steinpilz) oliva; Tylopilus felleus (boleto de hiel) rosa.$q1$,$q1$No es venenoso, pero un solo boleto de hiel arruina un plato entero. Los tubos rosados + el retículo grueso + el amargor lo delatan.$q1$,array[$q1$Boletus (Steinpilz): retículo fino y blanco, tubos blancos/amarillos, sabor suave$q1$,$q1$Tylopilus felleus (boleto de hiel): retículo grueso y oscuro, tubos rosados, extremadamente amargo$q1$]::text[],true),
($q1$zigeunerpilz$q1$,$q1$cortinarius_orellanus$q1$,$q1$es$q1$,$q1$Reifpilz (Cortinarius caperatus): sombrero de color amarillo pajizo a pardo amarillento, con velo escarchado de tono gris-blanquecino-lila, longitudinalmente arrugado, con un anillo membranoso de doble borde. Cortinarius orellanus (orellana, cortinario de montaña): sombrero de color naranja intenso a pardo cobrizo/herrumbroso, fibroso mate a finamente escamoso, seco, SIN escarcha; SIN anillo verdadero, solo una cortina fugaz; pie cilíndrico, del mismo color o amarillento, sin estar marcadamente jaspeado (a diferencia de rubellus).$q1$,$q1$Reifpilz: suave. Cortinarius orellanus (orellana): débilmente a rábano.$q1$,$q1$Reifpilz: bosque de coníferas y (raramente) de frondosas, a menudo en suelo ácido y arenoso, junto al arándano. Cortinarius orellanus (orellana): bosques de frondosas de clima cálido, junto a roble, haya, avellano, castaño, sobre suelos ácidos a básicos (julio-octubre); típicamente no en bosque de coníferas.$q1$,$q1$Reifpilz: pardo canela claro/amarillo herrumbroso. Cortinarius orellanus (orellana): pardo herrumbroso. No hay ningún rasgo aislado que los distinga de forma fiable.$q1$,$q1$Consumir el Reifpilz solo si presenta un anillo firme e inequívoco con doble borde. Un sombrero de color naranja/pardo herrumbroso intenso, seco y fibroso, SIN escarcha y sin anillo verdadero (solo fibras de velo), indica el mortal Cortinarius orellanus (orellana): no lo toques, llévalo al control de setas (VAPKO).$q1$,array[$q1$El Reifpilz posee un anillo membranoso firme en el pie, con doble borde; el Cortinarius orellanus (orellana) NO tiene anillo verdadero, sino solo fibras de velo fugaces (cortina).$q1$,$q1$El sombrero del Reifpilz está escarchado de gris-lila y es arrugado; el sombrero de la orellana es seco-fibroso a finamente escamoso y de un naranja/cobrizo/pardo herrumbroso intenso y uniforme, sin escarcha.$q1$,$q1$El pie de la orellana es del mismo color a amarillento y no está marcadamente jaspeado; el pie del Reifpilz lleva la manga membranosa de doble borde.$q1$,$q1$El tóxico orellanina es resistente al calor y a la desecación y, tras una latencia de días a semanas (3-14 días), provoca una insuficiencia renal mortal: no hay prueba de cata posible ni se puede destoxificar mediante la cocción.$q1$]::text[],true),
($q1$zigeunerpilz$q1$,$q1$cortinarius_rubellus$q1$,$q1$es$q1$,$q1$Pie violeta (Cortinarius caperatus): sombrero de color amarillo paja a pardo amarillento con una pruina (velo) de tono gris-blanquecino-lila, superficie característicamente arrugada/surcada longitudinalmente, anillo membranoso bien marcado en el pie con un borde doble. Cortinarius rubellus: sombrero seco y finamente afieltrado de color pardo canela amarillento a anaranjado o rojo zorruno, con un mamelón puntiagudo (o redondeado), SIN anillo verdadero (solo restos fugaces de cortina/velo), pie esbelto y amarillento con bandas (cinturones amarillos de velo).$q1$,$q1$Pie violeta (Cortinarius caperatus): agradable/suave. Cortinarius rubellus: débilmente parecido al rábano.$q1$,$q1$Pie violeta (Cortinarius caperatus): bosque de coníferas y (raramente) de frondosas, preferentemente junto al arándano en suelos ácidos y arenosos, de agosto a octubre. Cortinarius rubellus: sobre todo bosque de coníferas (rodales de abeto rojo), a menudo en zonas húmedas/pantanosas sobre suelos ácidos, junto al arándano — la coincidencia de hábitat agrava el riesgo.$q1$,$q1$Pie violeta (Cortinarius caperatus): pardo canela claro a amarillo herrumbroso. Cortinarius rubellus: pardo herrumbroso. El color de las esporas NO separa de forma fiable aquí — nunca usarlo como único criterio.$q1$,$q1$Busca en el pie el anillo firme y membranoso con el característico borde DOBLE — si falta este anillo y el pie en su lugar está amarillento con bandas y solo presenta fibras fugaces de velo, no se trata del pie violeta (Cortinarius caperatus), sino posiblemente del mortal Cortinarius rubellus. En ejemplares jóvenes, en caso de duda, acude SIEMPRE a la oficina de control de setas (VAPKO).$q1$,array[$q1$El pie violeta (Cortinarius caperatus) tiene un anillo firme y membranoso en el pie con un característico borde DOBLE; Cortinarius rubellus NO tiene un anillo verdadero, solo fibras fugaces de velo (cortina).$q1$,$q1$El sombrero del pie violeta (Cortinarius caperatus) está cubierto de una PRUINA mate de tono gris-blanquecino a lila y es arrugado longitudinalmente; Cortinarius rubellus tiene un sombrero seco, finamente afieltrado-fibroso, de color pardo canela rojo zorruno con un marcado mamelón PUNTIAGUDO.$q1$,$q1$El pie de Cortinarius rubellus es esbelto y amarillento con BANDAS (cinturones amarillos de velo); el pie del pie violeta (Cortinarius caperatus) es más grueso y lleva el manguito membranoso en lugar de bandas.$q1$,$q1$Consumir solo cuando esté claramente presente el anillo de borde doble; el veneno orellanina es estable al calor y al secado y provoca, tras una latencia de 2 a 21 días, una insuficiencia renal irreversible — ni cocer ni secar lo desintoxica.$q1$]::text[],true),
($q1$agaricus_augustus$q1$,$q1$agaricus_xanthodermus$q1$,$q1$fr$q1$,$q1$Odeur + coloration à la base du pied (anis vs. carbol; jaune faible vs. jaune chrome).$q1$,$q1$Anis (comestible) vs. carbol/encre (toxique) — critère le plus important$q1$,$q1$les deux en forêt/parc/jardin$q1$,$q1$les deux brun chocolat$q1$,$q1$Inciser la base du pied : jaune chrome vif + odeur de carbol = agaric jaunissant (toxique). Pour les agarics blancs, exclure en plus une volve (amanite phalloïde).$q1$,array[$q1$Agaric auguste : odeur d'anis/d'amande, jaunissement faible$q1$,$q1$Agaric jaunissant : odeur de carbol/d'encre (renforcée à la cuisson), base du pied jaune chrome$q1$]::text[],true),
($q1$agaricus_campestris$q1$,$q1$amanita_phalloides$q1$,$q1$fr$q1$,$q1$Champignon de Paris : chapeau blanc-beige, lamelles roses devenant brunes. Amanite phalloïde : chapeau vert olive, lamelles blanches restant blanches.$q1$,$q1$Champignon de Paris : agréable, odeur de champignon. Amanite phalloïde : faiblement sucrée.$q1$,$q1$Champignon de Paris : prairies, pâturages. Amanite phalloïde : forêt de feuillus, chênes.$q1$,$q1$Champignon de Paris : brun foncé. Amanite phalloïde : blanc.$q1$,$q1$TOUJOURS vérifier la base du pied — bulbe dans une volve membraneuse = NE JAMAIS manger !$q1$,array[$q1$Le champignon de Paris n'a JAMAIS de bulbe dans une volve, l'amanite phalloïde en a toujours un$q1$,$q1$Les lamelles du champignon de Paris deviennent roses puis brun chocolat, celles de l'amanite phalloïde restent blanches$q1$]::text[],true),
($q1$amanita_rubescens$q1$,$q1$amanita_pantherina$q1$,$q1$fr$q1$,$q1$Le test de rougissement + l'anneau (strié vs. lisse) + le bulbe sont décisifs.$q1$,$q1$à peine distinguables$q1$,$q1$les deux dans tous les types de forêt$q1$,$q1$les deux blanc$q1$,$q1$L'amanite rougissante n'est réservée qu'aux personnes expérimentées. Vérifier TOUS les caractères ENSEMBLE (rougissement + anneau strié + bulbe sans gaine marginée).$q1$,array[$q1$Amanite rougissante : la chair rougit (surtout à la base du pied/dans les galeries de larves), anneau strié, flocons de vélum gris$q1$,$q1$Amanite panthère : la chair ne rougit JAMAIS, anneau lisse, flocons d'un blanc pur, base bulbeuse marginée, toxines thermostables$q1$]::text[],true),
($q1$austernpilz$q1$,$q1$galerina_marginata$q1$,$q1$fr$q1$,$q1$Pleurote en huître : chapeau en forme de coquille/d'éventail de 5-25 cm, blanc/gris/brun, en touffes imbriquées ; pied latéral ou absent ; lamelles larges, blanchâtres, décurrentes. Galère marginée : petit chapeau convexe de 1-4 cm, ocre à brun cannelle, avec un pied central élancé brunâtre, zone annulaire dans le tiers supérieur du pied, lamelles brun cannelle avec l'âge.$q1$,$q1$Pleurote en huître : doux, agréable, odeur de champignon rappelant l'anis. Galère marginée : faiblement farineuse à insignifiante — l'odeur n'est PAS un critère de distinction fiable, ne pas s'y fier.$q1$,$q1$Les deux sur bois, mais : le pleurote en huître préfère le bois de feuillus (hêtre/peuplier), en touffes en forme de console, souvent haut sur le tronc ; la galère marginée sur bois mort en décomposition (souvent résineux, mais aussi feuillus), petite, isolée à groupée, plutôt près du sol/sur troncs couchés.$q1$,$q1$Pleurote en huître : BLANC à lilas-gris pâle. Galère marginée : BRUN ROUILLE/CANNELLE. C'est le caractère isolé le plus fiable — la sporée sépare les deux avec certitude.$q1$,$q1$Règle d'or : un véritable pleurote en huître est fixé latéralement/sans pied comme une console épaisse et charnue sur le bois et donne une sporée BLANCHE à lilas-gris. Dès qu'un pied central avec un reste d'anneau est présent OU que la sporée est brune, ce n'est PAS un pleurote en huître — alors ne pas y toucher (la galère marginée contient des amatoxines mortelles, le même poison que l'amanite phalloïde). En cas de doute, toujours faire une sporée avant de consommer.$q1$,array[$q1$Sporée : pleurote en huître blanc à lilas-gris ; galère marginée brun rouille/cannelle (la sporée sur papier foncé + clair est le critère de distinction le plus sûr).$q1$,$q1$Pied : le pleurote en huître a un pied latéral/excentré, court ou presque absent et AUCUN anneau ; la galère marginée a un pied central, élancé, avec un reste de zone annulaire membraneuse dans le tiers supérieur.$q1$,$q1$Forme de croissance : le pleurote en huître pousse en tuiles imbriquées, en touffes/consoles épaisses et charnues directement sur le bois ; la galère marginée pousse petite, isolée à groupée, avec un petit chapeau convexe à chair mince sur le bois mort.$q1$,$q1$Lamelles : le pleurote en huître a des lamelles larges, blanchâtres, décurrentes le long du pied (latéral) ; la galère marginée a des lamelles étroites, jeunes d'un ocre pâle, devenant brun cannelle avec l'âge (à cause de la sporée brune).$q1$,$q1$Taille/consistance : le pleurote en huître est grand (chapeau 5-25 cm), tenace-charnu ; la galère marginée est petite (chapeau le plus souvent 1-4 cm), fragile, avec un pied distinct comme un champignon à lamelles ordinaire.$q1$]::text[],true),
($q1$calocybe_gambosa$q1$,$q1$inocybe_erubescens$q1$,$q1$fr$q1$,$q1$Les deux au printemps, clairs ; l'inocybe est fibrilleux radialement/craquelé et rougit, le mousseron de la Saint-Georges est lisse-charnu.$q1$,$q1$Mousseron de la Saint-Georges : fortement farineux-concombre ; inocybe : sucré-spermatique$q1$,$q1$les deux en prairies/lisières de forêt, sur sol calcaire, même saison$q1$,$q1$Mousseron de la Saint-Georges blanc, inocybe brun$q1$,$q1$MORTEL (muscarine). Lamelles blanches + odeur de farine + absence de rougissement sont obligatoires — sinon n'y touchez pas.$q1$,array[$q1$Mousseron de la Saint-Georges : lamelles blanches à tout âge + odeur de farine, la chair ne rougit PAS$q1$,$q1$Inocybe : la chair rougit, lamelles gris-brun, sporée brune, forte teneur en muscarine$q1$]::text[],true),
($q1$champignon-de-paris$q1$,$q1$agaricus_xanthodermus$q1$,$q1$fr$q1$,$q1$Agaric jaunissant : la base du pied vire immédiatement au jaune chrome à la coupe, le centre du chapeau est souvent gris-métallique, la base du pied est bulbeuse sans peau lobée. Champignon de Paris/agaric des prés : la surface de coupe reste blanchâtre à légèrement rosée, pas de base de pied jaune.$q1$,$q1$L'agaric jaunissant dégage une odeur âcre de carbol/phénol/encre (renforcée à la chauffe et en frottant la base du pied). Les champignons comestibles sentent agréablement le champignon, la noisette ou l'anis.$q1$,$q1$Les deux poussent dans des prés riches en nutriments, des pâturages, des parcs et en lisière de forêt, de l'été à l'automne – le lieu de croissance n'aide PAS à les distinguer.$q1$,$q1$Les deux ont une sporée brun chocolat – la couleur de la sporée n'est ici PAS un critère de distinction ; se fier au jaunissement et à l'odeur.$q1$,$q1$Entailler la base du pied dans le sens de la longueur : un jaunissement jaune chrome vif à la base du pied + une odeur de carbol/d'encre = toxique, jeter le champignon. Ne pas le goûter par voie orale. Les suites sont de violents troubles gastro-intestinaux (nausées, vomissements, diarrhée), en règle générale non mortels.$q1$,array[$q1$La base du pied vire immédiatement et intensément au jaune chrome (jaune éclatant) à la coupe/au pincement – les champignons comestibles jaunissent tout au plus légèrement au bord du chapeau, JAMAIS fortement au jaune à la base du pied.$q1$,$q1$Dégage une odeur désagréable de carbol/phénol ou d'encre (perceptible surtout sur la base du pied frottée ou à la chauffe) – les champignons comestibles sentent le champignon, la noisette ou l'anis/l'amande.$q1$,$q1$Base du pied épaissie en bulbe SANS peau lobée/volve ; le jeune chapeau présente souvent un reflet gris-métallique au centre ; lamelles roses jeunes, brun chocolat foncé avec l'âge.$q1$,$q1$Lieu de croissance identique (prés, pâturages, parcs, lisières de forêt, sols riches en nutriments), d'où une confusion réelle fréquente – le lieu de croissance n'aide PAS à les distinguer.$q1$]::text[],true),
($q1$champignon-de-paris$q1$,$q1$amanita_phalloides$q1$,$q1$fr$q1$,$q1$Amanita phalloides : lamelles restant blanches, volve membraneuse blanche à la base bulbeuse du pied, chapeau vert olive à (var. alba/jeune) blanc. Champignon de Paris : lamelles rose-brun, pas de volve, base du pied sans gaine.$q1$,$q1$Amanita phalloides jeune : odeur discrète ; âgé : moisi-douceâtre rappelant le miel artificiel, jusqu'à désagréable. Champignon de Paris : agréablement champignonné/de noisette/d'anis.$q1$,$q1$Amanita phalloides est un champignon mycorhizien des forêts de feuillus (surtout sous chêne, hêtre) ; les champignons de Paris poussent en terrain cultivé ouvert, dans les prés et les pâturages.$q1$,$q1$Amanita phalloides : blanche ; champignon de Paris : brune – une sporée blanche est un signal d'alarme clair.$q1$,$q1$Couper en deux dans la longueur tout bouton/œuf blanc suspect : l'ébauche de lamelles blanches + une enveloppe de volve à la base = amanite phalloïde, mortelle. Environ 20 g suffisent déjà à mettre la vie en danger – en cas de doute, contrôle des champignons VAPKO / Tox Info Suisse 145.$q1$,array[$q1$Lamelles toujours d'un blanc pur (même chez le champignon âgé) – les lamelles du champignon de Paris sont roses jeunes, brunes/brun-noir âgées.$q1$,$q1$Base du pied bulbeuse, entourée d'une gaine membraneuse blanche lobée (volve) – chez le champignon de Paris, la volve est totalement absente.$q1$,$q1$Sporée blanche (champignon de Paris : brune).$q1$,$q1$Les jeunes exemplaires ressemblent à un « œuf » blanc et se confondent particulièrement facilement avec de jeunes champignons de Paris encore fermés – toujours couper ; à la coupe apparaît la structure de lamelles/volve blanche ébauchée (intérieur uniformément blanc-vert, jamais rose).$q1$]::text[],true),
($q1$calvatia_gigantea$q1$,$q1$gemeiner-fliegenpilz-var-alba$q1$,$q1$fr$q1$,$q1$Vesse-de-loup : peau blanche lisse et fermée, arrondie, sans pied. A. virosa jeune : œuf d'un blanc pur dans une enveloppe membraneuse ; à maturité, entièrement blanc avec un chapeau conique-pointu, un anneau et une volve membraneuse. Au stade « œuf », extérieurement à peine dissociable de la vesse-de-loup.$q1$,$q1$A. virosa mûr : odeur désagréable, douceâtre-écœurante (vieux spécimens). Vesse-de-loup jeune : douce-champignonnée. L'odeur au stade jeune/œuf n'est pas fiable — ne pas la considérer comme un feu vert.$q1$,$q1$A. virosa : mycorhizien des forêts de conifères/mixtes acides, souvent sous épicéa/bouleau, plutôt dans les régions de montagne plus froides/montagnardes. Vesse-de-loup géante : prairies ouvertes, pâturages, jardins. Recouvrement de stations moindre que chez phalloides, mais le test de coupe reste obligatoire.$q1$,$q1$Vesse-de-loup : pas de lamelles/pas de sporée pertinente. A. virosa : sporée blanche. Au stade « œuf » confondable, inutilisable — seule la coupe compte.$q1$,$q1$Pour tout petit champignon blanc en boule, faire une coupe longitudinale : un « embryon » de champignon blanc visible à la coupe (pied + chapeau ébauché) démasque l'amanite vireuse. Seule une masse blanche sans structure = vesse-de-loup.$q1$,array[$q1$Le jeune œuf d'A. virosa est d'un BLANC PUR et sphérique — optiquement quasi identique à une jeune vesse-de-loup blanche. C'est précisément pourquoi le test de coupe est ici le plus important.$q1$,$q1$TEST DE COUPE : vesse-de-loup = masse blanche homogène d'un bout à l'autre ; A. virosa montre en coupe longitudinale des lamelles, un pied et un bulbe déjà ébauchés (contour de champignon à l'intérieur) = mortelle.$q1$,$q1$A. virosa possède une volve membraneuse, en forme de sac, à la base du pied et (plus tard) un anneau ; la vesse-de-loup n'a ni volve, ni pied, ni anneau.$q1$,$q1$Confusion uniquement au stade jeune et sphérique — dès que le chapeau/le pied de l'amanite apparaissent, la distinction est triviale.$q1$]::text[],true),
($q1$calvatia_gigantea$q1$,$q1$amanita_phalloides$q1$,$q1$fr$q1$,$q1$Vesse-de-loup géante : peau extérieure lisse, blanche à crème, fermée, sphérique, sans pied/enveloppe/volve. A. phalloides jeune dans l'œuf : enveloppe générale membraneuse blanche à teintée d'olive, sphérique-ovoïde — extérieurement à s'y méprendre, c'est pourquoi seule la coupe compte.$q1$,$q1$Vesse-de-loup jeune : agréablement champignonnée-douce. A. phalloides mûr : douceâtre-mielleux jusqu'à désagréable ; au stade « œuf » à peine perceptible, donc PAS un critère fiable — ne jamais considérer l'odeur comme un feu vert.$q1$,$q1$Vesse-de-loup géante : prés, pâturages, jardins, bords de chemins, sols riches en nutriments (pas un champignon mycorhizien). A. phalloides : champignon mycorhizien des forêts de feuillus/mixtes, surtout sous chêne et hêtre. Recouvrement possible en lisière de forêt/dans les parcs — le lieu seul ne protège pas.$q1$,$q1$Chez la vesse-de-loup : non pertinent (pas de lamelles). A. phalloides : sporée blanche. Au stade « œuf », les deux ne sont pas significatifs — distinction uniquement par la coupe longitudinale.$q1$,$q1$Couper CHAQUE petite « vesse-de-loup » sphérique entièrement dans la longueur (du haut vers le bas) AVANT utilisation. Ce n'est une vesse-de-loup que si la surface est d'un blanc pur et homogène d'un bout à l'autre — sans aucun contour de pied/de lamelles/de chapeau. À la moindre structure interne : amanite phalloïde mortelle, jeter tout le panier.$q1$,array[$q1$TEST DE COUPE (décisif) : la vesse-de-loup géante a une chair fertile entièrement homogène, d'un blanc pur, sans structure interne. Chez la jeune amanite phalloïde au stade « œuf », la coupe longitudinale révèle déjà des lamelles, un pied et un bulbe ébauchés, en silhouette/« embryon » = mortelle, jeter immédiatement.$q1$,$q1$Couleur interne : jeune vesse-de-loup d'un blanc pur et homogène à l'intérieur. Toute coloration jaunâtre/verdâtre ou tout contour de champignon plus sombre à la coupe = pas une vesse-de-loup.$q1$,$q1$Enveloppe externe : la vesse-de-loup a une peau extérieure lisse, coriace-fermée, sans volve. L'œuf de l'amanite phalloïde est logé dans une enveloppe générale membraneuse (velum universale), d'où se forment la volve et la base du pied.$q1$,$q1$La vesse-de-loup géante mûre (>10 cm jusqu'à 50 cm) est inconfondable — la confusion n'est possible que pour de petits jeunes spécimens sphériques. Règle empirique : ne pas manger une « vesse-de-loup » plus petite qu'une paume de main sans contrôle par coupe.$q1$]::text[],true),
($q1$calvatia_gigantea$q1$,$q1$amanita_verna$q1$,$q1$fr$q1$,$q1$Vesse-de-loup : peau extérieure lisse, blanche, fermée, sans structure, sphérique. A. verna jeune : œuf de velum d'un blanc pur ; mûr, entièrement blanc avec volve membraneuse et anneau. Les stades « œuf » sont extérieurement quasi identiques.$q1$,$q1$A. verna : discrète à légèrement désagréable. Vesse-de-loup jeune : douce-champignonnée. Pas un critère de distinction fiable au stade jeune.$q1$,$q1$A. verna : mycorhizien des forêts de feuillus/mixtes (souvent calcaires) à climat favorisé sous chêne/châtaignier, apparaît surtout au printemps/début d'été, à tonalité méditerranéenne (expositions sud). Vesse-de-loup géante : prairies/pâturages, plutôt fin d'été/automne. Des différences de saison et de station existent, mais ne remplacent pas le test de coupe.$q1$,$q1$Vesse-de-loup non pertinente. A. verna : sporée blanche. Au stade « œuf », sans valeur pour la distinction — la coupe décide.$q1$,$q1$Coupe longitudinale à travers chaque petit champignon blanc en boule : si la silhouette d'un petit champignon (pied + ébauche de chapeau) apparaît dans la chair blanche, c'est l'amanite printanière mortelle — et non la vesse-de-loup.$q1$,array[$q1$Le jeune œuf d'A. verna est d'un blanc pur et sphérique comme une jeune vesse-de-loup — la confusion est de ce fait réelle, d'autant que verna pousse aussi dans des stations plus ouvertes et plus chaudes.$q1$,$q1$TEST DE COUPE : masse blanche homogène de la vesse-de-loup vs. pied + ébauche de lamelles + bulbe déjà reconnaissables à l'intérieur chez l'amanite = mortelle.$q1$,$q1$A. verna possède une volve membraneuse et un bulbe à la base du pied ; la vesse-de-loup n'a ni volve ni pied.$q1$,$q1$Seul le jeune stade sphérique est confondable ; l'amanite mûre avec chapeau/pied/anneau est sans équivoque.$q1$]::text[],true),
($q1$champignon-de-paris$q1$,$q1$gemeiner-fliegenpilz-var-alba$q1$,$q1$fr$q1$,$q1$Amanita virosa: chapeau d'un blanc pur, souvent conique, lamelles restant blanches, base du pied bulbeuse avec une volve blanche en lambeaux. Champignon de Paris: lamelles roses à brunes, pas de volve, base du pied sans gaine membraneuse.$q1$,$q1$Amanita virosa: discrète à douceâtre-écœurante (chair en décomposition). Champignon de Paris: agréable, fongique/de noisette/anisée.$q1$,$q1$Amanita virosa en forêt (souvent épicéas/forêt de conifères, sols acides); les champignons de Paris dans les prairies, pâturages, composts et terres cultivées.$q1$,$q1$Amanita virosa blanche, champignon de Paris brune – la sporée est un critère de distinction fiable (blanc = danger).$q1$,$q1$Toujours extraire le champignon entièrement du sol, avec la base du pied, et vérifier la présence d'une volve (gaine membraneuse) au pied du bulbe – volve + lamelles restant blanches + sporée blanche = mortel, n'y touchez pas. En cas de doute, Tox Info Suisse 145 / contrôle des champignons VAPKO.$q1$,array[$q1$Les lamelles restent d'un blanc pur à TOUT âge – les lamelles du champignon de Paris sont roses lorsqu'elles sont jeunes et deviennent brun chocolat à brun-noir en vieillissant (jamais durablement blanches).$q1$,$q1$À la base du pied, une base bulbeuse épaissie avec une gaine membraneuse blanche en lambeaux (volve/voile) – les champignons de Paris n'ont JAMAIS de volve.$q1$,$q1$Sporée blanche; la sporée du champignon de Paris est brune.$q1$,$q1$Pousse le plus souvent en forêt (de conifères), souvent près des épicéas – les champignons de Paris préfèrent les prairies, pâturages et terres cultivées.$q1$]::text[],true),
($q1$clitocybe_nebularis$q1$,$q1$entoloma_sinuatum$q1$,$q1$fr$q1$,$q1$Entolome livide (grand entolome): chapeau plus compact, plus charnu, gris clair à jaune argileux/ivoire; lamelles blanchâtres-jaunâtres lorsqu'elles sont jeunes, rose chair en vieillissant, courtes et échancrées (sinuées) à l'insertion, non décurrentes. Clitocybe nébuleux: grand chapeau (10-25 cm) gris brouillard avec des lamelles blanchâtres-crème, serrées et brièvement décurrentes sur le pied.$q1$,$q1$Clitocybe nébuleux: douceâtre-épicé envahissant (perçu comme désagréable par beaucoup). Entolome livide: farineux-rance avec une note acidulée-raphanoïde désagréable.$q1$,$q1$Entolome livide: calcicole, dans les forêts de feuillus et mixtes (surtout hêtre, chêne, charme) sur sols calcaires/argileux, plutôt rare, de mai à novembre; pousse isolé, en groupes OU en ronds de sorcières. Clitocybe nébuleux: fréquent et souvent en masse, forêts de feuillus et de conifères, fin de l'automne (oct.-nov.), forme également des rangées et des ronds de sorcières. ATTENTION: la croissance en rond de sorcières NE permet PAS de distinguer les deux espèces — toutes deux la présentent.$q1$,$q1$DÉCISIF: entolome livide rose chair à rose-brun (caractère du genre Entoloma). Clitocybe nébuleux blanche à crème-jaunâtre pâle. Une simple sporée sur papier blanc sépare les deux avec certitude — c'est le critère le plus fiable.$q1$,$q1$La sporée est obligatoire: poudre rose/rose chair = entolome (Rötling) = NE PAS manger. Le clitocybe nébuleux laisse une sporée blanche à crème pâle et a des lamelles brièvement décurrentes et serrées. Ne vous fiez PAS à la forme de croissance — les DEUX espèces peuvent former des rangées et des ronds de sorcières, ce n'est PAS un critère de distinction.$q1$,array[$q1$Sporée (critère le PLUS SÛR): entolome livide rose chair à rose-brun (genre des entolomes/Rötling) — clitocybe nébuleux blanche à crème-jaunâtre pâle. Une sporée sur papier blanc sépare les deux sans équivoque.$q1$,$q1$Couleur des lamelles à maturité: les lamelles de l'entolome livide sont blanchâtres/jaunâtres lorsqu'elles sont jeunes, et deviennent nettement ROSE chair avec l'âge sous l'effet des spores — les lamelles du clitocybe nébuleux restent blanches à crème-jaunâtre, JAMAIS roses.$q1$,$q1$Insertion des lamelles: les lamelles du clitocybe nébuleux sont brièvement DÉCURRENTES sur le pied (typique des clitocybes), serrées; les lamelles de l'entolome livide sont échancrées (sinuées) à l'insertion, courtes, rigides et peu serrées — NON décurrentes.$q1$,$q1$Odeur: clitocybe nébuleux douceâtre-épicé envahissant; entolome livide farineux-rance avec une note désagréable acidulée-raphanoïde.$q1$]::text[],true),
($q1$eierschwamm$q1$,$q1$cortinarius_orellanus$q1$,$q1$fr$q1$,$q1$Girolle (chanterelle): jaune d'œuf, en forme d'entonnoir et à plis. Cortinaire (Raukopf): brun-roux à orange avec de véritables lamelles.$q1$,$q1$Girolle: fruitée, d'abricot. Cortinaire: de radis (raphanoïde).$q1$,$q1$Girolle: de mai à octobre, forêt de conifères. Cortinaire: de septembre à novembre, forêt de feuillus.$q1$,$q1$Girolle: jaune pâle. Cortinaire: brun-rouille.$q1$,$q1$RÈGLE D'OR: retournez le chapeau — de VRAIES lamelles ou des PLIS? En cas de doute, VAPKO!$q1$,array[$q1$La girolle a des PLIS, le cortinaire (Raukopf) a de VRAIES lamelles$q1$,$q1$La girolle est jaune d'œuf-abricot, le cortinaire est orange-brun-roux$q1$]::text[],true),
($q1$eierschwamm$q1$,$q1$hygrophoropsis_aurantiaca$q1$,$q1$fr$q1$,$q1$Plis (girolle) vs. véritables lamelles (la fausse girolle); consistance ferme vs. molle.$q1$,$q1$Girolle fruitée (abricot); la fausse non spécifique/de moisi$q1$,$q1$Girolle forêt de feuillus/de conifères; la fausse surtout litière d'aiguilles/bois mort$q1$,$q1$les deux pâles$q1$,$q1$La fausse girolle est faiblement toxique (troubles gastro-intestinaux). Vérifiez les plis émoussés vs. les lamelles vives et détachables. Si la couleur est d'un orange-rouge soutenu, excluez en plus le clitocybe de l'olivier (toxique).$q1$,array[$q1$Vraie girolle: plis émoussés, fermement soudés, ferme-charnue$q1$,$q1$Fausse girolle: véritables lamelles fines, fortement fourchues, facilement détachables, molle$q1$]::text[],true),
($q1$hallimasch$q1$,$q1$cortinarius_orellanus$q1$,$q1$fr$q1$,$q1$Armillaire (Hallimasch): jaune miel avec un anneau, en touffes. Cortinaire (Raukopf): orange-brun-roux, isolé.$q1$,$q1$Armillaire: acidulée. Cortinaire: de radis (raphanoïde).$q1$,$q1$Armillaire: souches d'arbres, racines. Cortinaire: au sol, forêt de feuillus.$q1$,$q1$Armillaire: blanche. Cortinaire: brun-rouille.$q1$,$q1$Soyez particulièrement vigilant avec les jeunes champignons. Faites une sporée.$q1$,array[$q1$L'armillaire a un anneau + est parasite sur l'arbre, le cortinaire (Raukopf) est isolé$q1$,$q1$Sporée: armillaire blanche, cortinaire brun-rouille$q1$]::text[],true),
($q1$infundibulicybe_geotropa$q1$,$q1$clitocybe_dealbata$q1$,$q1$fr$q1$,$q1$Tête-de-moine (Infundibulicybe geotropa) : 12-25 cm, crème/couleur cuir à ocre-rougeâtre avec l'âge, mamelon central perceptible au toucher, pied robuste et clavé. Clitocybe blanchi des champs (Clitocybe dealbata) : seulement 2-5 cm, blanc craie pruineux, déprimé/aplati sans mamelon, pied mince et grêle.$q1$,$q1$La Tête-de-moine dégage une odeur aromatique douceâtre avec une nette note d'amande amère ; le Clitocybe blanchi des champs est insignifiant à faiblement farineux. Attention : l'odeur est un caractère COMPLÉMENTAIRE, jamais le seul critère de sécurité — toujours le combiner avec la taille/le mamelon/l'épaisseur de la chair.$q1$,$q1$Clitocybe blanchi des champs : prairies ouvertes, prés, pâturages, pelouses, bords de chemins, parcs. Tête-de-moine : forêts de feuillus et de conifères, lisières de forêt, clairières herbeuses sur sol calcaire humide. Les deux peuvent former des ronds de sorcière — le type de station (forêt vs herbe ouverte) est plus pertinent que la croissance en ronds.$q1$,$q1$Les deux BLANC — la sporée n'aide PAS ici à les distinguer. La distinction se fait par la taille, l'épaisseur de la chair, le mamelon du chapeau et l'épaisseur du pied.$q1$,$q1$Règle d'or : les PETITS clitocybes blancs (moins d'environ 6 cm, à chair mince, sans mamelon perceptible au toucher) ne JAMAIS les manger — ils contiennent de la muscarine et, en tant que groupe, sont confusibles de manière mortelle. Ne prendre que la grande Tête-de-moine (12-25 cm), à chair épaisse, avec un mamelon central nettement perceptible au toucher et un pied robuste. Ronds de sorcière et sporée blanche : les DEUX les présentent — ils ne servent PAS à les distinguer.$q1$,array[$q1$Taille/chair : le Clitocybe blanchi des champs n'a que 2-5 cm de chapeau, chair mince (quelques mm) ; la Tête-de-moine 12-25 cm, à chair épaisse et avec un mamelon/une verrue central nettement perceptible au toucher au centre du chapeau (test au doigt) — ce mamelon manque toujours au Clitocybe blanchi des champs.$q1$,$q1$Tous deux blancs/crème & en entonnoir avec des lamelles décurrentes et une sporée BLANCHE — la couleur du chapeau et la sporée n'aident PAS, seuls la taille + l'épaisseur de la chair + le mamelon + la station les séparent avec certitude.$q1$,$q1$Station/saison : le Clitocybe blanchi des champs dans les prés, pâturages, bords de chemins, pelouses, parcs (début d'été à fin d'automne, souvent en ronds de sorcière) ; la Tête-de-moine en forêt de feuillus/conifères, en lisière de forêt et dans les clairières herbeuses sur sol calcaire humide (fin d'été à automne, également en ronds de sorcière — la station seule ne SUFFIT PAS).$q1$,$q1$Pied : la Tête-de-moine a un pied robuste, souvent clavé et épaissi (2-4 cm d'épaisseur, 8-15 cm de long) ; le Clitocybe blanchi des champs grêle et mince.$q1$]::text[],true),
($q1$infundibulicybe_geotropa$q1$,$q1$clitocybe_rivulosa$q1$,$q1$fr$q1$,$q1$Clitocybe rivulé (Clitocybe rivulosa) : jusqu'à 4-5 cm, blanc craie pruineux, déprimé sans mamelon, pied mince. Tête-de-moine : 12-25 cm, crème/couleur cuir, avec un mamelon central, pied épais et clavé.$q1$,$q1$La Tête-de-moine aromatique douceâtre avec une note d'amande amère ; le Clitocybe rivulé discret à faible. N'utiliser l'odeur que comme caractère complémentaire, jamais seule.$q1$,$q1$Clitocybe rivulé : gazons, prairies, bords de chemins, dunes, talus, parcs (dans l'herbe, en troupes/ronds de sorcière). Tête-de-moine : forêt de feuillus/conifères sur sol calcaire, lisières de forêt, clairières herbeuses. Forêt vs herbage ouvert est le critère de station pertinent.$q1$,$q1$Les deux BLANC — aucune distinction possible par la couleur de la sporée ; taille + épaisseur de la chair + station + mamelon décident.$q1$,$q1$Tout petit clitocybe pruineux blanc craie dans l'herbe/le gazon est suspect de muscarine — en cas de doute, le laisser sur place. La Tête-de-moine est grande (12-25 cm), à chair épaisse, liée à la forêt et présente un mamelon central perceptible au toucher — ce n'est pas le gracile petit champignon blanc des prairies. Une sporée blanche n'EXCLUT PAS le clitocybe toxique, car lui aussi a une sporée blanche.$q1$,array[$q1$Taille : le Clitocybe rivulé seulement jusqu'à env. 4-5 cm de chapeau, blanc craie pruineux, déprimé/creusé sans mamelon ; la Tête-de-moine 12-25 cm, à chair épaisse, avec un mamelon central nettement perceptible au toucher.$q1$,$q1$Tous deux blanchâtres-en entonnoir avec des lamelles décurrentes et une sporée BLANCHE — seules la taille, l'épaisseur de la chair et le mamelon du chapeau les séparent avec certitude, la couleur et la sporée NON.$q1$,$q1$Très toxique par la muscarine (syndrome muscarinien : forte salivation/transpiration/larmoiement en 15-30 min, dans les cas graves collapsus circulatoire), souvent dans les mêmes stations de prairies/bords de chemins/dunes, en troupes ou en ronds de sorcière.$q1$,$q1$Pied grêle/mince chez le clitocybe toxique vs robuste-clavé (2-4 cm d'épaisseur) chez la Tête-de-moine.$q1$]::text[],true),
($q1$infundibulicybe_geotropa$q1$,$q1$entoloma_sinuatum$q1$,$q1$fr$q1$,$q1$Entolome livide (Entoloma sinuatum) : 5-20 cm, ivoire/brun-gris clair à gris lilas pâle, convexe à marge ondulée sans mamelon, lamelles épaisses et rigides qui virent au rose. Tête-de-moine : en forme d'entonnoir avec un mamelon central, lamelles blanches décurrentes, crème/couleur cuir.$q1$,$q1$L'Entolome livide farineux avec une odeur secondaire désagréablement acidulée-raphanoïde ; la Tête-de-moine aromatique douceâtre avec un arôme d'amande amère. N'utiliser l'odeur que comme caractère complémentaire, la sporée est décisive.$q1$,$q1$Entolome livide : forêt de feuillus claire (souvent hêtre/chêne-charme) sur sol frais à humide, riche en calcaire, été-automne, mycorhizien. Tête-de-moine : forêt de feuillus/conifères, lisières de forêt, clairières herbeuses sur sol calcaire humide, fin d'été-automne — les stations se recouvrent, c'est pourquoi le contrôle de la sporée et des lamelles est impératif.$q1$,$q1$Décisif : l'Entolome livide a une sporée ROSE CHAIR/rose-rougeâtre chair vs la Tête-de-moine BLANCHE. C'est le caractère de distinction le plus sûr entre ces deux espèces.$q1$,$q1$Faire une sporée : poudre rose/couleur chair = Entolome livide = laisser sur place. Vérifier en plus si les lamelles sont décurrentes (Tête-de-moine) ou seulement échancrées/à insertion droite et virant au rose à maturité (Entolome livide). Si le mamelon central manque et que le chapeau n'est pas véritablement en entonnoir, la prudence s'impose.$q1$,array[$q1$SPORÉE : l'Entolome livide a une sporée ROSE CHAIR (rose-rougeâtre chair) ; la Tête-de-moine a une sporée BLANCHE — le caractère de distinction le plus sûr par la sporée.$q1$,$q1$LAMELLES : les lamelles de l'Entolome livide sont blanchâtres jeunes, puis jaunâtres, finalement rose chair par les spores, échancrées/à insertion droite au pied (NON décurrentes) ; les lamelles de la Tête-de-moine restent blanches/crème et sont nettement décurrentes sur le pied.$q1$,$q1$FORME DU CHAPEAU : l'Entolome livide convexe à marge enroulée puis ondulée, SANS mamelon central et sans forme d'entonnoir prononcée ; la Tête-de-moine en forme d'entonnoir avec un mamelon central perceptible au toucher.$q1$,$q1$ODEUR : l'Entolome livide farineux avec une note désagréablement acidulée-raphanoïde ; la Tête-de-moine aromatique douceâtre avec une note d'amande amère.$q1$]::text[],true),
($q1$kuehneromyces_mutabilis$q1$,$q1$galerina_marginata$q1$,$q1$fr$q1$,$q1$Tous deux brun miel, hygrophanes, en touffes sur le bois — très semblables visuellement ; seul le pied sous la zone annulaire les distingue (squameux vs lisse).$q1$,$q1$tous deux fongiques, aucune distinction olfactive fiable$q1$,$q1$tous deux sur bois mort/souches, souvent mêlés$q1$,$q1$tous deux brun rouille$q1$,$q1$MORTEL. Interdit aux débutants. Ne récolter qu'avec le pied complet et vérifier chaque champignon individuellement — en cas de doute, au contrôle VAPKO.$q1$,array[$q1$Pied au-dessous de l'anneau : la Pholiote changeante squameux/pruineux, la Galère marginée lisse-soyeux$q1$,$q1$La Galère marginée contient des amatoxines mortelles$q1$]::text[],true),
($q1$lactarius_deliciosus$q1$,$q1$paxillus_involutus$q1$,$q1$fr$q1$,$q1$Lactaire délicieux : entièrement orange à rouge carotte, chapeau à zones concentriques plus foncées, souvent des taches verdâtres avec l'âge/en cas de blessure, pied souvent à scrobicules. Paxille enroulé : terne brun jaunâtre à brun ombré, marge du chapeau durablement enroulée et feutrée, pas d'orange, pas de zones concentriques de lactaire.$q1$,$q1$Lactaire délicieux : douce, fruitée. Paxille enroulé : discrète, légèrement acidulée ; pas de parfum typique de lactaire.$q1$,$q1$Chevauchement d'habitat possible : le Lactaire délicieux est partenaire de mycorhize des pins (en partie épicéas), plutôt sur sol calcaire. Le Paxille enroulé forme une mycorhize avec le pin, l'épicéa, le bouleau, le hêtre sur sols acides, frais à humides. La station n'est donc PAS un caractère de distinction sûr — seuls le test du lait et la couleur comptent.$q1$,$q1$Lactaire délicieux : sporée blanc crème à ocre-jaunâtre pâle. Paxille enroulé : sporée brunâtre (brun argile) — nettement plus foncée. Direction diagnostique claire : le paxille toujours sensiblement plus foncé.$q1$,$q1$Le test de coupe/du lait est obligatoire : qui ne voit AUCUN latex orange-rouge à la coupe n'a pas un lactaire — le laisser sur place. Le Paxille enroulé ne sécrète jamais de lait et noircit-brunit à la pression (le lactaire ne fait que verdir lentement). Le syndrome paxillien (immuno-hémolytique) peut être mortel après des années de consommation répétée — ne jamais le goûter 'pour essayer', même cuit.$q1$,array[$q1$TEST DU LAIT (décisif) : le Lactaire délicieux libère à la coupe un latex abondant rouge carotte/orange. Le Paxille enroulé ne libère AUCUN lait — ce n'est pas un lactaire. Pas de latex orange-rouge = pas de lactaire.$q1$,$q1$Changement de couleur à la pression : les lamelles et la chair du Paxille se colorent immédiatement à la pression/blessure du brun au brun foncé rougeâtre/noirâtre. La chair/le lait du Lactaire ne se colore que lentement en verdâtre (jamais brun-noir).$q1$,$q1$Lamelles : le Paxille ocre-jaune → brun olive, décurrentes sur le pied et facilement détachables de la chair du chapeau. Les lamelles du Lactaire sont orange/safran et non détachables.$q1$,$q1$Couleur du chapeau + marge : le Lactaire orange à rouge carotte avec des zones annulaires concentriques plus foncées. Le Paxille terne brun jaunâtre à brun ombré, sans orange, à marge du chapeau durablement enroulée et feutrée (même avec l'âge).$q1$]::text[],true),
($q1$lactarius_deterrimus$q1$,$q1$paxillus_involutus$q1$,$q1$fr$q1$,$q1$Lactaire de l'épicéa (lactaire saumon) : chapeau rouge orangé à brun orangé, devenant taché de vert sale avec l'âge ou par le gel, lamelles orange pâle qui virent au rouge foncé puis au gris-vert lorsqu'on les blesse. Paillet enroulé (paxille enroulé) : chapeau jaunâtre à brun ombré, luisant à l'humidité, jeune avec une marge feutrée longtemps enroulée, devenant nettement déprimé en entonnoir avec l'âge ; lamelles ocre-jaunâtre à brun olive, fines et serrées, décurrentes et détachables, qui brunissent FORTEMENT en brun rouille à noirâtre à la pression ou au toucher (les lamelles du lactaire ne brunissent pas en rouille). Les deux peuvent paraître en entonnoir et brun orangé -> d'où la confusion.$q1$,$q1$Lactaire de l'épicéa : doux, fruité-épicé (saveur légèrement amère). Paillet enroulé : aigrelet et discret ; l'odeur n'est PAS un critère de distinction fiable — le test du lait et le test de pression des lamelles sont décisifs.$q1$,$q1$Recouvrement existant : le paillet enroulé est un partenaire mycorhizien, entre autres, de l'épicéa (mais aussi du pin, du bouleau, du hêtre, du charme) et pousse dans le même sol acide de forêt de conifères/forêt mixte où le lactaire de l'épicéa apparaît auprès de l'épicéa. L'habitat ne permet PAS une distinction fiable.$q1$,$q1$Caractère secondaire, ne séparant pas nettement : lactaire de l'épicéa, selon les sources, crème à ocre pâle à brun ocracé ; paillet enroulé nettement brun argile à brun rouille. Les couleurs se chevauchent vers l'ocre — donc à utiliser seulement comme preuve complémentaire, pas comme critère principal. Le test du lait reste décisif. En cas de doute, prendre une sporée.$q1$,$q1$Toujours faire le test du lait : couper à frais et vérifier l'écoulement de lait. Si AUCUN lait ne s'écoule, ce n'est pas un lactaire — le paillet enroulé est dépourvu de lait et peut, par le syndrome cumulatif de Paxillus (anémie hémolytique, insuffisance rénale), devenir mortel même après des années de consommation. Les lactaires, eux, libèrent un lait orange/rouge carotte qui vire au rouge vineux. Règle de base : ne récolter que les lactaires à lait rouge/orange — jamais à lait clair/blanc ni totalement dépourvus de lait.$q1$,array[$q1$TEST DU LAIT (décisif, vérifié) : le lactaire de l'épicéa libère à la coupe un lait orange/rouge carotte qui vire au rouge vineux en 15-20 min (puis au gris-vert) ; le paillet enroulé ne libère AUCUN lait/liquide — aucun lait du tout = NE JAMAIS manger lorsqu'on s'attend à un lactaire.$q1$,$q1$Test de pression des lamelles (vérifié) : les lamelles du paillet se colorent fortement en brun rouille à noirâtre sous la pression et se détachent du chapeau ; les lamelles du lactaire sont cassantes, solidement attachées au chapeau et virent au rouge foncé/gris-vert lorsqu'on les blesse, pas au brun rouille.$q1$,$q1$Marge du chapeau & forme : le paillet a une marge longuement feutrée-enroulée et un chapeau brun olive luisant ; le chapeau du lactaire est orange à taches vertes, sans marge durablement feutrée-enroulée.$q1$,$q1$Sporée (complément, pas fiable à elle seule) : lactaire crème à ocre vs paillet brun argile/rouille — chevauchement vers l'ocre, donc seulement à titre complémentaire.$q1$]::text[],true),
($q1$lepista_nuda$q1$,$q1$cortinarius_orellanus$q1$,$q1$fr$q1$,$q1$Cortinarius orellanus : chapeau brun jaunâtre/brun rougeâtre, légèrement mamelonné, finement squameux-fibrilleux, lamelles brun jaune-cannelle, fibrilles de voile brun rouille sur le pied. Lepista nuda : entièrement violet, chapeau lisse et bombé sans voile.$q1$,$q1$Lepista nuda nettement aromatique-sucré (parfumé). orellanus a une odeur faiblement raphanoïde (de radis), sans parfum sucré. L'odeur seulement comme indice, jamais fiable à elle seule.$q1$,$q1$orellanus : forêt de feuillus/forêt mixte auprès du chêne et du hêtre (mycorhize), de l'été à la fin de l'automne, plutôt rare/thermophile. Lepista nuda : litière riche en nutriments, haies, compost, très tard dans la saison.$q1$,$q1$Lepista nuda rose-blanchâtre pâle ; Cortinarius orellanus brun rouille. Une sporée brun rouille exclut Lepista nuda.$q1$,$q1$La prise d'une sporée est obligatoire : brun rouille = cortinaire, danger mortel. Cortinarius orellanus est considéré comme l'un des champignons les plus dangereux d'Europe (orellanine, latence jusqu'à 14 jours, lésions rénales et hépatiques). Un voile arachnéen sur le jeune champignon ou des fibrilles brun rouille sur le pied = ne jamais manger. Au moindre doute, jeter.$q1$,array[$q1$Sporée (critère le plus fiable face à tout le genre des cortinaires) : Lepista nuda rose-blanchâtre pâle vs Cortinarius orellanus brun rouille. Une sporée brun rouille exclut Lepista nuda.$q1$,$q1$Cortine/voile : orellanus possède un voile arachnéen (jaunâtre quand jeune) avec des restes de voile brun rouille sur le pied ; Lepista nuda n'a aucun velum.$q1$,$q1$Couleur du chapeau : orellanus brun jaune à brun rougeâtre/fauve (JAMAIS violet), souvent légèrement mamelonné ; Lepista nuda entièrement violet dans la jeunesse.$q1$,$q1$Couleur des lamelles : orellanus brun jaune/cannelle, espacées, échancrées-adnées ; Lepista nuda violet/violet-rose et restant clair.$q1$]::text[],true),
($q1$lepista_nuda$q1$,$q1$cortinarius_rubellus$q1$,$q1$fr$q1$,$q1$Lepista nuda : jeune, entièrement violet (chapeau, lamelles, pied), chapeau bombé et lisse sans mamelon pointu, sans voile. Cortinarius rubellus : chapeau orange rouille à orange roux avec un sommet pointu (mamelonné), finement feutré-fibrilleux, lamelles brun cannelle/rouille, fibrilles de voile brun rouille sur le pied.$q1$,$q1$Lepista nuda sent l'aromatique-sucré (parfumé, rappelant le biscuit/la fleur d'oranger). Cortinarius rubellus a une faible odeur raphanoïde (de radis), sans le parfum sucré typique. L'odeur n'est qu'un indice, JAMAIS fiable à elle seule — la sporée + la cortine sont décisives.$q1$,$q1$Cortinaire (rubellus) : forêts de conifères acides (épicéa/forêt mixte épicéa-pin), stations tourbeuses-humides et de montagne, août-octobre. Pied bleu (lepista) : litière de forêt de feuillus/mixte riche en nutriments, haies, tas de compost, très tard dans la saison jusqu'après les premières gelées.$q1$,$q1$Décisif : Lepista nuda = sporée rose-blanchâtre pâle/rose crème. Cortinarius rubellus = sporée brun rouille. Une empreinte brun rouille exclut Lepista nuda avec certitude.$q1$,$q1$TOUJOURS prendre une sporée (chapeau posé une nuit sur du papier blanc). Rose-blanchâtre pâle = possiblement Lepista nuda. Brun rouille OU un voile arachnéen (cortine) sur le jeune champignon = STOP, cortinaire — ne jamais manger. L'intoxication par l'orellanine ne se manifeste qu'après 3-14 jours, alors le rein est déjà irréversiblement endommagé. Au moindre doute, ne pas manger.$q1$,array[$q1$Sporée (test de séparation le plus sûr) : Lepista nuda rose-blanchâtre pâle/rose crème — TOUT cortinaire a une sporée BRUN ROUILLE. Une empreinte brun rouille exclut le pied bleu avec certitude.$q1$,$q1$Cortine/voile : le cortinaire a, à l'état jeune, un voile arachnéen (cortine) entre la marge du chapeau et le pied ; les restes de voile sur le pied se colorent en brun rouille. Le pied bleu n'a JAMAIS de voile — aucun velum.$q1$,$q1$Forme/couleur du chapeau : Cortinarius rubellus orange rouille à orange cannelle/roux avec un sommet pointu et mamelonné ; Lepista nuda jeune entièrement violet, chapeau bombé sans mamelon pointu.$q1$,$q1$Couleur des lamelles : le pied bleu violet/violet-rose et restant clair ; le cortinaire brun cannelle/rouille, espacé, échancré-adné.$q1$,$q1$Habitat : le cortinaire auprès des conifères (épicéa) sur sol acide, souvent tourbeux-humide en montagne ; le pied bleu dans la litière de forêt de feuillus/mixte riche en nutriments, haies, tas de compost, tard dans la saison jusqu'après le gel.$q1$]::text[],true),
($q1$lycoperdon_perlatum$q1$,$q1$amanita_phalloides$q1$,$q1$fr$q1$,$q1$De l'extérieur, un œuf d'amanite phalloïde blanc et fermé peut superficiellement ressembler à une jeune vesse-de-loup blanche. Distinction sûre seulement à la coupe longitudinale : masse blanche homogène (vesse-de-loup) vs champignon préformé avec silhouette de lamelles/pied et volve (amanite).$q1$,$q1$La jeune vesse-de-loup est inodore à odeur fongique douce. La jeune amanite phalloïde est presque inodore, ne devenant que tardivement sucrée-mielleuse à cadavérique. L'odeur n'est PAS un critère fiable au stade critique de l'œuf.$q1$,$q1$A. phalloides est un champignon mycorhizien surtout du chêne et du hêtre (aussi du châtaignier), préférant les sols acides ; la vesse-de-loup est saprotrophe et ubiquiste dans tous les types de forêts, prairies et jardins. Les stations se recoupent souvent → le lieu n'aide PAS à la distinction, seul le test de la coupe est sûr.$q1$,$q1$Chez la vesse-de-loup, une sporée brun jaune à brun olive mûrit à l'intérieur (le champignon n'est alors plus comestible). A. phalloides a une sporée blanche — non vérifiable au stade de l'œuf, donc sans intérêt pour le cueilleur.$q1$,$q1$Halver entièrement CHAQUE vesse-de-loup sphérique dans le sens de la longueur avant de la consommer et examiner l'image de la coupe. Ne manger que si l'intérieur est ENTIÈREMENT blanc pur et homogène — sans la moindre ombre de lamelles, de pied ou de chapeau. Un seul contour de champignon reconnaissable signifie une intoxication mortelle par amatoxines (insuffisance hépatique). En cas de doute, s'adresser à un poste de contrôle des champignons (VAPKO).$q1$,array[$q1$COUPE LONGITUDINALE (le test décisif) : chez la vesse-de-loup, l'intérieur est une masse parfaitement uniforme, blanc pur, de type guimauve, SANS aucune structure. Dans le jeune œuf d'amanite phalloïde, on voit déjà à la coupe le champignon préformé — les lamelles ébauchées et le pied comme silhouette/ombre plus foncée. Le moindre départ de lamelle ou de pied reconnaissable = jeter.$q1$,$q1$Base du pied/volve : la jeune amanite est enfermée dans un voile général membraneux blanc (velum) et possède à la base un bulbe/une volve lobée et membraneuse. La vesse-de-loup n'a pas de volve, pas de pied distinct ni de voile de ce type — elle est implantée dans le sol par une courte base stérile.$q1$,$q1$Peau externe : la vesse-de-loup perlée porte de fines verrues/aiguillons effaçables qui laissent un motif en réseau, et est blanche à l'intérieur. L'œuf d'amanite est lisse-membraneux et blanc à l'extérieur.$q1$,$q1$La maturation modifie la vesse-de-loup : dès que l'intérieur devient jaunâtre/olivâtre/brunâtre (formation des spores), elle n'est plus comestible — la chair de l'amanite reste blanche à la coupe et montre la silhouette du champignon.$q1$]::text[],true),
($q1$lycoperdon_perlatum$q1$,$q1$amanita_verna$q1$,$q1$fr$q1$,$q1$Extérieurement très semblable à la jeune vesse-de-loup blanche (œuf blanc-membraneux pur) ; distinction sûre uniquement en coupe transversale par la structure ébauchée du champignon (lamelles+pied) et la volve marquée — pas par la forme extérieure.$q1$,$q1$A. verna jeune inodore à faible ; sucrée-désagréable avec l'âge. Pas de critère de distinction fiable au stade de l'œuf.$q1$,$q1$A. verna apparaît surtout au printemps/début de l'été (forêts de feuillus, sols plutôt calcaires/chauds) ; les vesses-de-loup apparaissent plutôt de l'été à l'automne et sont ubiquistes. La saison/la station sont des indices, mais PAS un substitut fiable au test de la coupe.$q1$,$q1$A. verna : sporée blanche. Vesse-de-loup : sporée brun jaune/olive à maturité (alors plus comestible). Non vérifiable au stade de l'œuf, donc sans intérêt pour la détermination.$q1$,$q1$Ici aussi : halver chaque trouvaille blanche sphérique — ne manger que si l'intérieur est entièrement homogène et blanc, sans silhouette de lamelles/pied et sans volve. Un champignon ébauché à la coupe signifie une intoxication mortelle par amatoxines. Poste de contrôle (VAPKO) à la moindre incertitude.$q1$,array[$q1$Comme toutes les amanites phalloïdes blanches (section Phalloideae), A. verna est sphérique au stade jeune de l'œuf enveloppé du velum blanc et peut être confondue avec les vesses-de-loup blanches. La COUPE LONGITUDINALE décide : masse blanche homogène (vesse-de-loup) vs lamelles + pied préformés dans l'œuf (amanite).$q1$,$q1$Base du pied : A. verna montre à la base une gaine (volve) nettement marquée, lobée, en sac-membraneuse — chez la vesse-de-loup, toute volve fait défaut.$q1$,$q1$Les lamelles restent blanches à blanc crème (même à maturité) — ébauchées dans l'œuf comme silhouette claire à la coupe ; la vesse-de-loup n'a jamais de départs de lamelles.$q1$,$q1$Extérieur blanc-membraneux pur (amanite) vs finement verruqueux/aiguillonné avec des verrues effaçables (vesse-de-loup perlée).$q1$]::text[],true),
($q1$lycoperdon_perlatum$q1$,$q1$gemeiner-fliegenpilz-var-alba$q1$,$q1$fr$q1$,$q1$Vu de dessus / de l'extérieur, à peine distinguable de la jeune vesse-de-loup blanche, car A. virosa est entièrement blanc pur. Distinction sûre seulement en coupe : champignon préformé blanc avec lamelles serrées + volve (Amanita) versus masse blanche homogène (vesse-de-loup).$q1$,$q1$Un A. virosa plus âgé dégage une odeur désagréable, douceâtre et écœurante ; mais le jeune œuf reste discret. L'odeur n'est pas fiable au stade critique de l'œuf.$q1$,$q1$A. virosa pousse surtout dans les forêts de conifères / mixtes humides (acides), en mycorhize de préférence avec l'épicéa (des trouvailles sont aussi documentées sous le hêtre / le chêne / le bouleau), souvent en altitude / en zones montagnardes — écologiquement parfois différent de la vesse-de-loup saprotrophe ubiquiste, mais la station n'est PAS un critère sûr.$q1$,$q1$A. virosa : sporée blanche. Chez la vesse-de-loup, la sporée mûrit en brun-jaune / brun-olive (= alors plus comestible). Au stade de l'œuf, non vérifiable, donc sans pertinence pour la détermination.$q1$,$q1$Comme l'œuf de l'amanite vireuse blanche est blanc pur et ressemble particulièrement à une vesse-de-loup blanche, la règle est d'autant plus stricte : couper entièrement en deux, et ne consommer QUE si la chair intérieure est absolument homogène et blanche, sans la moindre silhouette de lamelles ou de pied et sans volve. Toute esquisse de champignon = danger de mort (amatoxines, insuffisance hépatique). En cas de doute, s'adresser au contrôle officiel des champignons (VAPKO).$q1$,array[$q1$Les jeunes stades d'Amanita virosa sont expressément signalés dans les bases de données mycologiques / toxicologiques comme étant confondus avec des bovistes et des vesses-de-loup. Décisive est la COUPE LONGITUDINALE : vesse-de-loup = masse homogène entièrement blanche ; œuf d'Amanita = lamelles (blanches, serrées) déjà ébauchées et pied reconnaissable en silhouette.$q1$,$q1$Base du pied : A. virosa possède une gaine blanche membraneuse et lobée (volve) à la base. La vesse-de-loup n'a ni volve ni pied distinct.$q1$,$q1$Contour extérieur : l'œuf de virosa est blanc pur et lisse-membraneux ; la vesse-de-loup perlée porte de fines verrues / épines effaçables.$q1$,$q1$Comme A. virosa est entièrement blanc (chapeau, lamelles, pied restent blancs), l'indice de couleur est inutilisable — seules l'image de coupe et la volve permettent une distinction sûre.$q1$]::text[],true),
($q1$marasmius_oreades$q1$,$q1$clitocybe_dealbata$q1$,$q1$fr$q1$,$q1$Clitocybe blanc (clitocybe du bord des routes) : chapeau plus petit, blanc plombé crayeux à jaune crème, souvent déprimé, avec des lamelles serrées et décurrentes. Marasme des Oréades (faux mousseron) : chapeau brun-jaune cuir avec un mamelon, lamelles espacées, pied nettement plus coriace.$q1$,$q1$Le marasme des Oréades a une odeur agréable et épicée (clou de girofle / amande amère) — non perceptible par ~25 % des gens pour des raisons génétiques, donc pas un critère à lui seul. Le clitocybe blanc a une odeur farineuse à inodore.$q1$,$q1$Comme C. rivulosa, c'est un champignon typique des prairies / pelouses, sur les endroits herbeux, éventuellement en ronds de sorcière — exactement dans l'habitat du marasme des Oréades. La station ne convient pas à la distinction.$q1$,$q1$Tous deux ont une sporée BLANCHE — aucun critère de distinction. Restent décisifs la disposition des lamelles et le pied coriace.$q1$,$q1$La muscarine agit déjà à petites doses (sueurs, salivation, larmoiement après 15-30 min). Ne jamais récolter lorsque les lamelles sont serrées et décurrentes le long du pied — le marasme des Oréades comestible a TOUJOURS des lamelles espacées et non décurrentes, ainsi qu'un pied coriace et flexible. L'odeur de clou de girofle n'est qu'une confirmation complémentaire.$q1$,array[$q1$Lamelles : clitocybe blanc serrées, adnées à brièvement DÉCURRENTES le long du pied — marasme des Oréades très espacées, attachées de façon échancrée, NON décurrentes$q1$,$q1$Chapeau : clitocybe blanc, blanc plombé crayeux à jaune crème, lisse / pruineux, plan à déprimé — marasme des Oréades couleur cuir avec un mamelon obtus, hygrophane$q1$,$q1$Pied : marasme des Oréades coriace-flexible, cartilagineux-fibreux — clitocybe blanc plus fibreux et plus cassant$q1$,$q1$Test de revivification : le marasme des Oréades reprend vie après séchage — le clitocybe blanc non$q1$]::text[],true),
($q1$marasmius_oreades$q1$,$q1$clitocybe_rivulosa$q1$,$q1$fr$q1$,$q1$Marasme des Oréades (faux mousseron) : chapeau brunâtre-jaune avec un mamelon obtus, lamelles pâles espacées, pied coriace et flexible. Clitocybe vénéneux : chapeau blanc plombé à gris crème, souvent déprimé / en entonnoir, lamelles serrées et décurrentes.$q1$,$q1$Marasme des Oréades : agréablement épicé, odeur de clou de girofle / amande amère (note d'acide cyanhydrique) — ATTENTION : ~25 % des gens ne peuvent PAS percevoir cette odeur pour des raisons génétiques, donc ce n'est pas un critère à lui seul. Clitocybe vénéneux : farineux à inodore. N'utiliser l'odeur que comme confirmation complémentaire, jamais comme seule preuve de sécurité.$q1$,$q1$Tous deux poussent au MÊME endroit : prairies, pâturages, pelouses de jardins / parcs, et tous deux forment des ronds de sorcière — aucune séparation possible par la station. Cela augmente massivement le risque de confusion.$q1$,$q1$Tous deux ont une sporée BLANCHE — la sporulation ne sépare PAS ces deux-là. Restent décisifs la disposition des lamelles (décurrentes versus espacées / échancrées) et le pied coriace.$q1$,$q1$Règle d'or dans la prairie : examiner les lamelles. Le marasme des Oréades a des lamelles TRÈS espacées, NON décurrentes, et un pied coriace et flexible. Si les lamelles sont serrées et décurrentes le long du pied — laisser sur place (suspicion de clitocybe vénéneux contenant de la muscarine). L'odeur épicée de clou de girofle n'est qu'une confirmation complémentaire (un quart des gens ne la sentent pas).$q1$,array[$q1$Lamelles (LE critère principal) : le clitocybe vénéneux a des lamelles serrées, brièvement DÉCURRENTES le long du pied — le marasme des Oréades a des lamelles ESPACÉES (largement), attachées de façon échancrée au pied, NON décurrentes$q1$,$q1$Pied : le pied du marasme des Oréades est coriace, flexible, cartilagineux-fibreux (il se tord sans casser) — le pied du clitocybe est cassant$q1$,$q1$Chapeau : clitocybe blanc plombé / gris crème, hygrophane, souvent déprimé / en entonnoir — marasme des Oréades brun-jaune cuir avec un mamelon obtus$q1$,$q1$Test de revivification : les carpophores du marasme des Oréades reprennent vie après séchage (typique des marasmes) — le clitocybe vénéneux non$q1$]::text[],true),
($q1$marasmius_oreades$q1$,$q1$inocybe_erubescens$q1$,$q1$fr$q1$,$q1$Inocybe (de Patouillard) : chapeau conique mamelonné, fendillé radialement, blanchâtre et virant au rouge brique avec le temps / la pression, lamelles se ternissant (gris rosé-brunâtre). Marasme des Oréades : chapeau lisse couleur cuir avec un mamelon obtus, lamelles espacées restant pâles.$q1$,$q1$Marasme des Oréades : agréablement épicé (clou de girofle / amande amère ; non perceptible par ~25 % des gens). Inocybe rouge brique : faiblement fruité, désagréablement douceâtre-spermatique avec l'âge. L'odeur seulement en complément, jamais seule.$q1$,$q1$L'inocybe rouge brique pousse de préférence sur sol calcaire, surtout dans les forêts de feuillus / mixtes, les parcs et sous les buissons (mycorhize avec le hêtre / le tilleul), parfois aussi sur des pelouses — pas principalement en prairie ouverte comme le marasme des Oréades. La station aide, mais n'est PAS un critère de sécurité à lui seul (possible aussi sur pelouse / gazon de parc).$q1$,$q1$DÉCISIF et vital : l'inocybe a une sporée brun foncé — le marasme des Oréades une sporée blanche. Une sporulation sépare les deux de façon univoque.$q1$,$q1$Le contrôle de la sporée comme sauveur de vie : blanc = marasme des Oréades possible, brun = NE JAMAIS manger. En outre, démasquent l'inocybe mortel : chapeau fendillé-radialement fibreux, virage au rouge brique (à la pression) et l'odeur spermatique. Muscarine — dose mortelle dès ~40-500 g de champignon frais.$q1$,array[$q1$Sporée (DÉCISIF) : l'inocybe a une sporée BRUN FONCÉ, les lamelles passent du blanc / crème au gris-olive rosé puis au brunâtre tacheté — le marasme des Oréades a une sporée BLANCHE et des lamelles restant pâles$q1$,$q1$Rougissement : l'inocybe rougit au rouge brique (chapeau / pied / chair, surtout à la pression et avec l'âge) — le marasme des Oréades ne rougit PAS$q1$,$q1$Surface du chapeau : l'inocybe conique-mamelonné, radialement fibreux et se fendillant / fissurant ('Risspilz', inocybe) — le marasme des Oréades lisse, hygrophane, avec un mamelon obtus$q1$,$q1$Odeur : l'inocybe spermatique / fruité-désagréable — le marasme des Oréades épicé, de clou de girofle / amande amère$q1$]::text[],true),
($q1$marone$q1$,$q1$flockenstieliger_hexenpilz$q1$,$q1$fr$q1$,$q1$Bolet bai : brun, léger bleuissement. Bolet à pied rouge (bolet Satan flocculeux / bolet à beau pied) : brun, bleuissement fort et rapide, points rouges.$q1$,null,$q1$Tous deux en forêt$q1$,null,$q1$Tous deux comestibles. Le bolet à pied rouge DOIT être cuit 15+ min.$q1$,array[$q1$Tous deux comestibles, le bolet à pied rouge bleuit PLUS VITE$q1$,$q1$Le bolet à pied rouge a de petits points rouges sur le pied$q1$]::text[],true),
($q1$parasol$q1$,$q1$amanita_pantherina$q1$,$q1$fr$q1$,$q1$Lépiote élevée (parasol) : chapeau brun clair, pied chiné (motif de peau de serpent). Amanite panthère : brune avec des flocons blancs, pied blanc à bulbe.$q1$,$q1$Lépiote élevée (parasol) : odeur de noisette agréable. Amanite panthère : odeur de radis (raifort).$q1$,$q1$Lépiote élevée (parasol) : prairies, lisières de forêt. Amanite panthère : forêt de feuillus.$q1$,$q1$Les deux : blanc.$q1$,$q1$Test PARASOL : anneau mobile (coulissant), pied chiné. En présence de flocons, NE JAMAIS consommer.$q1$,array[$q1$Anneau de la lépiote élevée (parasol) MOBILE, anneau de l'amanite panthère fixe$q1$,$q1$Lépiote élevée (parasol) à pied chiné, amanite panthère à pied blanc et lisse$q1$,$q1$L'amanite panthère possède un bulbe à 2-3 bourrelets$q1$]::text[],true),
($q1$parasol$q1$,$q1$chlorophyllum_brunneum$q1$,$q1$fr$q1$,$q1$Chinure du pied (présente chez la lépiote élevée/parasol) + rougissement (présent chez la lépiote vénéneuse/Chlorophyllum) + bulbe.$q1$,$q1$Les deux : odeur non spécifique.$q1$,$q1$Lépiote élevée (parasol) : forêt/prairie ; lépiote vénéneuse (Chlorophyllum) : souvent compost/jardin.$q1$,$q1$Les deux : blanc-crème.$q1$,$q1$Poison gastro-intestinal. Pied chiné + pas de rougissement = lépiote élevée (parasol) ; pied lisse + coloration rouge safran = on n'y touche pas.$q1$,array[$q1$Lépiote élevée (parasol) : pied chiné (motif de peau de serpent), double anneau coulissant, chair qui NE rougit PAS$q1$,$q1$Lépiote vénéneuse (Chlorophyllum) : pied lisse, bulbe marginé, chair/lamelles se colorant en rouge safran$q1$]::text[],true),
($q1$morchella_elata$q1$,$q1$fliegenpilz-grosspilz$q1$,$q1$fr$q1$,$q1$Morille à structure alvéolée/régulière vs. gyromitre à aspect cérébriforme/irrégulier.$q1$,$q1$Les deux : odeur non spécifique.$q1$,$q1$Les deux : au printemps, zones brûlées/forêt alluviale/forêt de conifères.$q1$,$q1$Pas de sporée de lamelles (ascomycètes).$q1$,$q1$La gyromitre (gyromitre printanier) est hautement toxique (potentiellement mortelle). Coupe longitudinale : entièrement creux (morille) vs. ouaté-cloisonné (gyromitre).$q1$,array[$q1$Morille conique (Morchella elata) : chapeau alvéolé-creusé, chapeau + pied entièrement creux$q1$,$q1$Gyromitre printanier : forme cérébriforme contournée, pied cloisonné (non creux), gyromitrine (hautement toxique)$q1$]::text[],true),
($q1$roetling$q1$,$q1$agaricus_xanthodermus$q1$,$q1$fr$q1$,$q1$Agaric jaunissant (agaric à odeur de phénol) : chapeau blanc à blanc crayeux, jeune globuleux/hémisphérique, puis aplati, lisse à finement squamuleux ; base du pied virant IMMÉDIATEMENT au jaune chrome vif en coupe longitudinale. Agaric des moutons : chapeau blanc crème, soyeux-fibrilleux à légèrement squamuleux, convexe à plan ; jaunit faiblement sur l'ensemble du champignon, sans la tache jaune chrome concentrée à la base du pied.$q1$,$q1$Caractère décisif : l'agaric des moutons sent agréablement l'anis/le massepain. L'agaric jaunissant (à odeur de phénol) sent désagréablement l'encre/le phénol (odeur médicinale-iodée) ; l'odeur se renforce au froissement de la base du pied et surtout à la chauffe/cuisson.$q1$,$q1$Agaric jaunissant (à odeur de phénol) : jardins, parcs, lisières de forêt, tas de compost, terrains rudéraux/proches des habitations. Agaric des moutons : prairies et pâturages fumés, surtout pâturages à moutons et à chevaux. L'habitat seul ne permet PAS de distinguer sûrement (recoupement possible).$q1$,$q1$Chez les deux espèces : brun chocolat foncé à brun pourpre (genre Agaricus) - PAS un critère de distinction.$q1$,$q1$Couper la base du pied dans le sens de la longueur : si elle vire aussitôt à un jaune chrome intense ET que le champignon sent l'encre/le phénol au lieu de l'anis, le laisser sur place - agaric jaunissant (à odeur de phénol). Règle empirique : tout agaric à odeur de phénol/d'encre ou à base du pied jaune chrome vif = toxique, ne pas consommer.$q1$,array[$q1$L'odeur est le critère le plus important : agaric des moutons agréablement anisé/massepain ; agaric jaunissant (à odeur de phénol) désagréablement encre/phénol - renforcé au froissement de la base du pied et à la chauffe.$q1$,$q1$Couper la base du pied dans le sens de la longueur : l'agaric jaunissant (à odeur de phénol) vire IMMÉDIATEMENT au jaune chrome intense, concentré à la base du pied ; l'agaric des moutons jaunit faiblement sur tout le carpophore et pas de façon concentrée à la base du pied.$q1$,$q1$Les deux ont un anneau et des lamelles qui mûrissent du rose pâle au brun chocolat, et les deux ont une sporée brun foncé - seuls la coupe de la base du pied (jaune chrome) ET le test olfactif distinguent de façon sûre, et non les lamelles ou la couleur de la sporée.$q1$]::text[],true),
($q1$roetling$q1$,$q1$amanita_phalloides$q1$,$q1$fr$q1$,$q1$Amanite phalloïde (amanite verte) : chapeau vert olive/vert jaunâtre avec des fibrilles radiales incrustées (la forme blanche var. alba également entièrement blanche), lamelles BLANC PUR, base du pied bulbeuse avec une volve membraneuse. Agaric des moutons : chapeau blanc crème, lamelles roses -> brun chocolat, PAS de volve membraneuse.$q1$,$q1$Agaric des moutons : odeur agréable d'anis/de massepain. Amanite phalloïde (amanite verte) : jeune, odeur douceâtre-mielleuse, désagréable avec l'âge - PAS d'anis.$q1$,$q1$Amanita phalloides : champignon mycorhizien surtout sous les chênes et les hêtres en forêt. Agaric des moutons : isolé sur prairies et pâturages, sans lien avec les arbres. L'habitat seul n'est PAS un critère fiable.$q1$,$q1$DÉCISIF : agaric des moutons brun chocolat foncé à brun pourpre ; Amanita phalloides BLANC PUR. Sporée blanche = ne jamais consommer.$q1$,$q1$Ne jamais récolter de 'champignons' blancs jeunes, encore fermés, à lamelles claires - c'est précisément au stade bouton que la mortelle amanite phalloïde ressemble le plus à l'agaric. Déterrer entièrement la base du pied (volve présente ?) et considérer des lamelles blanc pur ainsi qu'une sporée blanche comme un signal d'arrêt absolu.$q1$,array[$q1$Lamelles : l'amanite phalloïde (amanite verte) a toujours des lamelles BLANC PUR ; les lamelles de l'agaric sont jeunes rose pâle (les très jeunes boutons exceptionnellement blanc crème) et mûrissent en passant par le gris-rose jusqu'au brun chocolat. Au stade bouton, ne pas se fier à la seule couleur des lamelles - alors la volve + la sporée sont impératives.$q1$,$q1$Base du pied : bulbe nettement détaché avec volve membraneuse chez l'amanite phalloïde ; chez l'agaric, la volve est absente. Toujours déterrer entièrement la base du pied.$q1$,$q1$Ne PAS utiliser la couleur du chapeau comme critère principal : typiquement vert olive/vert jaunâtre, mais aussi entièrement blanc en var. alba - donc toujours vérifier lamelles + volve + sporée, jamais la seule couleur.$q1$,$q1$Sporée blanche (agaric brun foncé) - le critère isolé le plus fiable.$q1$]::text[],true),
($q1$roetling$q1$,$q1$amanita_verna$q1$,$q1$fr$q1$,$q1$Amanite printanière (Amanita verna): chapeau d'un blanc pur, LAMELLES D'UN BLANC PUR (même à un âge avancé), base du pied munie d'une volve bulbeuse, membraneuse et en forme de sac, souvent enfoncée profondément dans la terre. Agaric des moutons (agaric champêtre): chapeau blanc crème, lamelles virant au rose -> gris-rose -> brun chocolat en mûrissant, PAS de volve, tout au plus une base du pied légèrement épaissie.$q1$,$q1$Agaric des moutons: odeur agréable d'anis / de massepain. Amanita verna: quasiment inodore à légèrement sucrée / mielleuse, désagréable à un âge avancé - PAS d'anis.$q1$,$q1$Amanita verna: champignon mycorhizien, pousse en forêt (forêt de feuillus / forêt mixte), surtout au printemps, en lien avec les arbres. Agaric des moutons: saprotrophe, sur les prairies et pâturages ouverts, sans lien avec les arbres. Attention: l'habitat seul n'est PAS un critère sûr.$q1$,$q1$DÉCISIF et fiable à 100 %: agaric des moutons brun chocolat foncé à brun pourpré; Amanita verna BLANC PUR. En cas de sporée blanche, ne JAMAIS consommer comme agaric.$q1$,$q1$Pour chaque 'agaric' blanc, TOUJOURS déterrer entièrement la base du pied et la dégager: si l'on trouve une volve bulbeuse et membraneuse (volve) OU si les lamelles restent d'un blanc pur - danger de mort, laisser sur place. En cas de doute, faire une sporée: blanc = amanite, ne jamais consommer. Les jeunes boutons blancs fermés, ne pas les récolter du tout.$q1$,array[$q1$Lamelles: Amanita verna a à TOUT âge des lamelles d'un blanc pur; l'agaric des moutons les a jeunes d'un rose pâle (les très jeunes boutons peuvent être blanc crème!), puis gris-rose à brun chocolat. IMPORTANT: au stade bouton, la couleur des lamelles seule n'est PAS sûre - vérifier alors impérativement la volve + la sporée.$q1$,$q1$Base du pied: Amanita verna a un bulbe nettement délimité avec une volve membraneuse en forme de sac (volve); l'agaric n'a PAS de volve. De plus, toujours déterrer entièrement la base du pied - la volve se trouve souvent profondément dans la terre.$q1$,$q1$Sporée: agaric brun foncé, Amanita verna d'un blanc pur - la sporée est le critère isolé le plus fiable.$q1$,$q1$Odeur: agaric des moutons à l'anis; Amanita verna sans odeur d'anis (neutre à sucrée-mielleuse) - l'absence d'odeur d'anis est un signal d'alerte, mais ne remplace JAMAIS la vérification de la volve / de la sporée.$q1$]::text[],true),
($q1$russula_cyanoxantha$q1$,$q1$amanita_phalloides$q1$,$q1$fr$q1$,$q1$Exemplaires violet-vert visuellement confondables; le test des lamelles (souples vs non) + la base du pied sont décisifs.$q1$,$q1$Russule douce.$q1$,$q1$Toutes deux en forêt de feuillus (hêtre / chêne).$q1$,$q1$Toutes deux blanches.$q1$,$q1$MORTEL. Dégager la base du pied: tout bulbe muni d'une gaine membraneuse = danger de mort.$q1$,array[$q1$Russule charbonnière: lamelles souples et lardacées (ne se brisent pas en éclats), PAS d'anneau, PAS de volve.$q1$,$q1$Amanite phalloïde: anneau + volve, amatoxines mortelles.$q1$]::text[],true),
($q1$russula_vesca$q1$,$q1$amanita_phalloides$q1$,$q1$fr$q1$,$q1$Décisif et impératif est la base du pied: chez A. phalloides une volve blanche membraneuse autour d'une base bulbeuse plus un anneau pendant et strié; lamelles libres et molles. R. vesca a une base du pied s'amincissant droit, sans bulbe ni anneau, et des lamelles cassantes et fragiles, adnées. La couleur n'est PAS un critère fiable: phalloides est le plus souvent vert olive / vert jaunâtre (aussi blanche en var. alba); la couleur rouge chair de vesca n'est tout au plus qu'un indice. La confusion classique de couleur de l'amanite phalloïde se fait avec les russules comestibles VERTES, et non avec le rouge vesca - c'est pourquoi il faut toujours s'assurer morphologiquement à la base du pied.$q1$,$q1$L'amanite phalloïde âgée sent le sucré, le miel artificiel, jusqu'au désagréable; la russule comestible a une odeur douce / discrète. L'odeur n'est QU'un indice, jamais le critère de sécurité.$q1$,$q1$Toutes deux champignons mycorhiziens sous feuillus (chêne, hêtre, châtaignier) - le lieu ne les distingue PAS de manière fiable, d'où la vérification morphologique impérative à la base du pied.$q1$,$q1$Toutes deux blanches - la sporée ne DISTINGUE PAS ces espèces et ne doit pas servir à donner le feu vert.$q1$,$q1$TOUJOURS déterrer le champignon entièrement avec la base du pied (ne pas couper!) et vérifier la présence de bulbe + volve blanche membraneuse + anneau. Si l'on trouve une volve / un bulbe / un anneau, ou si les lamelles sont molles et libres, ce n'est PAS une russule - ne pas appliquer la règle des russules / le test gustatif, car les amatoxines ont un goût DOUX et sont mortelles. La couleur n'est jamais le critère. En Suisse: au moindre doute, se rendre au contrôle officiel des champignons VAPKO.$q1$,array[$q1$Bulbe / volve à la base du pied: A. phalloides a TOUJOURS une gaine blanche membraneuse en forme de sac (volve) autour d'un bulbe net - les russules n'ont JAMAIS de volve ni de bulbe. C'est le critère impératif, la couleur ne l'est PAS.$q1$,$q1$Anneau du pied: A. phalloides porte un anneau pendant, membraneux et strié (manchette) sur le haut du pied - les russules sont sans anneau.$q1$,$q1$Lamelles: russule = lamelles cassantes, fragiles, qui se brisent en éclats, adnées au pied (sporés fragiles); A. phalloides = lamelles molles, souples, LIBRES (non adnées au pied). Le test gustatif échoue ici, car les amatoxines ont un goût DOUX / de noisette!$q1$,$q1$Couleur du chapeau comme indice faible: A. phalloides est blanc-vert / vert / olive / vert jaunâtre (rarement blanche, var. alba) - la couleur rouge chair / rouge vineux de R. vesca n'y correspond PAS, mais ne remplace jamais la vérification de la base du pied. La confusion classique de couleur se fait avec les russules VERTES, et non avec la russule comestible rouge.$q1$]::text[],true),
($q1$russula_vesca$q1$,$q1$russula_emetica$q1$,$q1$fr$q1$,$q1$R. vesca: rouge chair à rouge vineux / brun rougeâtre mat, souvent décoloré et irrégulièrement taché, marge du chapeau avec une cuticule en retrait (trop courte), de sorte que les arêtes des lamelles dépassent en forme de petites dents. R. emetica: rouge cerise / rouge sang vif et uniforme, visqueux et brillant par temps humide, la cuticule couvre jusqu'à la marge et est largement séparable (souvent jusqu'au centre du chapeau).$q1$,$q1$Toutes deux largement discrètes / légèrement fruitées; l'odeur ne sépare PAS ces deux espèces. Le décisif est le goût (doux vs brûlant et âcre).$q1$,$q1$R. emetica: forêts marécageuses / acides humides et forêts de conifères (épicéa, pin, sapin blanc), souvent moussues. R. vesca: forêt de feuillus et forêt mixte sous hêtre et chêne, sols plutôt frais à secs.$q1$,$q1$Toutes deux blanches à blanchâtres - la sporée ne sépare PAS ces deux espèces. Ne pas l'utiliser pour la distinction.$q1$,$q1$Test gustatif selon la règle des russules: mâcher un petit morceau de chapeau avec lamelles, recracher, ne pas avaler - doux = russule comestible, âcre / brûlant = russule émétique (toxique, à jeter). La règle ne s'applique QUE si le champignon est reconnu sans aucun doute comme une russule (lamelles cassantes et fragiles qui se brisent en éclats, pas d'anneau au pied, pas de volve). R. emetica n'est pas mortelle, mais provoque des troubles gastro-intestinaux violents durant plusieurs jours.$q1$,array[$q1$Goût (règle des russules, le critère de distinction décisif): R. vesca est doux et agréablement noisette; R. emetica a immédiatement un goût brûlant, âcre / poivré. Mâcher brièvement un petit morceau de chapeau avec lamelles, NE PAS avaler, recracher entièrement - à n'appliquer que si le champignon est reconnu sans aucun doute comme une russule (lamelles cassantes, pas d'anneau, pas de volve).$q1$,$q1$Couleur du chapeau: R. vesca rouge chair / rouge vineux mat à brun rougeâtre, souvent taché et se décolorant; R. emetica rouge sang, rouge cerise à pourpre vif, collant et brillant par temps humide.$q1$,$q1$Cuticule raccourcie (caractère distinctif de R. vesca): la marge du chapeau est en retrait, de sorte que la chair du chapeau et les extrémités des lamelles dépassent la marge en forme de petites dents - absent chez R. emetica (la cuticule couvre jusqu'à la marge et se sépare largement, souvent jusqu'au centre du chapeau).$q1$,$q1$Station: R. emetica typiquement dans les forêts marécageuses et de conifères humides (épicéa, pin, sapin blanc, souvent moussues / acides); R. vesca surtout en forêt de feuillus / forêt mixte sous hêtre et chêne.$q1$]::text[],true),
($q1$russula_virescens$q1$,$q1$amanita_phalloides$q1$,$q1$fr$q1$,$q1$Coloration verte semblable, surtout jeune; la cuticule de la russule se craquelle en aréoles.$q1$,$q1$Russule douce / de noisette; amanite phalloïde mielleuse (à un âge avancé).$q1$,$q1$Toutes deux en forêt de feuillus.$q1$,$q1$Russule blanche, A. phalloides blanche.$q1$,$q1$MORTEL. Pour les champignons verts, TOUJOURS déterrer le champignon entier: l'anneau ET la volve sont-ils absents? Sinon, ne pas consommer.$q1$,array[$q1$Russule: lamelles cassantes et fragiles, PAS d'anneau, PAS de bulbe / volve.$q1$,$q1$Amanite phalloïde: anneau + volve membraneuse à la base bulbeuse, lamelles souples.$q1$]::text[],true),
($q1$schopftintling$q1$,$q1$amanita_phalloides$q1$,$q1$fr$q1$,$q1$Coprin chevelu: blanc-écailleux, ovoïde. Amanite phalloïde: vert olive, lisse.$q1$,null,$q1$Coprin chevelu: prairies, bords de chemin. Amanite phalloïde: forêt de feuillus.$q1$,$q1$Coprin chevelu: noire. Amanite phalloïde: blanche.$q1$,$q1$Les lamelles du coprin chevelu noircissent, celles de l'amanite phalloïde JAMAIS.$q1$,array[$q1$Coprin chevelu: chapeau ovoïde écailleux; amanite phalloïde lisse$q1$,$q1$Coprin chevelu dans les prairies, amanite phalloïde en forêt$q1$]::text[],true),
($q1$semmelstoppelpilz$q1$,$q1$austernpilz$q1$,$q1$fr$q1$,$q1$Pied-de-mouton sur le sol en forêt mixte. Pleurote en huître sur un tronc d'arbre.$q1$,null,$q1$Sol vs arbre$q1$,null,$q1$Tous deux adaptés aux débutants.$q1$,array[$q1$Le pied-de-mouton a des AIGUILLONS, le pleurote en huître des LAMELLES$q1$,$q1$Sol vs tronc d'arbre$q1$]::text[],true),
($q1$steinpilz$q1$,$q1$butterpilz$q1$,$q1$fr$q1$,$q1$Le cèpe a un pied à réseau blanc, sans anneau. Le bolet jaune a un chapeau visqueux et un anneau.$q1$,null,$q1$Tous deux en forêt de conifères, le bolet jaune sous le pin sylvestre.$q1$,null,$q1$Peler la cuticule du chapeau du bolet jaune.$q1$,array[$q1$Cèpe: pied lisse; bolet jaune: anneau + chapeau visqueux$q1$]::text[],true),
($q1$steinpilz$q1$,$q1$tylopilus_felleus$q1$,$q1$fr$q1$,$q1$Couleur des tubes (blanc/jaune vs rose) + réseau (fin et blanc vs grossier et foncé).$q1$,$q1$Le bolet amer (Tylopilus felleus) est extrêmement amer (en goûter une toute petite quantité, puis recracher).$q1$,$q1$Tous deux dans les forêts acides de conifères ou mixtes, souvent ensemble.$q1$,$q1$Cèpe: olive; bolet amer: rose.$q1$,$q1$Pas toxique, mais un seul bolet amer gâte tout un plat. Les tubes roses + le réseau grossier + l'amertume le démasquent.$q1$,array[$q1$Cèpe: réseau fin et blanc, tubes blancs/jaunes, doux$q1$,$q1$Bolet amer: réseau grossier et foncé, tubes roses, extrêmement amer$q1$]::text[],true),
($q1$zigeunerpilz$q1$,$q1$cortinarius_orellanus$q1$,$q1$fr$q1$,$q1$Rozite ridé (Cortinarius caperatus): chapeau jaune paille à brun jaunâtre, pruineux gris-blanchâtre-lilas, ridé longitudinalement, avec un anneau membraneux à double bord. Cortinaire des montagnes (Cortinarius orellanus): chapeau d'un orange soutenu à brun cuivré/rouille, mat-fibrilleux à finement écailleux, sec, SANS pruine; PAS de véritable anneau, seulement une cortine fugace; pied cylindrique, de même couleur ou jaunâtre, non nettement chiné/guirlandé (contrairement à rubellus).$q1$,$q1$Rozite ridé: doux. Cortinaire des montagnes: légèrement raveline (odeur de radis).$q1$,$q1$Rozite ridé: forêts de conifères et (rarement) de feuillus, souvent sur sol acide et sableux, près des myrtilles. Cortinaire des montagnes: forêts de feuillus thermophiles près des chênes, hêtres, noisetiers, châtaigniers, sur sols acides à basiques (juillet-octobre) — typiquement pas en forêt de conifères.$q1$,$q1$Rozite ridé: brun cannelle clair/jaune rouille. Cortinaire des montagnes: brun rouille. Aucun caractère unique permettant de les distinguer de façon fiable.$q1$,$q1$Ne consommer le rozite ridé qu'avec un anneau ferme et net à double bord. Un chapeau d'un orange/brun rouille soutenu, sec et fibrilleux, SANS pruine et sans véritable anneau (seulement des fibres de voile), indique le mortel cortinaire des montagnes — n'y touchez pas, direction le contrôle des champignons (VAPKO).$q1$,array[$q1$Le rozite ridé possède un anneau membraneux ferme à double bord sur le pied; le cortinaire des montagnes n'a PAS de véritable anneau, seulement des fibres de voile fugaces (cortine).$q1$,$q1$Le chapeau du rozite ridé est pruineux gris-lilas et ridé; le chapeau du cortinaire des montagnes est sec, fibrilleux à finement écailleux et d'un orange/cuivre/brun rouille uniforme et soutenu, sans pruine.$q1$,$q1$Le pied du cortinaire des montagnes est de même couleur à jaunâtre et non nettement chiné; le pied du rozite ridé porte la manchette membraneuse à double bord.$q1$,$q1$Le poison orellanine résiste à la chaleur et au séchage et provoque, après une latence de plusieurs jours à plusieurs semaines (3-14 jours), une insuffisance rénale mortelle — aucun test gustatif et aucune détoxification par la cuisson ne sont possibles.$q1$]::text[],true),
($q1$zigeunerpilz$q1$,$q1$cortinarius_rubellus$q1$,$q1$fr$q1$,$q1$Pholiote ridée (Reifpilz / Zigeunerpilz) : chapeau jaune paille à brun jaunâtre avec une pruine gris-blanchâtre-lilas (voile), surface caractéristiquement ridée/sillonnée dans le sens de la longueur, anneau membraneux net sur le pied avec un double bord. Cortinaire des montagnes (Cortinarius rubellus) : chapeau sec et finement feutré, jaune à orangé ou brun cannelle roussâtre, à mamelon pointu (ou arrondi), AUCUN véritable anneau (seulement des restes fugaces de cortine/voile), pied élancé et chiné de jaune (ceintures jaunes de voile).$q1$,$q1$Pholiote ridée (Reifpilz) : agréable/doux. Cortinaire à mamelon pointu (Cortinarius rubellus) : faiblement raphanoïde (odeur de radis).$q1$,$q1$Pholiote ridée (Reifpilz) : forêts de conifères et (rarement) de feuillus, volontiers auprès de la myrtille sur sol acide et sableux, août à octobre. Cortinaire à mamelon pointu (Cortinarius rubellus) : surtout forêt de conifères (peuplements d'épicéas), souvent dans des stations humides/marécageuses sur sols acides, auprès de la myrtille — le chevauchement d'habitat aggrave le risque.$q1$,$q1$Pholiote ridée (Reifpilz) : brun cannelle clair à jaune rouille. Cortinarius rubellus : brun rouille. La couleur des spores ne permet PAS de les distinguer de manière fiable ici — ne jamais l'utiliser comme unique critère.$q1$,$q1$Cherche sur le pied l'anneau membraneux ferme au DOUBLE bord caractéristique — si cet anneau manque et que le pied est au contraire chiné de jaune avec seulement de fugaces fibres de voile, ce n'est pas une pholiote ridée, mais peut-être le mortel cortinaire (Raukopf). En cas de doute, à l'état jeune, TOUJOURS s'adresser à un organe de contrôle des champignons (VAPKO).$q1$,array[$q1$La pholiote ridée (Reifpilz) possède un anneau membraneux ferme sur le pied, au DOUBLE bord caractéristique ; le cortinaire à mamelon pointu (Cortinarius rubellus) n'a AUCUN véritable anneau, seulement de fugaces fibres de voile (cortine).$q1$,$q1$Le chapeau de la pholiote ridée (Reifpilz) est mat, PRUINEUX gris-blanchâtre à lilas et ridé dans le sens de la longueur ; le cortinaire (Raukopf) a un chapeau sec, finement feutré-fibrilleux, brun cannelle roussâtre, avec un net mamelon POINTU.$q1$,$q1$Le pied du cortinaire (Raukopf) est élancé et CHINÉ de jaune (ceintures jaunes de voile) ; le pied de la pholiote ridée (Reifpilz) est plus épais et porte la manchette membraneuse au lieu de ceintures.$q1$,$q1$Ne consommer que si un anneau à double bord est présent sans ambiguïté ; le poison, l'orellanine, est stable à la chaleur et au séchage et provoque, après une latence de 2 à 21 jours, une insuffisance rénale irréversible — aucune cuisson/aucun séchage ne le détoxifie.$q1$]::text[],true),
($q1$agaricus_augustus$q1$,$q1$agaricus_xanthodermus$q1$,$q1$it$q1$,$q1$Odore + viraggio del colore alla base del gambo (anice vs. carbolico; debolmente giallo vs. giallo cromo).$q1$,$q1$Anice (commestibile) vs. carbolico/inchiostro (velenoso) — il criterio più importante$q1$,$q1$entrambi bosco/parco/giardino$q1$,$q1$entrambi marrone cioccolato$q1$,$q1$Incidere la base del gambo: giallo cromo intenso + odore carbolico = prataiolo giallo (velenoso). Negli agarici bianchi escludere inoltre la volva (Amanita phalloides).$q1$,array[$q1$Prataiolo gigante (Agaricus augustus): odore di anice/mandorla, ingiallimento debole$q1$,$q1$Prataiolo giallo (Agaricus xanthodermus): odore carbolico/di inchiostro (intensificato col calore), base del gambo giallo cromo$q1$]::text[],true),
($q1$agaricus_campestris$q1$,$q1$amanita_phalloides$q1$,$q1$it$q1$,$q1$Prataiolo: cappello bianco-beige, lamelle rosa che diventano marroni. Tignosa verdognola: cappello verde oliva, lamelle bianche che restano bianche.$q1$,$q1$Prataiolo: gradevole, fungino. Tignosa verdognola: debolmente dolciastro.$q1$,$q1$Prataiolo: prati, pascoli. Tignosa verdognola: bosco di latifoglie, querce.$q1$,$q1$Prataiolo: marrone scuro. Tignosa verdognola: bianco.$q1$,$q1$Controllare SEMPRE la base del gambo — bulbo in una volva membranosa = MAI mangiare!$q1$,array[$q1$Il prataiolo non ha MAI un bulbo nella volva, la tignosa verdognola sempre$q1$,$q1$Le lamelle del prataiolo diventano rosa e marrone cioccolato, quelle della tignosa verdognola restano bianche$q1$]::text[],true),
($q1$amanita_rubescens$q1$,$q1$amanita_pantherina$q1$,$q1$it$q1$,$q1$Decidono il test dell'arrossamento + l'anello (striato vs. liscio) + il bulbo.$q1$,$q1$quasi indistinguibili$q1$,$q1$entrambi in tutti i tipi di bosco$q1$,$q1$entrambi bianco$q1$,$q1$L'Amanita rubescens (tignosa vinata) solo per esperti. Verificare TUTTI i caratteri INSIEME (arrossamento + anello striato + bulbo senza guaina marginata).$q1$,array[$q1$Tignosa vinata (Amanita rubescens): la carne arrossa (soprattutto base del gambo/gallerie dei vermi), anello striato, fioccosità del velo grigia$q1$,$q1$Tignosa bigia (Amanita pantherina): la carne NON arrossa MAI, anello liscio, fioccosità bianca pura, base bulbosa marginata, tossine termostabili$q1$]::text[],true),
($q1$austernpilz$q1$,$q1$galerina_marginata$q1$,$q1$it$q1$,$q1$Gelone (Pleurotus ostreatus): cappello a forma di conchiglia/ventaglio di 5-25 cm, bianco/grigio/marrone, in cespi embricati a tegola; gambo laterale o assente; lamelle larghe biancastre decorrenti. Galerina marginata: piccolo cappellino convesso da ocra a marrone cannella di 1-4 cm con gambo centrale slanciato brunastro, zona anulare nel terzo superiore del gambo, da vecchio lamelle marrone cannella.$q1$,$q1$Gelone: mite, gradevolmente fungino-anisato. Galerina marginata: debolmente farinoso fino a impercettibile - l'odore NON è un carattere distintivo sicuro, quindi non affidarsi ad esso.$q1$,$q1$Entrambi su legno, ma: il gelone predilige legno di latifoglie (faggio/pioppo), in cespi a mensola, spesso in alto sul tronco; la Galerina marginata su legno morto marcescente (spesso conifere, ma anche latifoglie), piccola, da singola a fascicolata, piuttosto vicino al suolo/su tronchi distesi.$q1$,$q1$Gelone: BIANCO fino a grigio-lilla pallido. Galerina marginata: MARRONE RUGGINE/CANNELLA. Questo è il carattere singolo più affidabile - la sporata distingue i due con sicurezza.$q1$,$q1$Regola d'oro: un vero gelone sta lateralmente/senza gambo come una spessa mensola carnosa sul legno e dà una sporata BIANCA fino a grigio-lilla. Non appena è presente un gambo centrale con resto di anello OPPURE la sporata risulta marrone, NON è un gelone - allora giù le mani (la Galerina marginata contiene amatossine mortali, lo stesso veleno della tignosa verdognola). Nel dubbio fare sempre una sporata prima di mangiare.$q1$,array[$q1$Sporata: gelone bianca fino a grigio-lilla; Galerina marginata marrone ruggine/cannella (la sporata su carta scura + chiara è il carattere distintivo più sicuro).$q1$,$q1$Gambo: il gelone ha un gambo laterale/eccentrico, corto o quasi assente, e NESSUN anello; la Galerina marginata ha un gambo centrale, slanciato, con un resto membranoso di zona anulare nel terzo superiore.$q1$,$q1$Forma di crescita: il gelone cresce embricato a tegola in cespi/mensole spessi e carnosi direttamente sul legno; la Galerina marginata cresce piccola, da singola a fascicolata, con cappellino convesso a carne sottile su legno morto.$q1$,$q1$Lamelle: il gelone con lamelle larghe, biancastre, decorrenti sul gambo (laterale); la Galerina marginata con lamelle strette, da giovani di colore ocra pallido, che da vecchie virano al marrone cannella (per il sporo marrone).$q1$,$q1$Dimensione/consistenza: il gelone grande (cappello 5-25 cm), tenace-carnoso; la Galerina marginata piccola (cappello per lo più 1-4 cm), fragile, con un gambo distinto come un normale fungo a lamelle.$q1$]::text[],true),
($q1$calocybe_gambosa$q1$,$q1$inocybe_erubescens$q1$,$q1$it$q1$,$q1$Entrambi primaverili, chiari; l'inocibe (Inocybe erubescens) a fibre radiali/screpolato e arrossante, il prugnolo (Calocybe gambosa) liscio-carnoso.$q1$,$q1$Prugnolo fortemente farinoso-cetriolato; inocibe dolciastro-spermatico$q1$,$q1$entrambi prati/margini di bosco, su suolo calcareo, stessa stagione$q1$,$q1$Prugnolo bianco, inocibe marrone$q1$,$q1$MORTALE (muscarina). Lamelle bianche + odore farinoso + assenza di arrossamento sono obbligatori — altrimenti giù le mani.$q1$,array[$q1$Prugnolo (Calocybe gambosa): lamelle bianche a ogni età + odore farinoso, la carne NON arrossa$q1$,$q1$Inocibe (Inocybe erubescens): la carne arrossa, lamelle grigio-marroni, sporata marrone, alto contenuto di muscarina$q1$]::text[],true),
($q1$champignon-de-paris$q1$,$q1$agaricus_xanthodermus$q1$,$q1$it$q1$,$q1$Prataiolo giallo (Agaricus xanthodermus): la base del gambo, al taglio, vira immediatamente al giallo cromo, il centro del cappello è spesso grigiastro-metallico, la base del gambo è bulbosa senza pelle a lembi. Champignon coltivato/prataiolo: la superficie di taglio rimane biancastra fino a leggermente rossastra, nessuna base del gambo gialla.$q1$,$q1$Il prataiolo giallo odora in modo pungente di carbolo/fenolo/inchiostro (intensificato al riscaldamento e sfregando la base del gambo). I prataioli commestibili odorano gradevolmente di fungo, di nocciola o di anice.$q1$,$q1$Entrambi su prati ricchi di nutrienti, pascoli, nei parchi e ai margini dei boschi, dall'estate all'autunno – il luogo di crescita NON aiuta nella distinzione.$q1$,$q1$Entrambi color cioccolato – qui il colore della sporata NON è un carattere distintivo; fare attenzione all'ingiallimento e all'odore.$q1$,$q1$Tagliare la base del gambo per il lungo: un netto viraggio al giallo cromo alla base del gambo + odore di carbolo/inchiostro = velenoso, gettare il fungo. Non assaggiare per via orale. Le conseguenze sono violenti disturbi gastro-intestinali (nausea, vomito, diarrea), di norma non pericolosi per la vita.$q1$,array[$q1$La base del gambo, al taglio/alla compressione, vira immediatamente in modo intenso al giallo cromo (giallo brillante) – i prataioli commestibili viranno al massimo debolmente al giallastro sul bordo del cappello, MAI in modo deciso al giallo alla base del gambo.$q1$,$q1$Odora sgradevolmente di carbolo/fenolo ovvero di inchiostro (percepibile al meglio alla base del gambo sfregata o al riscaldamento) – i prataioli commestibili odorano di fungo, di nocciola o di anice/mandorla.$q1$,$q1$Base del gambo ingrossata a bulbo SENZA pelle a lembi/volva; il cappello giovane ha spesso un riflesso grigio-metallico al centro; lamelle rosa da giovani, color cioccolato scuro da vecchie.$q1$,$q1$Luogo di crescita identico (prati, pascoli, parchi, margini dei boschi, suoli ricchi di nutrienti), perciò frequente confusione reale – il luogo NON aiuta nella distinzione.$q1$]::text[],true),
($q1$champignon-de-paris$q1$,$q1$amanita_phalloides$q1$,$q1$it$q1$,$q1$Amanita phalloides: lamelle che restano bianche, volva membranosa bianca alla base bulbosa del gambo, cappello da verde-oliva a (var. alba/giovane) bianco. Champignon: lamelle rosa-brune, nessuna volva, base del gambo senza guaina.$q1$,$q1$Amanita phalloides da giovane poco appariscente, da vecchia di muffa-dolciastra come miele artificiale fino a sgradevole. Champignon gradevolmente di fungo/nocciola/anice.$q1$,$q1$Amanita phalloides come fungo micorrizico nel bosco di latifoglie (soprattutto presso quercia, faggio); i prataioli su terreni coltivati aperti, prati e pascoli.$q1$,$q1$Amanita phalloides bianca, champignon bruna – una sporata bianca è un chiaro segnale d'allarme.$q1$,$q1$Dimezzare per il lungo il sospetto bottone/uovo bianco: presenza di lamelle bianche + involucro-volva alla base = amanita falloide, mortale. Già ca. 20 g sono pericolosi per la vita – nel dubbio controllo funghi VAPKO / Tox Info Suisse 145.$q1$,array[$q1$Lamelle sempre di un bianco puro (anche nel fungo vecchio) – le lamelle del champignon sono rosa da giovani, brune/bruno-nere da vecchie.$q1$,$q1$Base del gambo con base bulbosa circondata da una guaina membranosa a lembi bianca (volva) – nel champignon la volva manca completamente.$q1$,$q1$Sporata bianca (champignon bruna).$q1$,$q1$Gli esemplari giovani assomigliano a un 'uovo' bianco e vengono confusi con particolare facilità con i giovani champignon chiusi – tagliare sempre: nel taglio si mostra la struttura abbozzata di lamelle/volva bianche (all'interno uniformemente bianco-verde, mai rosa).$q1$]::text[],true),
($q1$calvatia_gigantea$q1$,$q1$gemeiner-fliegenpilz-var-alba$q1$,$q1$it$q1$,$q1$Vescia: pelle bianca liscia e chiusa, tondeggiante, senza gambo. A. virosa da giovane: uovo di un bianco puro in un involucro membranoso; da adulta di un bianco puro con cappello acuto-conico, anello e volva membranosa. Nello stadio a uovo esteriormente quasi indistinguibile dalla vescia.$q1$,$q1$A. virosa matura: sgradevole, dolciastra-disgustosa (vecchi ritrovamenti). Vescia giovane: lieve-di fungo. L'odore nello stadio giovane/a uovo è inaffidabile — non considerarlo come via libera.$q1$,$q1$A. virosa: micorriza in bosco acido di conifere/misto, spesso presso abete rosso/betulla, piuttosto regioni montane più fredde/montane. Vescia gigante: prateria aperta, pascoli, giardini. Minore sovrapposizione di habitat rispetto alla phalloides, ma il test del taglio resta obbligatorio.$q1$,$q1$Vescia: nessuna lamella/nessuna sporata rilevante. A. virosa: sporata bianca. Nello stadio a uovo confondibile non utilizzabile — conta solo il taglio.$q1$,$q1$Per ogni piccolo fungo sferico bianco fare un taglio longitudinale: un 'embrione' di fungo bianco visibile nel taglio (gambo + cappello abbozzato) smaschera l'amanita falloide bianca. Solo una massa bianca senza struttura = vescia.$q1$,array[$q1$L'uovo giovane di A. virosa è di un BIANCO PURO e sferico — otticamente praticamente identico a una giovane vescia bianca. Proprio per questo il test del taglio è qui il più importante.$q1$,$q1$TEST DEL TAGLIO: vescia = massa bianca omogenea uniforme; A. virosa mostra nel taglio longitudinale già lamelle, gambo e bulbo abbozzati (sagoma del fungo all'interno) = mortale.$q1$,$q1$A. virosa ha una volva membranosa, a sacco, alla base del gambo e (più tardi) un anello; la vescia non ha né volva né gambo né anello.$q1$,$q1$Confusione solo nello stadio giovane, sferico — non appena nell'amanita compaiono cappello/gambo, la distinzione è banale.$q1$]::text[],true),
($q1$calvatia_gigantea$q1$,$q1$amanita_phalloides$q1$,$q1$it$q1$,$q1$Vescia gigante: pelle esterna liscia, bianca fino a color crema, chiusa, sferica, senza gambo/involucro/volva. A. phalloides giovane nell'uovo: involucro generale membranoso da bianco a tonalità olivastra, sferico-ovoidale — esteriormente ingannevolmente simile, perciò conta solo il taglio.$q1$,$q1$Vescia giovane: gradevolmente di fungo-lieve. A. phalloides matura: dolciastra-simile al miele fino a sgradevole; nello stadio a uovo appena percepibile, perciò NON un carattere affidabile — non considerare mai l'odore come via libera.$q1$,$q1$Vescia gigante: prati, pascoli, giardini, bordi di sentiero, suoli ricchi di nutrienti (non fungo micorrizico). A. phalloides: fungo micorrizico nel bosco di latifoglie/misto, soprattutto presso quercia e faggio. Sovrapposizione possibile ai margini dei boschi/nei parchi — il luogo da solo non protegge.$q1$,$q1$Nella vescia non rilevante (nessuna lamella). A. phalloides: sporata bianca. Nello stadio a uovo entrambe non significative — distinzione unicamente attraverso il taglio longitudinale.$q1$,$q1$Tagliare completamente per il lungo (dall'alto verso il basso) OGNI piccola 'vescia' sferica PRIMA dell'utilizzo. Solo se la superficie è uniformemente di un bianco puro e omogenea — senza alcuna sagoma di gambo/lamelle/cappello — è una vescia. Alla minima struttura interna: mortale amanita falloide, gettare l'intero cesto.$q1$,array[$q1$TEST DEL TAGLIO (decisivo): la vescia gigante ha una massa carnosa completamente omogenea, di un bianco puro, senza struttura interna. Nella giovane amanita falloide nello stadio a uovo, nel taglio longitudinale sono già riconoscibili lamelle, gambo e bulbo abbozzati come sagoma/'embrione' = mortale, gettare subito.$q1$,$q1$Colore interno: vescia giovane all'interno di un bianco puro e omogenea. Qualsiasi viraggio giallastro/verdastro o una sagoma di fungo più scura nel taglio = non è una vescia.$q1$,$q1$Involucro esterno: la vescia ha una pelle esterna liscia, coriacea-chiusa, senza volva. L'uovo dell'amanita falloide è racchiuso in un involucro generale membranoso (velum universale), dal quale si formano volva e base del gambo.$q1$,$q1$La vescia gigante matura (>10 cm fino a 50 cm) è inconfondibile — confusione possibile solo con piccoli esemplari giovani, sferici. Regola pratica: non mangiare alcuna 'vescia' più piccola di un palmo di mano senza controllo del taglio.$q1$]::text[],true),
($q1$calvatia_gigantea$q1$,$q1$amanita_verna$q1$,$q1$it$q1$,$q1$Vescia: pelle esterna liscia, bianca, chiusa, senza struttura, sferica. A. verna giovane: uovo-velum di un bianco puro; matura completamente bianca con volva membranosa e anello. Gli stadi a uovo sono esteriormente quasi identici.$q1$,$q1$A. verna: poco appariscente fino a leggermente sgradevole. Vescia giovane: lieve-di fungo. Nessun carattere distintivo affidabile nello stadio giovane.$q1$,$q1$A. verna: micorriza in boschi di latifoglie/misti caldi (spesso calcarei) presso quercia/castagno, compare soprattutto in primavera/inizio estate, di tonalità mediterranea (esposizioni a sud). Vescia gigante: prateria/pascoli, piuttosto fine estate/autunno. Differenze di stagione e di luogo presenti, ma non sostituiscono il test del taglio.$q1$,$q1$Vescia non rilevante. A. verna: sporata bianca. Nello stadio a uovo inutile per la distinzione — decide il taglio.$q1$,$q1$Taglio longitudinale attraverso ogni piccolo fungo sferico bianco: se nella carne bianca si mostra la sagoma di un piccolo fungo (gambo + abbozzo del cappello), è l'amanita falloide primaverile, mortale — non la vescia.$q1$,array[$q1$L'uovo giovane di A. verna è di un bianco puro e sferico come una giovane vescia — la confusione è perciò reale, soprattutto perché la verna cresce anche in esposizioni più aperte e calde.$q1$,$q1$TEST DEL TAGLIO: massa bianca omogenea della vescia vs. gambo + abbozzo di lamelle + bulbo già riconoscibili all'interno nell'amanita = mortale.$q1$,$q1$A. verna possiede volva membranosa e bulbo alla base del gambo; la vescia non ha volva né gambo.$q1$,$q1$Confondibile solo nello stadio giovane sferico; l'amanita matura con cappello/gambo/anello è inequivocabile.$q1$]::text[],true),
($q1$champignon-de-paris$q1$,$q1$gemeiner-fliegenpilz-var-alba$q1$,$q1$it$q1$,$q1$Amanita virosa: cappello bianco puro, spesso conico, lamelle che restano bianche, base del gambo bulbosa con volva bianca lobata e membranosa. Champignon (prataiolo): lamelle da rosa a brune, nessuna volva, base del gambo senza guaina membranosa.$q1$,$q1$Amanita virosa: odore insignificante fino a dolciastro-nauseante (carne in putrefazione). Champignon (prataiolo): gradevole odore fungino/di nocciola/anisato.$q1$,$q1$Amanita virosa: nel bosco (spesso abeti rossi/conifere, suoli acidi); i prataioli su prati, pascoli, compost, terreni coltivati.$q1$,$q1$Amanita virosa: bianco; Champignon (prataiolo): bruno – la sporata in massa è un criterio di distinzione affidabile (bianco = pericolo).$q1$,$q1$Estrarre sempre il fungo completo dal terreno, compresa la base del gambo, e verificare la presenza di una volva (guaina membranosa) alla base bulbosa – volva + lamelle che restano bianche + sporata in massa bianca = mortale, non toccare. In caso di sospetto Tox Info Suisse 145 / controllo funghi VAPKO.$q1$,array[$q1$Le lamelle restano bianche pure a OGNI età – le lamelle del prataiolo sono da giovani rosa e da vecchie diventano da bruno-cioccolato a bruno-nerastre (mai bianche in modo permanente).$q1$,$q1$Alla base del gambo una base bulbosa ingrossata con guaina bianca membranosa e lobata (volva/velo generale) – i prataioli non hanno MAI una volva.$q1$,$q1$Sporata in massa bianca; la sporata in massa del prataiolo è bruna.$q1$,$q1$Crescita per lo più nel bosco (di conifere), spesso presso abeti rossi – i prataioli prediligono prati, pascoli e terreni coltivati.$q1$]::text[],true),
($q1$clitocybe_nebularis$q1$,$q1$entoloma_sinuatum$q1$,$q1$it$q1$,$q1$Entoloma lividum (Riesenrötling): cappello più compatto, carnoso, da grigio chiaro a giallo-argilla/avorio; lamelle da giovani biancastre-giallastre, da vecchie rosa-carne, corte e attaccate in modo smarginato (sinuato), non decorrenti. Clitocybe nebularis (Nebbiolo): cappello grande (10-25 cm) grigio-nebbia con lamelle biancastre-crema, fitte e brevemente decorrenti sul gambo.$q1$,$q1$Clitocybe nebularis (Nebbiolo): odore invadente dolciastro-aromatico (percepito da molti come sgradevole). Entoloma lividum (Riesenrötling): farinoso-rancido con nota acidula-rafanoide, sgradevole.$q1$,$q1$Entoloma lividum (Riesenrötling): calcofilo, in boschi di latifoglie e misti (soprattutto faggio, quercia, carpino) su suolo calcareo/argilloso, piuttosto raro, da maggio a novembre; cresce isolato, in gruppi OPPURE in cerchi delle streghe. Clitocybe nebularis (Nebbiolo): frequente e spesso in gran quantità, in boschi di latifoglie e conifere, tardo autunno (ott-nov), forma anch'esso file e cerchi delle streghe. ATTENZIONE: la crescita in cerchio delle streghe NON serve per la distinzione — entrambe le specie la presentano.$q1$,$q1$DECISIVO: Entoloma lividum (Riesenrötling) rosa-carne fino a rosa-bruno (carattere distintivo del genere Entoloma). Clitocybe nebularis (Nebbiolo) bianco fino a crema-giallastro pallido. Una semplice sporata su carta bianca distingue i due con sicurezza — è il carattere più affidabile.$q1$,$q1$La sporata è obbligatoria: polvere rosa/rosa-carne = Entoloma (Rötling) = NON mangiare. Il Nebbiolo (Clitocybe nebularis) rilascia una polvere da bianca a crema pallida e ha lamelle brevemente decorrenti e fitte. NON affidarti alla forma di crescita — ENTRAMBE le specie possono formare file e cerchi delle streghe, NON è un criterio di distinzione.$q1$,array[$q1$Sporata in massa (carattere PIÙ SICURO): Entoloma lividum (Riesenrötling) da rosa-carne a rosa-bruno (genere Entoloma) — Clitocybe nebularis (Nebbiolo) da bianco a crema-giallastro pallido. La sporata su carta bianca distingue inequivocabilmente i due.$q1$,$q1$Colore delle lamelle con l'età: le lamelle dell'Entoloma lividum (Riesenrötling) da giovani biancastre/giallastre, da vecchie nettamente rosa-CARNE per via delle spore — le lamelle del Clitocybe nebularis (Nebbiolo) restano da bianche a crema-giallastre, MAI rosa.$q1$,$q1$Attacco delle lamelle: le lamelle del Clitocybe nebularis (Nebbiolo) sono brevemente DECORRENTI sul gambo (tipico dei clitocibi), fitte; le lamelle dell'Entoloma lividum (Riesenrötling) sono attaccate in modo smarginato (sinuato), corte, rigide e poco fitte — NON decorrenti.$q1$,$q1$Odore: Clitocybe nebularis (Nebbiolo) invadente dolciastro-aromatico; Entoloma lividum (Riesenrötling) farinoso-rancido con sgradevole nota acidula-rafanoide.$q1$]::text[],true),
($q1$eierschwamm$q1$,$q1$cortinarius_orellanus$q1$,$q1$it$q1$,$q1$Galletto (Pfifferling): giallo tuorlo con forma a imbuto e pseudolamelle (pliche). Cortinarius (Raukopf): da bruno-rossastro a arancione con vere lamelle.$q1$,$q1$Galletto (Pfifferling): fruttato di albicocca. Cortinarius (Raukopf): rafanoide (di ravanello).$q1$,$q1$Galletto (Pfifferling): mag-ott, bosco di conifere. Cortinarius (Raukopf): set-nov, bosco di latifoglie.$q1$,$q1$Galletto (Pfifferling): giallo pallido. Cortinarius (Raukopf): bruno-ruggine.$q1$,$q1$REGOLA D'ORO: rovesciare il cappello — VERE lamelle o PSEUDOLAMELLE (pliche)? In caso di dubbio VAPKO!$q1$,array[$q1$Il galletto (Pfifferling) ha PSEUDOLAMELLE (pliche), il Cortinarius (Raukopf) ha VERE lamelle$q1$,$q1$Il galletto (Pfifferling) è giallo tuorlo-albicocca, il Cortinarius (Raukopf) è da arancione a bruno-rossastro$q1$]::text[],true),
($q1$eierschwamm$q1$,$q1$hygrophoropsis_aurantiaca$q1$,$q1$it$q1$,$q1$Pseudolamelle/pliche (galletto, Pfifferling) vs. vere lamelle (falso galletto); consistenza soda vs. molle.$q1$,$q1$Galletto (Pfifferling) fruttato (albicocca); il falso aspecifico/muffito.$q1$,$q1$Galletto (Pfifferling) in bosco di latifoglie/conifere; il falso soprattutto su lettiera di aghi/legno morto.$q1$,$q1$entrambi pallido.$q1$,$q1$Il falso galletto (Hygrophoropsis aurantiaca) è debolmente tossico (gastro-intestinale). Verificare pseudolamelle/pliche ottuse vs. lamelle nette e staccabili. In caso di colore arancio-rosso intenso escludere inoltre l'Omphalotus (fungo dell'olivo, tossico).$q1$,array[$q1$Galletto vero (Pfifferling): pseudolamelle/pliche ottuse, saldamente concresciute, soda-carnoso$q1$,$q1$Falso galletto: vere lamelle sottili, fortemente forcate, facilmente staccabili, molle$q1$]::text[],true),
($q1$hallimasch$q1$,$q1$cortinarius_orellanus$q1$,$q1$it$q1$,$q1$Chiodino (Hallimasch): giallo-miele con anello, in fascetti (cespitoso). Cortinarius (Raukopf): da arancione a bruno-rossastro, isolato.$q1$,$q1$Chiodino (Hallimasch): acidulo. Cortinarius (Raukopf): rafanoide (di ravanello).$q1$,$q1$Chiodino (Hallimasch): ceppi d'albero, radici. Cortinarius (Raukopf): a terra, bosco di latifoglie.$q1$,$q1$Chiodino (Hallimasch): bianco. Cortinarius (Raukopf): bruno-ruggine.$q1$,$q1$Prestare particolare attenzione con i funghi giovani. Eseguire la sporata.$q1$,array[$q1$Il chiodino (Hallimasch) ha l'anello + parassita sull'albero, il Cortinarius (Raukopf) è isolato$q1$,$q1$Sporata in massa: chiodino (Hallimasch) bianco, Cortinarius (Raukopf) bruno-ruggine$q1$]::text[],true),
($q1$kuehneromyces_mutabilis$q1$,$q1$galerina_marginata$q1$,$q1$it$q1$,$q1$Entrambi color bruno-miele, igrofani, in fascetti sul legno — otticamente molto simili; a distinguere è unicamente il gambo sotto la zona dell'anello (squamoso vs. liscio).$q1$,$q1$entrambi di odore fungino, nessuna distinzione olfattiva sicura$q1$,$q1$entrambi su legno morto/ceppi, spesso mescolati$q1$,$q1$entrambi bruno-ruggine$q1$,$q1$MORTALE. Per principianti vietato. Raccogliere solo con il gambo completo e controllare ogni singolo fungo — nel dubbio al controllo VAPKO.$q1$,array[$q1$Gambo sotto l'anello: il Kuehneromyces mutabilis squamoso/pruinoso, la Galerina marginata liscio-setoso$q1$,$q1$La Galerina marginata contiene amatossine mortali$q1$]::text[],true),
($q1$infundibulicybe_geotropa$q1$,$q1$clitocybe_rivulosa$q1$,$q1$it$q1$,$q1$Clitocybe rivulosa: fino a 4-5 cm, bianco-gesso pruinoso, depresso senza umbone, gambo sottile. Infundibulicybe geotropa: 12-25 cm, crema/bruno-cuoio, con umbone centrale, gambo spesso e clavato.$q1$,$q1$L'Infundibulicybe geotropa aromatico e dolciastro con nota di mandorla amara; la Clitocybe rivulosa inappariscente fino a debole. Usare l'odore solo come carattere accessorio, mai da solo.$q1$,$q1$Clitocybe rivulosa: tappeti erbosi, prati, bordi dei sentieri, dune, scarpate, parchi (nell'erba, in gruppi/cerchi delle streghe). Infundibulicybe geotropa: bosco di latifoglie/conifere su suolo calcareo, margini boschivi, radure boschive. Bosco vs. prateria aperta è il criterio di stazione rilevante.$q1$,$q1$Entrambi BIANCO - nessuna distinzione possibile tramite il colore delle spore; decidono dimensione + spessore della carne + stazione + umbone.$q1$,$q1$Ogni piccolo imbutino bianco-gesso pruinoso nell'erba/prato è sospetto di muscarina - in caso di dubbio lasciarlo stare. L'Infundibulicybe geotropa è grande (12-25 cm), a carne spessa, legato al bosco e ha un umbone centrale percepibile al tatto - non il piccolo, gracile fungo bianco dei prati. Il polverino sporale bianco NON esclude la Clitocybe velenosa, poiché anch'essa sporula bianco.$q1$,array[$q1$Dimensione: la Clitocybe rivulosa solo fino a ca. 4-5 cm di cappello, bianco-gesso pruinosa, depressa/infossata senza umbone; l'Infundibulicybe geotropa 12-25 cm, a carne spessa, con umbone centrale nettamente percepibile al tatto.$q1$,$q1$Entrambi biancastri-imbutiformi con lamelle decorrenti e polverino sporale BIANCO - solo dimensione, spessore della carne e umbone del cappello li separano con sicurezza, NON il colore né il polverino sporale.$q1$,$q1$Altamente velenosa per la muscarina (sindrome muscarinica: forte salivazione/sudorazione/lacrimazione entro 15-30 min, nei casi gravi collasso circolatorio), spesso nelle stesse stazioni di prati/bordi di sentieri/dune in gruppi o cerchi delle streghe.$q1$,$q1$Gambo gracile/sottile nella Clitocybe velenosa vs. robusto-clavato (2-4 cm di spessore) nell'Infundibulicybe geotropa.$q1$]::text[],true),
($q1$infundibulicybe_geotropa$q1$,$q1$clitocybe_dealbata$q1$,$q1$it$q1$,$q1$Infundibulicybe geotropa: 12-25 cm, crema/color cuoio fino a ocra-rossastro con l'età, umbone centrale percepibile al tatto, gambo robusto-clavato. Clitocybe dealbata: solo 2-5 cm, bianco-gesso pruinosa, depressa/piana senza umbone, gambo sottile e gracile.$q1$,$q1$L'Infundibulicybe geotropa odora aromatico e dolciastro con netta nota di mandorla amara; la Clitocybe dealbata insignificante fino a debolmente farinoso. Attenzione: l'odore è un carattere DI SUPPORTO, mai l'unico criterio di sicurezza - combinarlo sempre con dimensione/umbone/spessore della carne.$q1$,$q1$Clitocybe dealbata: prateria aperta, prati, pascoli, tappeti erbosi, bordi dei sentieri, parchi. Infundibulicybe geotropa: bosco di latifoglie e conifere, margini boschivi, radure boschive su suolo calcareo umido. Entrambi possono formare cerchi delle streghe - il tipo di stazione (bosco vs. erba aperta) è più rilevante della crescita in cerchi.$q1$,$q1$Entrambi BIANCO - il polverino sporale qui NON aiuta nella distinzione. La separazione avviene tramite dimensione, spessore della carne, umbone del cappello e spessore del gambo.$q1$,$q1$Regola d'oro: i PICCOLI imbutini bianchi (sotto ca. 6 cm, a carne sottile, senza umbone percepibile) MAI mangiarli - contengono muscarina e come gruppo sono pericolosamente confondibili in modo letale. Prendere solo il grande (12-25 cm) Infundibulicybe geotropa a carne spessa, con umbone centrale chiaramente percepibile al tatto e gambo robusto. Cerchi delle streghe e polverino sporale bianco li hanno ENTRAMBI - NON servono alla distinzione.$q1$,array[$q1$Dimensione/carne: la Clitocybe dealbata solo 2-5 cm di cappello, a carne sottile (pochi mm); l'Infundibulicybe geotropa 12-25 cm, a carne spessa e con umbone/verruca centrale nettamente percepibile al tatto al centro del cappello (test con le dita) - l'umbone manca sempre alla Clitocybe dealbata.$q1$,$q1$Entrambi bianchi/color crema e imbutiformi con lamelle decorrenti e polverino sporale BIANCO - il colore del cappello e il polverino sporale NON aiutano, solo dimensione + spessore della carne + umbone + stazione separano con sicurezza.$q1$,$q1$Stazione/stagione: la Clitocybe dealbata su prati, pascoli, bordi dei sentieri, tappeti erbosi, parchi (inizio estate-tardo autunno, spesso in cerchi delle streghe); l'Infundibulicybe geotropa nel bosco di latifoglie/conifere, ai margini boschivi e nelle radure boschive su suolo calcareo umido (tardo estate-autunno, anch'esso cerchi delle streghe - la stazione da sola NON basta).$q1$,$q1$Gambo: l'Infundibulicybe geotropa ha gambo robusto, spesso ingrossato a clava (2-4 cm di spessore, 8-15 cm di lunghezza); la Clitocybe dealbata gracile e sottile.$q1$]::text[],true),
($q1$infundibulicybe_geotropa$q1$,$q1$entoloma_sinuatum$q1$,$q1$it$q1$,$q1$Entoloma sinuatum: 5-20 cm, avorio/grigio-bruno chiaro fino a grigio-lillaceo pallido, convesso con margine ondulato senza umbone, lamelle spesse e rigide che virano al rosa. Infundibulicybe geotropa: imbutiforme con umbone centrale, lamelle bianche decorrenti, crema/color cuoio.$q1$,$q1$L'Entoloma sinuatum farinoso con sgradevole odore acidulo-rafanoide; l'Infundibulicybe geotropa aromatico e dolciastro con aroma di mandorla amara. L'odore solo come carattere accessorio, lo sporata è decisivo.$q1$,$q1$Entoloma sinuatum: bosco rado di latifoglie (spesso faggio/quercia-carpino) su suolo fresco fino a umido, ricco di calcare, estate-autunno, micorrizico. Infundibulicybe geotropa: bosco di latifoglie/conifere, margini boschivi, radure boschive su suolo calcareo umido, tardo estate-autunno - le stazioni si sovrappongono, quindi il controllo dello sporata e delle lamelle è obbligatorio.$q1$,$q1$Decisivo: l'Entoloma sinuatum ha polverino sporale ROSA-CARNE/rosato-carnicino vs. l'Infundibulicybe geotropa BIANCO. Questo è il carattere distintivo più sicuro tra questi due.$q1$,$q1$Eseguire lo sporata: polvere rosa/color carne = Entoloma sinuatum = lasciarlo stare. Inoltre verificare se le lamelle decorrono (Infundibulicybe geotropa) o sono solo smarginate/diritte e adnate e con la maturazione virano al rosa (Entoloma sinuatum). Se manca l'umbone centrale e il cappello non è realmente imbutiforme, è doverosa la prudenza.$q1$,array[$q1$POLVERINO SPORALE: l'Entoloma sinuatum ha polverino sporale ROSA-CARNE (rosato-carnicino); l'Infundibulicybe geotropa ha polverino sporale BIANCO - il carattere distintivo più sicuro tramite lo sporata.$q1$,$q1$LAMELLE: le lamelle dell'Entoloma sinuatum da giovani biancastre, poi giallastre, infine rosa-carne per le spore, smarginate/diritte e adnate al gambo (NON decorrenti); le lamelle dell'Infundibulicybe geotropa restano bianche/color crema e decorrono nettamente lungo il gambo.$q1$,$q1$FORMA DEL CAPPELLO: l'Entoloma sinuatum convesso con margine inrotolato, poi ondulato, SENZA umbone centrale e senza marcata forma a imbuto; l'Infundibulicybe geotropa imbutiforme con umbone centrale percepibile al tatto.$q1$,$q1$ODORE: l'Entoloma sinuatum farinoso con sgradevole nota acidula-rafanoide; l'Infundibulicybe geotropa aromatico e dolciastro con nota di mandorla amara.$q1$]::text[],true),
($q1$lactarius_deliciosus$q1$,$q1$paxillus_involutus$q1$,$q1$it$q1$,$q1$Lactarius deliciosus: interamente da arancione a rosso-carota, cappello con zone concentriche più scure, spesso macchie verdastre con l'età/in caso di lesione, gambo spesso con scrobicoli. Paxillus involutus: opaco da giallo-bruno a bruno-umbra, margine del cappello permanentemente inrotolato e feltroso, nessun arancione, nessuna zona concentrica da Lactarius.$q1$,$q1$Lactarius deliciosus: mite, fruttato-fragrante. Paxillus involutus: inappariscente, leggermente acidulo; nessun tipico profumo da Lactarius.$q1$,$q1$Sovrapposizione di habitat possibile: il Lactarius deliciosus è partner micorrizico dei pini (in parte abeti rossi), preferibilmente suolo calcareo. Il Paxillus involutus forma micorriza con pino, abete rosso, betulla, faggio su suoli acidi, freschi fino a umidi. La stazione NON è quindi un carattere distintivo sicuro - contano solo il test del latice e il colore.$q1$,$q1$Lactarius deliciosus: polverino sporale da bianco-crema a ocra-giallastro pallido. Paxillus involutus: polverino sporale brunastro (bruno-argilla) - nettamente più scuro. Indicazione diagnostica chiara: il Paxillus sempre marcatamente più scuro.$q1$,$q1$Il test del taglio/del latice è obbligatorio: chi NON vede latice arancio-rosso al taglio non ha un Lactarius deliciosus - lasciarlo stare. Il Paxillus involutus non emette mai latice e alla pressione vira al bruno-nerastro (il Lactarius vira solo lentamente al verde). La sindrome paxillica (immuno-emolitica) può avere esito mortale dopo anni di consumo ripetuto - perciò non assaggiarlo mai 'per provare', nemmeno cotto.$q1$,array[$q1$TEST DEL LATICE (decisivo): il Lactarius deliciosus emette al taglio abbondante latice rosso-carota/arancione. Il Paxillus involutus NON emette latice - non è un fungo lattario. Nessun latice arancio-rosso = nessun Lactarius deliciosus.$q1$,$q1$Viraggio alla pressione: lamelle e carne del Paxillus virano subito alla pressione/lesione da bruno a bruno-rossastro scuro/bruno-nerastro. La carne/il latice del Lactarius vira solo lentamente al verdastro (mai al bruno-nerastro).$q1$,$q1$Lamelle: il Paxillus da giallo-ocra a bruno-oliva, decorrenti lungo il gambo e facilmente staccabili dalla carne del cappello. Le lamelle del Lactarius sono arancioni/color zafferano e non staccabili.$q1$,$q1$Colore del cappello + margine del cappello: il Lactarius da arancione a rosso-carota con zone anulari concentriche più scure. Il Paxillus opaco da giallo-bruno a bruno-umbra, senza arancione, con margine del cappello permanentemente inrotolato e feltroso (anche con l'età).$q1$]::text[],true),
($q1$lactarius_deterrimus$q1$,$q1$paxillus_involutus$q1$,$q1$it$q1$,$q1$Lactarius deterrimus (lattario degli abeti): cappello da rosso-arancio a bruno-arancio, con l'età/in caso di gelo macchiato di verde sporco, lamelle arancio pallido che, se lese, diventano da rosso scuro a grigio-verde. Paxillus involutus (paxillo): cappello da giallastro a bruno-umbra, lucido se umido, da giovane con margine a lungo arrotolato e feltroso, da vecchio nettamente depresso a imbuto; lamelle da ocra-giallastre a oliva-brune, sottili e fitte, decorrenti e separabili, che a pressione/contatto si colorano FORTEMENTE di bruno-ruggine fino a bruno-nero (le lamelle del lattario non diventano bruno-ruggine). Entrambi possono apparire a imbuto e bruno-arancio -> da qui la confusione.$q1$,$q1$Lactarius deterrimus: mite, fruttato-speziato (sapore leggermente amaro). Paxillus involutus: acidulo-insignificante; l'odore NON è un carattere distintivo affidabile — la prova del latte e la prova di pressione sulle lamelle sono decisive.$q1$,$q1$Sovrapposizione presente: il Paxillus involutus è partner micorrizico tra l'altro dell'abete rosso (anche pino, betulla, faggio, carpino) e cresce nello stesso terreno acido di bosco di conifere/misto in cui il Lactarius deterrimus compare presso l'abete rosso. L'habitat NON separa in modo affidabile.$q1$,$q1$Carattere secondario, non nettamente distintivo: il Lactarius deterrimus, a seconda della fonte, da crema a ocra pallido fino a bruno-ocraceo; il Paxillus involutus nettamente da bruno-argilla a bruno-ruggine. I colori si sovrappongono verso l'ocra — quindi solo come prova aggiuntiva, non come criterio principale. Resta decisiva la prova del latte. In caso di dubbio prelevare la sporata.$q1$,$q1$Fare sempre la prova del latte: tagliare il fungo fresco e verificare la fuoriuscita di latte. Se NON esce latte, non è un lattario — il Paxillus involutus è privo di latte e, attraverso la sindrome cumulativa da Paxillus (anemia emolitica, insufficienza renale), può diventare pericoloso per la vita anche dopo anni di consumo. I lattari invece emettono latte arancio/rosso-carota che vira al rosso-vino. Regola pratica: raccogliere solo lattari con latte rosso/arancio — mai con latte chiaro/bianco o del tutto privo di latte.$q1$,array[$q1$PROVA DEL LATTE (decisiva, verificata): il Lactarius deterrimus al taglio emette latte arancio/rosso-carota che in 15-20 min vira al rosso-vino (poi grigio-verde); il Paxillus involutus NON emette alcun latte/liquido — nessun latte = MAI mangiare, se ci si aspetta un lattario.$q1$,$q1$Prova di pressione sulle lamelle (verificata): le lamelle del Paxillus a pressione si colorano fortemente da bruno-ruggine a bruno-nero e si lasciano staccare dal cappello; le lamelle del lattario sono fragili, saldamente unite al cappello e, se lese, diventano rosso scuro/grigio-verde, non bruno-ruggine.$q1$,$q1$Margine del cappello e forma: il Paxillus ha margine del cappello a lungo arrotolato e feltroso e cappello bruno-oliva lucido; il cappello del lattario è arancio con macchie verdi, senza arrotolamento feltroso permanente del margine.$q1$,$q1$Sporata (aggiuntiva, non affidabile da sola): lattario da crema a ocra vs. Paxillus da bruno-argilla a bruno-ruggine — si sovrappongono verso l'ocra, quindi solo a complemento.$q1$]::text[],true),
($q1$lepista_nuda$q1$,$q1$cortinarius_orellanus$q1$,$q1$it$q1$,$q1$Cortinarius orellanus: cappello da giallo a rosso-bruno, leggermente umbonato, finemente squamoso-fibrilloso, lamelle da giallo a bruno-cannella, fibre del velo bruno-ruggine sul gambo. Lepista nuda: interamente violetta, cappello liscio e convesso senza velo.$q1$,$q1$Lepista nuda nettamente aromatica-dolciastra (profumata). orellanus odora debolmente di ravanello, senza profumo dolciastro. L'odore solo come indizio, mai affidabile da solo.$q1$,$q1$orellanus: bosco di latifoglie/misto presso quercia e faggio (micorriza), dall'estate al tardo autunno, piuttosto raro/in stazioni calde. Lepista nuda: lettiera ricca di nutrienti, siepi, compost, molto tardi nella stagione.$q1$,$q1$Lepista nuda da rosa pallido a biancastro; Cortinarius orellanus bruno-ruggine. Una sporata bruno-ruggine esclude la Lepista nuda.$q1$,$q1$La sporata è obbligatoria: bruno-ruggine = cortinario, pericoloso per la vita. Cortinarius orellanus è considerato uno dei funghi più pericolosi d'Europa (orellanina, latenza fino a 14 giorni, danni a reni e fegato). Un velo a ragnatela sul fungo giovane o fibre bruno-ruggine sul gambo = mai mangiare. Al minimo dubbio scartare.$q1$,array[$q1$Sporata (il distintivo più affidabile per l'intero genere dei cortinari): Lepista nuda da rosa pallido a biancastro vs. Cortinarius orellanus bruno-ruggine. Una sporata bruno-ruggine esclude la Lepista nuda.$q1$,$q1$Cortina/velo: orellanus ha un velo a ragnatela (da giovane giallastro) con resti del velo bruno-ruggine sul gambo; Lepista nuda non ha alcun velo (velum).$q1$,$q1$Colore del cappello: orellanus da giallo a rosso-bruno/fulvo (MAI violetto), spesso leggermente umbonato; Lepista nuda in gioventù interamente violetta.$q1$,$q1$Colore delle lamelle: orellanus da giallo a bruno-cannella, distanziate, attaccate in modo smarginato; Lepista nuda violetta/violetto-rosa e che rimane chiara.$q1$]::text[],true),
($q1$lepista_nuda$q1$,$q1$cortinarius_rubellus$q1$,$q1$it$q1$,$q1$Lepista nuda: da giovane interamente violetta (cappello, lamelle, gambo), cappello convesso e liscio senza umbone appuntito, senza velo. Cortinarius rubellus: cappello da ruggine ad arancio-volpe con apice appuntito (umbonato), finemente feltroso-fibrilloso, lamelle da cannella a bruno-ruggine, fibre del velo bruno-ruggine sul gambo.$q1$,$q1$Lepista nuda odora aromatica-dolciastra (profumata, ricorda biscotto/fiore d'arancio). Cortinarius rubellus odora debolmente di ravanello, senza il tipico profumo dolciastro. L'odore è solo un indizio, MAI affidabile da solo — sporata + cortina sono decisive.$q1$,$q1$Cortinario (Raukopf): boschi di conifere acidi (abete rosso/bosco misto abete rosso-pino), stazioni torbose-umide e di montagna, ago-ott. Lepista nuda (Roetelritterling): lettiera di bosco di latifoglie/misto ricca di nutrienti, siepi, cumuli di compost, molto tardi nella stagione fino a dopo le prime gelate.$q1$,$q1$Decisivo: Lepista nuda = sporata da rosa pallido a biancastra/crema-rosa. Cortinarius rubellus = sporata bruno-ruggine. Una sporata bruno-ruggine esclude con sicurezza la Lepista nuda.$q1$,$q1$Prelevare SEMPRE una sporata (cappello sulla carta bianca per una notte). Da rosa pallido a biancastra = possibilmente Lepista nuda. Bruno-ruggine OPPURE un velo a ragnatela (cortina) sul fungo giovane = STOP, cortinario — non mangiare mai. L'avvelenamento da orellanina si manifesta solo dopo 3-14 giorni, quando il rene è già danneggiato in modo irreversibile. Al minimo dubbio non mangiare.$q1$,array[$q1$Sporata (il controllo distintivo più sicuro): Lepista nuda da rosa pallido a biancastra/crema-rosa — OGNI Cortinarius/cortinario ha sporata BRUNO-RUGGINE. Una sporata bruno-ruggine esclude con sicurezza la Lepista nuda.$q1$,$q1$Cortina/velo: il cortinario da fungo giovane ha un velo a ragnatela (cortina) tra il margine del cappello e il gambo; i resti del velo sul gambo si colorano di bruno-ruggine. La Lepista nuda non ha MAI un velo — nessun velum.$q1$,$q1$Forma/colore del cappello: Cortinarius rubellus da ruggine a cannella/arancio-volpe con apice appuntito e umbonato; Lepista nuda da giovane interamente violetta, cappello convesso senza umbone appuntito.$q1$,$q1$Colore delle lamelle: Lepista nuda violetta/violetto-rosa e che rimane chiara; cortinario da cannella a bruno-ruggine, distanziate, attaccate in modo smarginato.$q1$,$q1$Habitat: il cortinario presso conifere (abete rosso) su terreno acido, spesso torboso-umido di montagna; la Lepista nuda in lettiera di bosco di latifoglie/misto ricca di nutrienti, siepi, cumuli di compost, tardi nella stagione fino a dopo il gelo.$q1$]::text[],true),
($q1$lycoperdon_perlatum$q1$,$q1$amanita_phalloides$q1$,$q1$it$q1$,$q1$Dall'esterno un uovo bianco e chiuso di tignosa verdognola (Amanita phalloides) può somigliare superficialmente a un giovane vesce bianco. Separabili con sicurezza solo nella sezione longitudinale: massa bianca omogenea (vesce) vs. fungo preformato con silhouette di lamelle/gambo e volva (Amanita).$q1$,$q1$Il giovane vesce è inodore o di odore fungino-mite. La giovane tignosa verdognola è quasi inodore, solo da vecchia dolciastra-melliflua fino a odore di carogna. L'odore NON è un carattere affidabile nello stadio critico a uovo.$q1$,$q1$A. phalloides è fungo micorrizico soprattutto presso quercia e faggio (anche castagno), predilige terreni acidi; il vesce è saprotrofo e ubiquitario in tutti i tipi di bosco, prati e giardini. Le stazioni si sovrappongono spesso → l'habitat NON aiuta nella distinzione, solo la prova del taglio è sicura.$q1$,$q1$Nel vesce all'interno matura una sporata da giallo a bruno-oliva (il fungo allora non è più commestibile). A. phalloides ha sporata bianca – nello stadio a uovo però non verificabile, quindi irrilevante per il raccoglitore.$q1$,$q1$Dividere SEMPRE per il lungo, completamente a metà, ogni vesce sferico prima del consumo e verificare l'immagine in sezione. Mangiare solo se l'interno è COMPLETAMENTE bianco puro e omogeneo – senza il minimo profilo in controluce di lamelle, gambo o cappello. Un solo contorno di fungo riconoscibile significa avvelenamento mortale da amatossine (insufficienza epatica). In caso di dubbio recarsi all'ufficio di controllo funghi (VAPKO).$q1$,array[$q1$SEZIONE LONGITUDINALE (il test decisivo): nel vesce l'interno è una massa del tutto uniforme, bianca pura, simile a marshmallow, SENZA alcuna struttura. Nel giovane uovo di tignosa verdognola si vede già in sezione il fungo preformato – le lamelle abbozzate e il gambo come silhouette/profilo in controluce più scuro. Già un solo accenno riconoscibile di lamelle o gambo = scartare.$q1$,$q1$Base del gambo/volva: la giovane Amanita è racchiusa in un velo generale bianco e membranoso (velum) e ha alla base un bulbo/volva lobato e membranoso. Il vesce non ha volva, né gambo distinto, né un involucro di questo tipo – siede nel terreno con una breve base sterile.$q1$,$q1$Superficie esterna: il vesce (Lycoperdon perlatum) porta fini aculei/verruche asportabili, che lasciano un disegno a rete, ed è bianco all'interno. L'uovo dell'Amanita è esternamente bianco, liscio e membranoso.$q1$,$q1$La maturazione cambia il vesce: appena l'interno diventa giallastro/olivastro/brunastro (formazione di spore), non è più commestibile – la carne dell'Amanita rimane bianca in sezione e mostra la silhouette del fungo.$q1$]::text[],true),
($q1$lycoperdon_perlatum$q1$,$q1$amanita_verna$q1$,$q1$it$q1$,$q1$Esternamente molto simile al giovane vesce bianco (uovo bianco puro e membranoso); distinguibile con sicurezza solo in sezione trasversale, attraverso la struttura del fungo abbozzata (lamelle+gambo) e la volva pronunciata – non dalla forma esterna.$q1$,$q1$A. verna da giovane inodore o di odore debole; da vecchia di odore sgradevole-dolciastro. Nessun carattere distintivo affidabile nello stadio a uovo.$q1$,$q1$A. verna compare soprattutto in primavera/inizio estate (boschi di latifoglie, piuttosto su terreni calcarei/caldi); i vesci compaiono piuttosto in estate-autunno e sono ubiquitari. Stagione/stazione sono indizi, ma NON un sostituto sicuro della prova del taglio.$q1$,$q1$A. verna: sporata bianca. Vesce: sporata da giallo a bruno-oliva a maturità (allora non più commestibile). Nello stadio a uovo non verificabile, quindi irrilevante per la determinazione.$q1$,$q1$Anche qui: dividere a metà ogni reperto bianco sferico – mangiare solo se l'interno è completamente omogeneo e bianco, senza silhouette di lamelle/gambo e senza volva. Un fungo abbozzato in sezione significa avvelenamento mortale da amatossine. Ufficio di controllo (VAPKO) a ogni incertezza.$q1$,array[$q1$Come tutte le tignose bianche (sezione Phalloideae), A. verna nello stadio giovane a uovo, avvolto dal velum bianco, è sferica e può essere confusa con i vesci bianchi. La SEZIONE LONGITUDINALE decide: massa bianca omogenea (vesce) vs. lamelle + gambo preformati nell'uovo (Amanita).$q1$,$q1$Base del gambo: A. verna mostra alla base una guaina (volva) nettamente pronunciata, lobata, a sacco e membranosa – nel vesce manca ogni volva.$q1$,$q1$Le lamelle rimangono bianche fino a bianco-crema (anche a maturità) – nell'uovo abbozzate in sezione come silhouette chiara; il vesce non ha mai accenni di lamelle.$q1$,$q1$Esternamente bianco puro e membranoso (Amanita) vs. finemente verrucoso/aculeato con verruche asportabili (Lycoperdon perlatum).$q1$]::text[],true),
($q1$lycoperdon_perlatum$q1$,$q1$gemeiner-fliegenpilz-var-alba$q1$,$q1$it$q1$,$q1$Visto dall'alto/dall'esterno è quasi impossibile distinguerlo dalla giovane vescia bianca, poiché A. virosa è completamente bianca pura. Una distinzione sicura è possibile solo in sezione trasversale: fungo bianco già preformato con lamelle fitte + volva (Amanita) contro massa bianca omogenea (vescia).$q1$,$q1$L'A. virosa più vecchia ha un odore sgradevole dolciastro-nauseante; l'uovo giovane però è inodore/non caratteristico. L'odore nello stadio critico a uovo non è affidabile.$q1$,$q1$L'A. virosa cresce soprattutto in boschi di conifere/misti umidi (acidi), in micorriza preferibilmente con l'abete rosso (ritrovamenti documentati anche presso faggio/quercia/betulla), spesso a quote più alte/montane – ecologicamente in parte diversa dalla vescia saprotrofa ubiquitaria, ma la stazione di crescita NON è un criterio sicuro.$q1$,$q1$A. virosa: sporata bianca. Nella vescia matura una sporata da gialla a oliva-bruna (= a quel punto non più commestibile). Allo stadio a uovo non è verificabile, quindi irrilevante per la determinazione.$q1$,$q1$Poiché l'uovo bianco dell'Amanita virosa è bianco puro e assomiglia in modo particolare a una vescia bianca, vale a maggior ragione la regola severa: sezionare completamente a metà, e mangiare SOLO in presenza di carne interna bianca assolutamente omogenea, senza alcuna sagoma di lamelle/gambo e senza volva. Qualunque contorno di fungo = pericolo di vita (amatossine, insufficienza epatica). Nel dubbio rivolgersi al controllo dei funghi (VAPKO).$q1$,array[$q1$Gli stadi giovani di Amanita virosa vengono espressamente confusi con vesce e vescioni nelle banche dati micologiche/tossicologiche. Decisiva è la SEZIONE LONGITUDINALE: vescia = massa bianca pura omogenea; uovo di Amanita = lamelle (bianche, fitte) e gambo già abbozzati, riconoscibili come sagoma.$q1$,$q1$Base del gambo: A. virosa ha una guaina bianca membranosa e lobata (volva) alla base. La vescia non ha volva né un gambo distinto.$q1$,$q1$Contorno esterno: l'uovo di virosa è bianco puro e liscio-membranoso; la vescia comune porta fini verruche/aculei asportabili.$q1$,$q1$Poiché A. virosa è completamente bianca (cappello, lamelle, gambo restano bianchi), viene meno l'indizio del colore – solo l'immagine in sezione e la volva distinguono con sicurezza.$q1$]::text[],true),
($q1$marasmius_oreades$q1$,$q1$clitocybe_dealbata$q1$,$q1$it$q1$,$q1$Clitocybe dealbata: più piccolo, cappello da bianco-gesso a giallo-crema, spesso depresso, con lamelle fitte e decorrenti. Marasmius oreades: cappello bruno-giallo cuoio con umbone, lamelle distanziate, gambo nettamente più tenace.$q1$,$q1$Marasmius oreades dall'odore gradevolmente speziato (chiodo di garofano/mandorla amara) — non percepibile geneticamente da circa il 25% delle persone, quindi non è un carattere a sé stante. Clitocybe dealbata da farinoso a inodore.$q1$,$q1$Come C. rivulosa è un tipico fungo di prati/tappeti erbosi in punti erbosi, eventualmente in cerchi delle streghe — esattamente nell'habitat del Marasmius oreades. La stazione di crescita non serve alla distinzione.$q1$,$q1$Entrambi con sporata BIANCA — non è un carattere distintivo. Restano decisivi l'inserzione delle lamelle e il gambo tenace.$q1$,$q1$La muscarina agisce già in piccole quantità (sudorazione, salivazione, lacrimazione dopo 15-30 min). Non raccogliere mai quando le lamelle sono fitte e decorrono lungo il gambo — il commestibile Marasmius oreades ha SEMPRE lamelle distanziate, non decorrenti, e un gambo tenace e flessibile. L'odore di chiodo di garofano è solo una conferma aggiuntiva.$q1$,array[$q1$Lamelle: Clitocybe dealbata fitte, da adnate a brevemente DECORRENTI lungo il gambo — Marasmius oreades distanziate, inserite in modo smarginato, NON decorrenti$q1$,$q1$Cappello: Clitocybe dealbata da bianco-gesso a giallo-crema, liscio/pruinoso, da piano a depresso — Marasmius oreades color cuoio con umbone ottuso, igrofano$q1$,$q1$Gambo: Marasmius oreades tenace-flessibile, cartilagineo-fibroso — Clitocybe dealbata più fibroso e fragile$q1$,$q1$Test di rivitalizzazione: il Marasmius oreades rivive dopo l'essiccazione — la Clitocybe dealbata no$q1$]::text[],true),
($q1$marasmius_oreades$q1$,$q1$clitocybe_rivulosa$q1$,$q1$it$q1$,$q1$Marasmius oreades: cappello da brunastro a giallo con umbone ottuso, lamelle pallide distanziate, gambo tenace e flessibile. Clitocybe rivulosa: cappello da bianco-piombo a grigio-crema, spesso depresso/imbutiforme, lamelle fitte e decorrenti.$q1$,$q1$Marasmius oreades: gradevolmente speziato di chiodi di garofano/mandorla amara (nota di acido cianidrico) — ATTENZIONE: circa il 25% delle persone, per ragioni genetiche, NON può percepire questo odore, quindi non è un carattere a sé stante. Clitocybe rivulosa: da farinoso a inodore. Usare l'odore solo come conferma aggiuntiva, mai come unica prova di sicurezza.$q1$,$q1$Entrambi crescono nella STESSA stazione: prati, pascoli, tappeti erbosi in giardini/parchi, entrambi formano cerchi delle streghe — nessuna separazione possibile in base alla stazione. Questo aumenta enormemente il rischio di confusione.$q1$,$q1$Entrambi hanno sporata BIANCA — la sporata NON distingue questi due. Restano decisivi l'inserzione delle lamelle (decorrenti vs. distanziate/smarginate) e il gambo tenace.$q1$,$q1$Regola d'oro sul prato: controllare le lamelle. Il Marasmius oreades ha lamelle DISTANZIATE, NON decorrenti, e un gambo tenace e flessibile. Se le lamelle sono fitte e decorrono lungo il gambo — lasciarlo stare (sospetto di Clitocybe contenente muscarina). Il gradevole odore di chiodo di garofano è solo una conferma aggiuntiva (un quarto delle persone non lo sente).$q1$,array[$q1$Lamelle (IL carattere principale): la Clitocybe rivulosa ha lamelle fitte, brevemente DECORRENTI (decorrenti) lungo il gambo — il Marasmius oreades ha lamelle DISTANZIATE (distanti), inserite in modo smarginato al gambo, NON decorrenti$q1$,$q1$Gambo: il gambo del Marasmius oreades è tenace, flessibile, cartilagineo-fibroso (si può torcere senza spezzarsi) — il gambo della Clitocybe è fragile$q1$,$q1$Cappello: la Clitocybe da bianco-piombo/grigio-crema, igrofano, spesso depresso/imbutiforme — il Marasmius oreades da bruno-cuoio a giallo con umbone ottuso$q1$,$q1$Test di rivitalizzazione: i corpi fruttiferi del Marasmius oreades rivivono dopo l'essiccazione (tipico dei Marasmius) — la Clitocybe no$q1$]::text[],true),
($q1$marasmius_oreades$q1$,$q1$inocybe_erubescens$q1$,$q1$it$q1$,$q1$Inocybe erubescens: cappello conico-umbonato, lacerato radialmente, biancastro e che con il tempo/la pressione vira al rosso-mattone, lamelle che scuriscono (da oliva-rosa a brunastre). Marasmius oreades: cappello liscio color cuoio con umbone ottuso, lamelle distanziate che restano pallide.$q1$,$q1$Marasmius oreades gradevolmente speziato (chiodo di garofano/mandorla amara; non percepibile da circa il 25%). Inocybe erubescens debolmente fruttato, da vecchio sgradevolmente dolciastro-spermatico. L'odore solo come aggiunta, mai da solo.$q1$,$q1$L'Inocybe erubescens cresce, amante del calcare, soprattutto in boschi di latifoglie/misti, parchi e sotto cespugli (micorriza con faggio/tiglio), in parte anche su tappeti erbosi — non principalmente in prato aperto come il Marasmius oreades. La stazione aiuta, ma NON è un carattere di sicurezza a sé stante (possibile anche su tappeti erbosi/prati di parco).$q1$,$q1$DECISIVO e salvavita: l'Inocybe erubescens ha sporata bruno-scura — il Marasmius oreades bianca. Una sporata distingue i due in modo inequivocabile.$q1$,$q1$Controllo della sporata come salvavita: bianca = possibile Marasmius oreades, bruna = NON mangiare MAI. Inoltre smascherano il mortale Inocybe erubescens: il cappello fessurato-radialmente fibroso, il viraggio al rosso-mattone (sotto pressione) e l'odore spermatico. Muscarina — quantità mortale già a partire da circa 40-500 g di fungo fresco.$q1$,array[$q1$Sporata (DECISIVA): l'Inocybe erubescens ha sporata BRUNO-SCURA, le lamelle virano da bianco/crema attraverso grigio-oliva-rosa fino a brunastro-macchiato — il Marasmius oreades ha sporata BIANCA e lamelle che restano pallide$q1$,$q1$Arrossamento: l'Inocybe erubescens arrossa al rosso-mattone (cappello/gambo/carne, soprattutto sotto pressione e da vecchio) — il Marasmius oreades NON arrossa$q1$,$q1$Superficie del cappello: l'Inocybe erubescens conico-umbonato, fibroso-radiale e fessurato/lacerato ('Risspilz') — il Marasmius oreades liscio, igrofano, con umbone ottuso$q1$,$q1$Odore: l'Inocybe erubescens spermatico/fruttato-sgradevole — il Marasmius oreades speziato di chiodi di garofano/mandorla amara$q1$]::text[],true),
($q1$marone$q1$,$q1$flockenstieliger_hexenpilz$q1$,$q1$it$q1$,$q1$Marone (Imleria badia): bruno, viraggio leggero al blu. Boleto dal gambo fioccoso (Neoboletus): bruno, viraggio rapido e intenso al blu, punti rossi.$q1$,null,$q1$Entrambi nel bosco$q1$,null,$q1$Entrambi commestibili. Il boleto dal gambo fioccoso DEVE essere cotto 15+ min.$q1$,array[$q1$Entrambi funghi commestibili, il boleto dal gambo fioccoso vira al blu PIÙ RAPIDAMENTE$q1$,$q1$Il boleto dal gambo fioccoso ha puntini rossi sul gambo$q1$]::text[],true),
($q1$morchella_elata$q1$,$q1$fliegenpilz-grosspilz$q1$,$q1$it$q1$,$q1$La spugnola è alveolata/regolare, mentre la girella (Gyromitra) è cerebriforme-irregolare.$q1$,$q1$entrambe aspecifiche$q1$,$q1$entrambe in primavera, su zone bruciate/boschi golenali/boschi di conifere$q1$,$q1$nessuna sporata lamellare (funghi ascomiceti)$q1$,$q1$La girella primaverile (Gyromitra esculenta) è altamente tossica (potenzialmente mortale). Taglio longitudinale: completamente cava (spugnola) vs. ovattata-camerata (girella).$q1$,array[$q1$Spugnola appuntita (Morchella elata): cappello alveolato-fossettato, cappello e gambo completamente cavi$q1$,$q1$Girella primaverile (Gyromitra esculenta): contorta in modo cerebriforme, gambo camerato (non cavo), giromitrina (altamente tossica)$q1$]::text[],true),
($q1$parasol$q1$,$q1$amanita_pantherina$q1$,$q1$it$q1$,$q1$Mazza di tamburo (parasol): cappello bruno chiaro, gambo zebrato a pelle di serpente. Tignosa bigia (Amanita pantherina): bruna con verruche bianche, gambo bianco con bulbo.$q1$,$q1$Mazza di tamburo (parasol): nocciolato, gradevole. Tignosa bigia (Amanita pantherina): odore di ravanello.$q1$,$q1$Mazza di tamburo (parasol): prati, margini del bosco. Tignosa bigia (Amanita pantherina): bosco di latifoglie.$q1$,$q1$Entrambe bianca.$q1$,$q1$Test della MAZZA DI TAMBURO: anello mobile-scorrevole, gambo zebrato. In presenza di verruche NON mangiarla MAI.$q1$,array[$q1$Anello della mazza di tamburo (parasol) MOBILE, anello della tignosa bigia (Amanita pantherina) fisso$q1$,$q1$Mazza di tamburo (parasol) con gambo zebrato, tignosa bigia (Amanita pantherina) con gambo bianco-liscio$q1$,$q1$La tignosa bigia (Amanita pantherina) ha un bulbo con 2-3 cercini$q1$]::text[],true),
($q1$parasol$q1$,$q1$chlorophyllum_brunneum$q1$,$q1$it$q1$,$q1$Zebratura del gambo (mazza di tamburo/parasol sì) + arrossamento (lepiota tossica/Chlorophyllum sì) + bulbo.$q1$,$q1$entrambi aspecifico$q1$,$q1$Mazza di tamburo (parasol) bosco/prato; lepiota tossica (Chlorophyllum) spesso su compost/giardino$q1$,$q1$entrambi bianco-crema$q1$,$q1$Veleno gastrointestinale. Gambo zebrato + nessun arrossamento = mazza di tamburo (parasol); gambo liscio + viraggio rosso zafferano = giù le mani.$q1$,array[$q1$Mazza di tamburo (parasol): gambo zebrato (a pelle di serpente), doppio anello scorrevole, la carne NON arrossa$q1$,$q1$Lepiota tossica (Chlorophyllum): gambo liscio, bulbo marginato, la carne/le lamelle virano al rosso zafferano$q1$]::text[],true),
($q1$roetling$q1$,$q1$agaricus_xanthodermus$q1$,$q1$it$q1$,$q1$Prataiolo giallescente (Agaricus xanthodermus): cappello da bianco a bianco gesso, da giovane sferico/emisferico, poi appianato, liscio fino a finemente squamoso; la base del gambo, nel taglio longitudinale, vira SUBITO a giallo cromo brillante. Prataiolo (Schaf-Champignon, Agaricus arvensis): cappello bianco crema, sericeo-fibrilloso fino a leggermente squamoso, da convesso a piano; ingiallisce su tutto il fungo solo debolmente e senza la macchia concentrata di giallo cromo alla base del gambo.$q1$,$q1$Carattere decisivo: il prataiolo (Schaf-Champignon, Agaricus arvensis) ha un odore gradevole di anice/marzapane. Il prataiolo giallescente (Agaricus xanthodermus) ha un odore sgradevole di inchiostro/fenolo/carbolo (medicinale-iodato); l'odore si intensifica strofinando la base del gambo e soprattutto con il riscaldamento/la cottura.$q1$,$q1$Prataiolo giallescente (Agaricus xanthodermus): giardini, parchi, margini del bosco, cumuli di compost, superfici ruderali/vicine agli insediamenti. Prataiolo (Schaf-Champignon, Agaricus arvensis): prati e pascoli concimati, soprattutto pascoli di pecore e cavalli. L'habitat da solo NON consente una distinzione sicura (possibile sovrapposizione).$q1$,$q1$In entrambe le specie da bruno cioccolato scuro a bruno porpora (genere Agaricus) - NESSUN carattere distintivo.$q1$,$q1$Tagliare longitudinalmente la base del gambo: se vira subito a giallo cromo intenso E il fungo odora di inchiostro/carbolo invece che di anice, lasciarlo stare - prataiolo giallescente (Agaricus xanthodermus). Regola pratica: ogni prataiolo con odore di carbolo/inchiostro o con base del gambo giallo cromo brillante = tossico, non mangiare.$q1$,array[$q1$L'odore è il carattere più importante: il prataiolo (Schaf-Champignon, Agaricus arvensis) profuma gradevolmente di anice/marzapane; il prataiolo giallescente (Agaricus xanthodermus) odora sgradevolmente di inchiostro/carbolo/fenolo - si intensifica strofinando la base del gambo e con il riscaldamento.$q1$,$q1$Tagliare longitudinalmente la base del gambo: il prataiolo giallescente (Agaricus xanthodermus) vira SUBITO a giallo cromo intenso, concentrato alla base del gambo; il prataiolo (Schaf-Champignon, Agaricus arvensis) ingiallisce su tutto il carpoforo solo debolmente e non concentrato alla base del gambo.$q1$,$q1$Entrambi hanno anello e lamelle che maturano da rosa pallido a bruno cioccolato, ed entrambi hanno sporata bruno scuro - perciò distinguono con sicurezza SOLO il taglio della base del gambo (giallo cromo) E il test dell'odore, non le lamelle o il colore delle spore.$q1$]::text[],true),
($q1$roetling$q1$,$q1$amanita_phalloides$q1$,$q1$it$q1$,$q1$Tignosa verdognola/falloide (Amanita phalloides): cappello da verde oliva/giallo-verdognolo con fibrille radiali innate (la forma bianca var. alba anche bianca pura), lamelle BIANCHE PURE, base del gambo bulbosa con guaina membranosa (volva). Prataiolo (Schaf-Champignon, Agaricus arvensis): cappello bianco crema, lamelle da rosa -> bruno cioccolato, NESSUNA guaina membranosa.$q1$,$q1$Prataiolo (Schaf-Champignon, Agaricus arvensis): gradevole odore di anice/marzapane. Tignosa verdognola/falloide (Amanita phalloides): da giovane dolciastro-mielato, da vecchio sgradevole - NESSUN anice.$q1$,$q1$Amanita phalloides: fungo micorrizico prevalentemente presso querce e faggi nel bosco. Prataiolo (Schaf-Champignon, Agaricus arvensis): isolato su prati e pascoli senza legame con gli alberi. L'habitat da solo NON è un carattere sicuro.$q1$,$q1$DECISIVO: il prataiolo (Schaf-Champignon, Agaricus arvensis) da bruno cioccolato scuro a bruno porpora; Amanita phalloides BIANCA PURA. Sporata bianca = non mangiare mai.$q1$,$q1$Non raccogliere mai 'prataioli' giovani, ancora chiusi, bianchi e con lamelle chiare - proprio allo stadio di bottone la mortale tignosa falloide somiglia di più al prataiolo. Dissotterrare completamente la base del gambo (volva presente?) e considerare le lamelle bianche pure e la sporata bianca come segnale di stop assoluto.$q1$,array[$q1$Lamelle: la tignosa verdognola/falloide (Amanita phalloides) ha sempre lamelle BIANCHE PURE; le lamelle del prataiolo sono da giovani rosa pallido (i bottoni molto giovani eccezionalmente bianco-crema) e maturano attraverso il grigio-rosa fino al bruno cioccolato. Allo stadio di bottone non fidarsi del solo colore delle lamelle - allora volva + sporata obbligatori.$q1$,$q1$Base del gambo: bulbo nettamente distinto con guaina membranosa (volva) nella tignosa falloide; nel prataiolo manca la volva. Dissotterrare sempre completamente la base del gambo.$q1$,$q1$NON usare il colore del cappello come carattere principale: tipicamente verde oliva/giallo-verdognolo, ma come var. alba anche bianco puro - perciò controllare sempre lamelle + volva + sporata, mai solo il colore.$q1$,$q1$Sporata bianca (prataiolo bruno scuro) - il carattere singolo più affidabile.$q1$]::text[],true),
($q1$russula_virescens$q1$,$q1$amanita_phalloides$q1$,$q1$it$q1$,$q1$Colorazione verde simile, soprattutto da giovane; la cuticola della russola si screpola a placche (areolata).$q1$,$q1$Russola dolce/nocciolata; tignosa verdognola (Amanita phalloides) odore mielato (da vecchia)$q1$,$q1$entrambe bosco di latifoglie$q1$,$q1$Russola bianca, A. phalloides bianca$q1$,$q1$MORTALE. Con i funghi verdi estrarre SEMPRE il fungo intero: mancano anello E volva? Altrimenti non mangiare.$q1$,array[$q1$Russola: lamelle fragili, NESSUN anello, NESSUN bulbo/volva$q1$,$q1$Tignosa verdognola (Amanita phalloides): anello + volva membranosa su base bulbosa, lamelle flessibili$q1$]::text[],true),
($q1$russula_cyanoxantha$q1$,$q1$amanita_phalloides$q1$,$q1$it$q1$,$q1$Esemplari violetto-verdastri otticamente confondibili; decisive la prova delle lamelle (flessibili vs. non flessibili) + la base del gambo.$q1$,$q1$Russola dolce$q1$,$q1$entrambe bosco di latifoglie (faggio/quercia)$q1$,$q1$entrambe bianche$q1$,$q1$MORTALE. Liberare la base del gambo: ogni bulbo con guaina membranosa = pericolo di vita.$q1$,array[$q1$Russola maggiore (R. cyanoxantha): lamelle flessibili-lardacee (non si frantumano), NESSUN anello, NESSUNA volva$q1$,$q1$Tignosa verdognola (Amanita phalloides): anello + volva, amatossine mortali$q1$]::text[],true),
($q1$roetling$q1$,$q1$amanita_verna$q1$,$q1$it$q1$,$q1$Tignosa primaverile (Amanita verna): cappello bianco puro, lamelle BIANCO PURO (anche da vecchio), base del gambo con guaina bulbosa, membranosa, a sacco (volva), spesso profonda nel terreno. Prataiolo (Agaricus): cappello bianco crema, lamelle che maturano da rosa -> grigio-rosa -> bruno cioccolato, NESSUNA volva, al massimo base del gambo leggermente ingrossata.$q1$,$q1$Prataiolo: gradevole odore di anice/marzapane. Amanita verna: pressoché inodore fino a leggermente dolciastro/mielato, da vecchia sgradevole - NESSUN anice.$q1$,$q1$Amanita verna: fungo micorrizico, cresce nel bosco (bosco di latifoglie/misto), soprattutto in primavera, in simbiosi con gli alberi. Prataiolo: saprofita su prati e pascoli aperti senza legame con gli alberi. Attenzione: l'habitat da solo NON è un carattere sicuro.$q1$,$q1$DECISIVO e affidabile al 100 %: prataiolo bruno-cioccolato scuro fino a bruno-purpureo; Amanita verna BIANCO PURO. Con sporata bianca NON mangiare MAI come prataiolo.$q1$,$q1$Con ogni 'prataiolo' bianco estrarre e liberare SEMPRE completamente la base del gambo: se si trova una guaina bulbosa membranosa (volva) OPPURE le lamelle restano bianco puro - pericolo di vita, lasciare stare. In caso di dubbio fare la sporata: bianca = tignosa (Amanita), non mangiare mai. I giovani bottoni bianchi chiusi non raccoglierli nemmeno.$q1$,array[$q1$Lamelle: Amanita verna ha in OGNI età lamelle bianco puro; il prataiolo le ha da giovane rosa pallido (i bottoni molto giovani possono essere bianco-crema!), poi grigio-rosa fino a bruno cioccolato. IMPORTANTE: allo stadio di bottone il colore delle lamelle da solo NON è sicuro - allora verificare obbligatoriamente volva + sporata.$q1$,$q1$Base del gambo: Amanita verna ha un bulbo nettamente distinto con guaina membranosa a sacco (volva); il prataiolo NON ha volva. Estrarre sempre completamente anche la base del gambo - la volva si trova spesso in profondità nel terreno.$q1$,$q1$Sporata: prataiolo bruno scuro, Amanita verna bianco puro - la sporata è il carattere singolo più affidabile.$q1$,$q1$Odore: prataiolo odore di anice; Amanita verna senza odore di anice (neutro fino a dolciastro-mielato) - l'assenza dell'odore di anice è un segnale d'allarme, ma non sostituisce MAI la verifica di volva/sporata.$q1$]::text[],true),
($q1$russula_vesca$q1$,$q1$russula_emetica$q1$,$q1$it$q1$,$q1$R. vesca: rosso-carne opaco fino a rosso-vinato/bruno-rossastro, spesso scolorita e macchiata in modo irregolare, con cuticola del bordo del cappello retratta (troppo corta), così che i bordi delle lamelle sporgono a denti. R. emetica: rosso-ciliegia/sangue uniforme e brillante, viscida e lucida con l'umidità, con cuticola che copre fino al bordo e si stacca ampiamente (spesso fino al centro del cappello).$q1$,$q1$Entrambe perlopiù poco appariscenti/leggermente fruttate; l'odore NON distingue queste due specie. Decisivo è il sapore (dolce vs. bruciante-acre).$q1$,$q1$R. emetica: boschi umidi/acidi di torbiera e di conifere (abete rosso, pino, abete bianco), spesso muscosi. R. vesca: bosco di latifoglie e misto presso faggio e quercia, suoli piuttosto freschi fino a secchi.$q1$,$q1$Entrambe bianca fino a biancastra - la sporata NON distingue queste due specie. Non usarla per la distinzione.$q1$,$q1$Prova di sapore secondo la regola delle russole: masticare un pezzetto di cappello con lamelle, sputare, non ingoiare - dolce = russola commestibile, acre/bruciante = russola emetica (velenosa, scartare). La regola vale SOLO se il fungo è riconosciuto senza dubbio come russola (lamelle fragili-friabili che si frantumano, nessun anello al gambo, nessuna volva). R. emetica non è mortale, ma provoca per giorni violenti disturbi gastrointestinali.$q1$,array[$q1$Sapore (regola delle russole, il carattere distintivo decisivo): R. vesca è dolce e gradevolmente nocciolata; R. emetica ha sapore subito bruciante-acre/pepato. Masticare brevemente un pezzetto di cappello con lamelle, NON ingoiare, sputare completamente - applicare solo se il fungo è riconosciuto senza dubbio come russola (lamelle fragili-friabili, nessun anello, nessuna volva).$q1$,$q1$Colore del cappello: R. vesca rosso-carne/vinato opaco fino a bruno-rossastro, spesso scolorita a macchie; R. emetica rosso sangue, ciliegia fino a purpureo brillante, appiccicosa-lucida con l'umidità.$q1$,$q1$Cuticola accorciata (carattere distintivo di R. vesca): il bordo del cappello è retratto, così che la carne del cappello e le estremità delle lamelle sporgono a denti oltre il bordo - assente in R. emetica (la cuticola copre fino al bordo e si lascia staccare ampiamente, spesso fino al centro del cappello).$q1$,$q1$Habitat: R. emetica tipica in boschi umidi di torbiera e di conifere (abete rosso, pino, abete bianco, spesso muscosi/acidi); R. vesca soprattutto in bosco di latifoglie/misto presso faggio e quercia.$q1$]::text[],true),
($q1$russula_vesca$q1$,$q1$amanita_phalloides$q1$,$q1$it$q1$,$q1$Decisiva e vincolante è la base del gambo: in A. phalloides una volva membranosa bianca attorno a una base del gambo bulbosa più un anello pendulo e striato; lamelle libere e molli. R. vesca ha una base del gambo che termina diritta, senza bulbo e senza anello, e lamelle fragili-friabili e adnate. Il colore NON è un criterio affidabile: phalloides è perlopiù verde-oliva/verde-giallastra (anche bianca come var. alba); il colore rosso-carne di vesca è al massimo un indizio. La tipica confusione di colore della tignosa verdognola riguarda le russole commestibili VERDI, non la vesca rossa - perciò assicurarsi sempre morfologicamente alla base del gambo.$q1$,$q1$La tignosa verdognola più vecchia odora di dolciastro come miele artificiale fino a sgradevole; la russola commestibile odora di dolce/poco appariscente. L'odore è SOLO un indizio, mai il criterio di sicurezza.$q1$,$q1$Entrambi funghi micorrizici presso latifoglie (quercia, faggio, castagno) - l'habitat NON li distingue in modo affidabile, quindi è obbligatoria la verifica morfologica alla base del gambo.$q1$,$q1$Entrambe bianca - la sporata NON distingue queste specie e non deve servire da rassicurazione.$q1$,$q1$Estrarre SEMPRE il fungo intero con la base del gambo (non tagliare!) e verificare bulbo + volva membranosa bianca + anello al gambo. Se si trova volva/bulbo/anello oppure le lamelle sono molli e libere, NON è una russola - non applicare la regola delle russole/prova di sapore, poiché le amatossine hanno sapore DOLCE e sono mortali. Il colore non è mai il criterio. In Svizzera: in caso di qualsiasi dubbio recarsi al controllo ufficiale dei funghi VAPKO.$q1$,array[$q1$Bulbo/volva alla base del gambo: A. phalloides ha SEMPRE una guaina bianca membranosa, a sacco (volva) attorno a un bulbo evidente - le russole non hanno MAI una volva né un bulbo. Questo è il criterio vincolante, il colore NON lo è.$q1$,$q1$Anello al gambo: A. phalloides porta un anello pendulo, membranoso e striato (manicotto) nella parte alta del gambo - le russole sono prive di anello.$q1$,$q1$Lamelle: russola = lamelle fragili-friabili, che si frantumano, adnate al gambo (a lamelle fragili); A. phalloides = lamelle molli, flessibili, LIBERE (non adnate al gambo). Qui la prova di sapore fallisce, perché le amatossine hanno sapore DOLCE/nocciolato!$q1$,$q1$Colore del cappello come debole indizio: A. phalloides è bianco-verde/verde/oliva/verde-giallastra (raramente bianca, var. alba) - il colore rosso-carne/vinato di R. vesca NON corrisponde, ma non sostituisce mai la verifica della base del gambo. La classica confusione di colore riguarda le russole VERDI, non la russola commestibile rossa.$q1$]::text[],true),
($q1$schopftintling$q1$,$q1$amanita_phalloides$q1$,$q1$it$q1$,$q1$Coprino chiomato: bianco-squamoso, ovoidale. Amanita falloide (Amanita phalloides): verde oliva, liscia.$q1$,null,$q1$Coprino chiomato: prati, bordi dei sentieri. Amanita falloide: bosco di latifoglie.$q1$,$q1$Coprino chiomato: nera. Amanita falloide: bianca.$q1$,$q1$Le lamelle del coprino chiomato diventano nere, quelle dell'Amanita falloide MAI.$q1$,array[$q1$Coprino chiomato: cappello ovoidale, squamoso; Amanita falloide liscia$q1$,$q1$Coprino nei prati, Amanita falloide nel bosco$q1$]::text[],true),
($q1$semmelstoppelpilz$q1$,$q1$austernpilz$q1$,$q1$it$q1$,$q1$Steccherino dorato sul terreno, nel bosco misto. Gelone (orecchione) sul tronco d'albero.$q1$,null,$q1$Terreno contro albero$q1$,null,$q1$Entrambi adatti ai principianti.$q1$,array[$q1$Lo steccherino ha ACULEI, il gelone (orecchione) ha LAMELLE$q1$,$q1$Terreno contro tronco d'albero$q1$]::text[],true),
($q1$steinpilz$q1$,$q1$butterpilz$q1$,$q1$it$q1$,$q1$Porcino: gambo con reticolo bianco, senza anello. Pinarolo: cappello vischioso, con anello.$q1$,null,$q1$Entrambi nel bosco di conifere, il pinarolo sotto il pino silvestre.$q1$,null,$q1$Staccare la pellicola del cappello del pinarolo.$q1$,array[$q1$Porcino: gambo liscio; pinarolo: anello + cappello vischioso$q1$]::text[],true),
($q1$steinpilz$q1$,$q1$tylopilus_felleus$q1$,$q1$it$q1$,$q1$Colore dei tubuli (bianco/giallo contro rosa) + reticolo (fine-bianco contro grossolano-scuro).$q1$,$q1$Il boleto del fiele (Tylopilus felleus) è estremamente amaro (assaggio minimo, sputare).$q1$,$q1$Entrambi in boschi acidi di conifere/misti, spesso insieme.$q1$,$q1$Porcino oliva, boleto del fiele rosa.$q1$,$q1$Non velenoso, ma un solo boleto del fiele rovina un intero piatto. Tubuli rosa + reticolo grossolano + amarezza lo smascherano.$q1$,array[$q1$Porcino: reticolo bianco fine, tubuli bianchi/gialli, dolce$q1$,$q1$Boleto del fiele: reticolo scuro grossolano, tubuli rosa, estremamente amaro$q1$]::text[],true),
($q1$zigeunerpilz$q1$,$q1$cortinarius_orellanus$q1$,$q1$it$q1$,$q1$Cortinario brunastro (Reifpilz): cappello giallo paglierino-bruno giallastro, pruinoso grigio-biancastro-lilla, rugoso longitudinalmente, con anello membranoso a doppio bordo. Cortinario arancio-fulvo (Cortinarius orellanus): cappello da arancio intenso a bruno ramato/ruggine, opaco-fibroso fino a finemente squamoso, secco, SENZA pruina; NESSUN vero anello, solo una cortina fugace; gambo cilindrico, dello stesso colore o giallastro, non marcatamente zigrinato (a differenza di rubellus).$q1$,$q1$Cortinario brunastro: mite. Cortinario arancio-fulvo: debolmente di ravanello.$q1$,$q1$Cortinario brunastro: bosco di conifere e (raramente) di latifoglie, spesso suolo acido e sabbioso, presso il mirtillo. Cortinario arancio-fulvo: boschi di latifoglie in posizioni calde presso quercia, faggio, nocciolo, castagno, su suoli da acidi a basici (luglio-ottobre) — tipicamente non in bosco di conifere.$q1$,$q1$Cortinario brunastro: bruno cannella chiaro/giallo ruggine. Cortinario arancio-fulvo: bruno ruggine. Nessun singolo carattere distintivo affidabile.$q1$,$q1$Consumare il cortinario brunastro solo con un anello fermo e ben definito a doppio bordo. Un cappello arancio/bruno ruggine intenso, secco-fibroso, SENZA pruina e senza vero anello (solo fibre del velo) indica il mortale cortinario arancio-fulvo — non toccarlo, portarlo al controllo dei funghi (VAPKO).$q1$,array[$q1$Il cortinario brunastro possiede un anello membranoso fermo sul gambo con doppio bordo; il cortinario arancio-fulvo NON ha un vero anello, ma solo fibre fugaci del velo (cortina).$q1$,$q1$Il cappello del cortinario brunastro è pruinoso grigio-lilla e rugoso; il cappello del cortinario arancio-fulvo è secco-fibroso fino a finemente squamoso e uniformemente arancio/ramato/bruno ruggine intenso, senza pruina.$q1$,$q1$Il gambo del cortinario arancio-fulvo è dello stesso colore fino a giallastro e non marcatamente zigrinato; il gambo del cortinario brunastro porta il manicotto membranoso a doppio bordo.$q1$,$q1$Il veleno orellanina è resistente al calore e all'essiccazione e provoca, dopo una latenza di giorni-settimane (3-14 giorni), un'insufficienza renale mortale — nessun test d'assaggio e nessuna disintossicazione tramite cottura possibile.$q1$]::text[],true),
($q1$zigeunerpilz$q1$,$q1$cortinarius_rubellus$q1$,$q1$it$q1$,$q1$Cortinario violaceo-bruno (Reifpilz/Rozites caperatus): cappello da giallo paglierino a giallo-bruno con una pruinosità (velo) grigio-biancastro-lillacina, superficie caratteristicamente rugosa/solcata in senso longitudinale, anello del gambo nettamente membranoso con doppio margine. Cortinarius rubellus: cappello da giallo ad arancio o rosso-volpino-cannella, secco e finemente feltrato, con umbone appuntito (o arrotondato), SENZA un vero anello (solo resti fugaci di cortina/velo), gambo slanciato e giallastro screziato (cinte di velo gialle).$q1$,$q1$Cortinario violaceo-bruno (Reifpilz): gradevole/delicato. Cortinarius rubellus: debolmente rafanoide (di ravanello).$q1$,$q1$Cortinario violaceo-bruno (Reifpilz): bosco di conifere e (raramente) di latifoglie, predilige la presenza di mirtillo su terreno acido e sabbioso, da agosto a ottobre. Cortinarius rubellus: soprattutto bosco di conifere (peccete), spesso in stazioni umide/torbose su terreni acidi, presso il mirtillo — la sovrapposizione di habitat aggrava il rischio.$q1$,$q1$Cortinario violaceo-bruno (Reifpilz): da bruno-cannella chiaro a giallo-ruggine. Cortinarius rubellus: bruno-ruggine. Qui il colore delle spore NON distingue in modo affidabile — non utilizzarlo mai come unico carattere.$q1$,$q1$Cerca sul gambo l'anello membranoso e consistente con il caratteristico DOPPIO margine — se questo anello manca e il gambo è invece giallastro e screziato con sole fibre fugaci di velo, non si tratta del Reifpilz, bensì possibilmente del mortale Cortinarius rubellus. In caso di dubbio, allo stadio giovane rivolgiti SEMPRE all'organo ufficiale di controllo dei funghi (VAPKO).$q1$,array[$q1$Il cortinario violaceo-bruno (Reifpilz) ha un anello del gambo consistente e membranoso con il caratteristico DOPPIO margine; il Cortinarius rubellus NON ha un vero anello, solo fibre fugaci di velo (cortina).$q1$,$q1$Il cappello del cortinario violaceo-bruno (Reifpilz) è opaco, PRUINOSO da grigio-biancastro a lillacino e rugoso in senso longitudinale; il Cortinarius rubellus ha un cappello secco, finemente feltrato-fibrilloso, rosso-volpino-cannella, con un netto umbone APPUNTITO.$q1$,$q1$Il gambo del Cortinarius rubellus è slanciato e giallastro SCREZIATO (cinte di velo gialle); il gambo del cortinario violaceo-bruno (Reifpilz) è più spesso e porta il manicotto membranoso anziché le cinte.$q1$,$q1$Consumare solo in presenza inequivocabile dell'anello a doppio margine; il veleno orellanina è stabile al calore e all'essiccazione e provoca, dopo una latenza di 2-21 giorni, un'insufficienza renale irreversibile — nessuna cottura/essiccazione lo disintossica.$q1$]::text[],true)
