-- v29.74 · mushroom_lookalikes_i18n — EN/ES/FR/IT-Übersetzungen der Verwechsler-Differenztexte
-- 6 Felder (visual/smell/habitat/spore_print_differences, pro_tip, key_differences[]) × 46 Paare × 4 Sprachen.
-- DE-Quelle bleibt in mushroom_lookalikes. translate+adversarial-safety-Verify (Zuordnung Speisepilz↔Doppelgänger
-- nicht invertiert, lat. Artnamen/VAPKO/145 erhalten — HL#24/#25).
create table if not exists public.mushroom_lookalikes_i18n (
  edible_slug text not null, lookalike_slug text not null, lang text not null,
  visual_differences text, smell_differences text, habitat_differences text,
  spore_print_differences text, pro_tip text, key_differences text[],
  verified boolean not null default false, created_at timestamptz not null default now(),
  primary key (edible_slug, lookalike_slug, lang),
  foreign key (edible_slug, lookalike_slug) references public.mushroom_lookalikes(edible_slug, lookalike_slug) on delete cascade
);
alter table public.mushroom_lookalikes_i18n enable row level security;
drop policy if exists "mushroom_lookalikes_i18n_read" on public.mushroom_lookalikes_i18n;
create policy "mushroom_lookalikes_i18n_read" on public.mushroom_lookalikes_i18n for select to anon, authenticated using (true);
revoke insert, update, delete on public.mushroom_lookalikes_i18n from anon, authenticated, public;

on conflict (edible_slug, lookalike_slug, lang) do update set
  visual_differences=excluded.visual_differences, smell_differences=excluded.smell_differences,
  habitat_differences=excluded.habitat_differences, spore_print_differences=excluded.spore_print_differences,
  pro_tip=excluded.pro_tip, key_differences=excluded.key_differences, verified=true;

